class CalendarHomeScreen extends StatefulWidget {
  const CalendarHomeScreen({super.key});

  @override
  State<CalendarHomeScreen> createState() => _CalendarHomeScreenState();
}

class _CalendarHomeScreenState extends State<CalendarHomeScreen> {
  int selectedLiveryIndex = 0;
  final Map<int, int> bestPositionByRound = {};
  final Map<int, int> pointsByRound = {};

  int get totalPoints => pointsByRound.values.fold(0, (a, b) => a + b);

  @override
  void initState() {
    super.initState();
    UltraTextures.ensureLoaded();
    SystemChrome.setPreferredOrientations([
      DeviceOrientation.portraitUp,
      DeviceOrientation.landscapeLeft,
      DeviceOrientation.landscapeRight,
    ]);
  }

  void _openSettingsDialog() {
    final TeamLivery livery = kLiveries[selectedLiveryIndex];
    showDialog<void>(
      context: context,
      builder: (ctx) {
        return StatefulBuilder(
          builder: (dialogCtx, setDialogState) {
            final int sensPct = (RaceEngineState.steerSensitivity * 100.0).round();
            final String sensDesc = RaceEngineState.sensitivityLabel(RaceEngineState.steerSensitivity);
            return AlertDialog(
              backgroundColor: const Color(0xFF0E1422),
              shape: RoundedRectangleBorder(
                borderRadius: BorderRadius.circular(18),
                side: BorderSide(color: livery.primary, width: 1.8),
              ),
              title: const Row(
                children: [
                  Icon(Icons.tune, color: Color(0xFF00E5FF), size: 22),
                  SizedBox(width: 8),
                  Text('AJUSTES', style: TextStyle(fontSize: 17, fontWeight: FontWeight.w900, letterSpacing: 1.2)),
                ],
              ),
              content: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Container(
                      padding: const EdgeInsets.fromLTRB(12, 10, 12, 6),
                      decoration: BoxDecoration(
                        color: const Color(0xFF151E30),
                        borderRadius: BorderRadius.circular(12),
                        border: Border.all(color: const Color(0xFF283754)),
