                            mainAxisAlignment: MainAxisAlignment.spaceBetween,
                            children: [
                              const Text('50% Suave', style: TextStyle(fontSize: 10, color: Colors.white54)),
                              GestureDetector(
                                onTap: () {
                                  setDialogState(() {
                                    RaceEngineState.steerSensitivity = 1.20;
                                  });
                                },
                                child: const Text(
                                  'Restablecer (120%)',
                                  style: TextStyle(fontSize: 10, fontWeight: FontWeight.bold, color: Color(0xFFFFD54F)),
