      MaterialPageRoute(
        builder: (_) => CockpitRaceScreen(
          circuit: circuit,
          livery: kLiveries[selectedLiveryIndex],
        ),
      ),
    );

    if (result != null && mounted) {
      setState(() {
        final int prevBest = bestPositionByRound[circuit.round] ?? 99;
        if (result.position < prevBest) {
          bestPositionByRound[circuit.round] = result.position;
        }
        final int prevPts = pointsByRound[circuit.round] ?? 0;
        if (result.points > prevPts) {
          pointsByRound[circuit.round] = result.points;
        }
      });

      if (result.nextRound && circuit.round < 24) {
        _startWeekend(kAll24Circuits[circuit.round]);
      }
    }
