class CircuitPreviewPainter extends CustomPainter {
  final List<Offset> waypoints;
  final Color accent;

  CircuitPreviewPainter({required this.waypoints, required this.accent});

  @override
  void paint(Canvas canvas, Size size) {
    if (waypoints.length < 3) return;
    final double cx = size.width * 0.5;
    final double cy = size.height * 0.5;
    final double r = min(size.width, size.height) * 0.46;

    final Path path = Path();
    for (int i = 0; i < waypoints.length; i++) {
      final double x = cx + waypoints[i].dx * r;
      final double y = cy + waypoints[i].dy * r;
      if (i == 0) {
        path.moveTo(x, y);
      } else {
        path.lineTo(x, y);
      }
    }
    path.close();

    canvas.drawPath(
      path,
      Paint()
        ..isAntiAlias = true
        ..color = Colors.white70
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.0
        ..strokeJoin = StrokeJoin.round,
    );
    canvas.drawCircle(
      Offset(cx + waypoints[0].dx * r, cy + waypoints[0].dy * r),
      2.6,
      Paint()..isAntiAlias = true..color = accent,
    );
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
}

