/// Core 120FPS Simulation State: 1-Lap Qualifying + Starting Grid + Precision Swept Collisions + Smart AI
class RaceEngineState extends ChangeNotifier {
  static const int totalLaps = 5;
  static const int totalCars = 22;

  // Shared 1:1 real-meter visual & physics scale: real F1 car = 2.00m wide -> 1.88 world X units (0.94 units/meter)!
  static const double kMetersToWorldX = 0.94;
  static const double kCarLengthOverlapBack = -2.4; // Side-by-side rear wheel contact
  static const double kCarLengthOverlapFront = 3.6; // Front wing into rival rear diffuser
  static const double kGridSpacing = 12.0;

  final CircuitInfo circuit;

  // Dynamic 1:1 per-circuit real FIA width, asymmetric left/right barrier runoff & exact tire-to-tire collision width!
  double get trackHalfWidthMeters => circuit.trackWidthMeters * 0.5;
  double get roadHalfWorldX => trackHalfWidthMeters * kMetersToWorldX;
  double get laneToWorldX => roadHalfWorldX;
  double get carCollisionDxLane => (2.04 / trackHalfWidthMeters).clamp(0.25, 0.50).toDouble();

  double wallLimitLaneLeftAtProgress(double prog) {
    final double runM = geometry.runoffLeftAtProgress(prog);
    return ((trackHalfWidthMeters + runM - 0.92) / trackHalfWidthMeters).clamp(1.03, 9.0).toDouble();
  }

  double wallLimitLaneRightAtProgress(double prog) {
    final double runM = geometry.runoffRightAtProgress(prog);
    return ((trackHalfWidthMeters + runM - 0.92) / trackHalfWidthMeters).clamp(1.03, 9.0).toDouble();
  }

  /// True if the given laneX at prog is inside a gravel trap or grass verge (vs painted FIA tarmac runoff)
  bool isInGravelAt(double laneX, double prog) {
    if (laneX.abs() <= 1.02 || circuit.isStreetCircuit || !circuit.hasGravelTraps) return false;
    final double runM = laneX < 0 ? geometry.runoffLeftAtProgress(prog) : geometry.runoffRightAtProgress(prog);
    final double offM = (laneX.abs() - 1.0) * trackHalfWidthMeters;
    return runM >= 11.5 && offM > (runM * 0.44);
  }

  bool isOnGrassAt(double laneX, double prog) {
    if (laneX.abs() <= 1.02 || circuit.isStreetCircuit) return false;
    if (isInGravelAt(laneX, prog)) return false;
    final double runM = laneX < 0 ? geometry.runoffLeftAtProgress(prog) : geometry.runoffRightAtProgress(prog);
    final double offM = (laneX.abs() - 1.0) * trackHalfWidthMeters;
    return circuit.hasGravelTraps && runM < 11.5 && offM > 2.0;
  }
  final TeamLivery livery;
  final TrackGeometry geometry;
  final Random rng = Random();

  static bool showRacingLine = true;
