      aiDrivers.add(driver);
    }

    poleReferenceTime = aiDrivers.map((a) => a.qualiTimeSec).reduce((a, b) => min(a, b));
  }

  /// Physics-based 1-lap qualifying simulation matched to pro AI pace & 100% manual physics!
  double _simulateAiQualiLap(AiDriver ai) {
    double dist = 0.0;
    double spd = 0.0;
    double t = 0.0;
    const double dt = 0.025;
    final double qualiBaseTop = 300.0 + (ai.skill * 36.0);
    double aiErs = 100.0;

    while (dist < circuit.lapLengthMeters && t < 240.0) {
      final double prog = (dist % circuit.lapLengthMeters) / circuit.lapLengthMeters;
      final double kappaNow = geometry.kappaAtProgress(prog).abs();
      final double vTarget = geometry.targetSpeedAtProgress(prog) * (0.93 + ai.skill * 0.13);
      double desired = min(qualiBaseTop, vTarget);

      if (kappaNow < 0.0055 && desired > 245.0 && aiErs > 4.0) {
        desired = min(362.0, min(desired + 28.0 * ai.skill, vTarget));
        aiErs = max(0.0, aiErs - 11.0 * dt);
      } else {
        aiErs = min(100.0, aiErs + 4.5 * dt);
      }

      if (desired > spd) {
        spd = min(desired, spd + (148.0 + ai.skill * 36.0) * dt);
      } else {
        spd = max(desired, spd - (195.0 + ai.skill * 40.0) * dt);
      }
      dist += (spd / 3.6) * dt;
      t += dt;
    }
    final double variance = (rng.nextDouble() - 0.42) * 0.40;
    return max(10.0, t + variance);
  }

