    if (raceFinished || phase == SessionPhase.gridOverview) return;
    isPaused = !isPaused;
    if (isPaused) {
      resumeCountdownTimer = 0.0;
      _lastResumeCount = 0;
      leftHeld = false;
      rightHeld = false;
      analogSteerTarget = null;
      gasHeld = false;
      brakeHeld = false;
      brakePressure = 0.0;
      F1SoundEngine.stop();
    } else {
      resumeCountdownTimer = 3.0;
      _lastResumeCount = 3;
      F1SoundEngine.playEvent('light');
