  Widget _steerBarIndicator(double totalW) {
    final double ang = engine.steerAngle.clamp(-1.0, 1.0).toDouble();
    final double halfW = totalW * 0.5;
    final double barW = (ang.abs() * halfW).clamp(0.0, halfW).toDouble();
    final double leftPos = ang >= 0.0 ? halfW : (halfW - barW);
    return Container(
      width: totalW,
      height: 5,
      decoration: BoxDecoration(
        color: const Color(0x990A101D),
        borderRadius: BorderRadius.circular(3),
        border: Border.all(color: Colors.white24, width: 0.7),
      ),
      child: Stack(
        children: [
          Positioned(
            left: halfW - 0.75,
            top: 0,
            bottom: 0,
            child: Container(width: 1.5, color: Colors.white38),
          ),
          if (barW > 1.0)
            Positioned(
              left: leftPos,
              top: 0,
              bottom: 0,
              child: Container(
                width: barW,
                decoration: BoxDecoration(
                  color: const Color(0xFF00E5FF),
                  borderRadius: BorderRadius.circular(2.5),
                ),
              ),
            ),
        ],
      ),
    );
  }

  Widget _steerPadWidget() {
    if (RaceEngineState.analogSteeringMode) {
      const double padW = 192.0;
      const double padH = 68.0;
      const double halfW = padW * 0.5;
      final double curSteer = (engine.analogSteerTarget ?? engine.steerAngle).clamp(-1.0, 1.0).toDouble();
      final bool active = _analogSteerPointer != null;

      void updateAnalog(double localDx) {
        final double norm = ((localDx - halfW) / (halfW - 18.0)).clamp(-1.0, 1.0).toDouble();
        // Tiny 4% center deadzone so resting center goes laser-straight
        final double val = norm.abs() < 0.04 ? 0.0 : norm;
        engine.analogSteerTarget = val;
        engine.leftHeld = val < -0.04;
        engine.rightHeld = val > 0.04;
        _hudTick.value++;
      }

      return Listener(
        behavior: HitTestBehavior.opaque,
        onPointerDown: (e) {
          _analogSteerPointer = e.pointer;
          updateAnalog(e.localPosition.dx);
        },
        onPointerMove: (e) {
          if (_analogSteerPointer == e.pointer) {
            updateAnalog(e.localPosition.dx);
          }
        },
        onPointerUp: (e) {
          if (_analogSteerPointer == e.pointer) {
            _analogSteerPointer = null;
            engine.analogSteerTarget = null;
            engine.leftHeld = false;
            engine.rightHeld = false;
            _hudTick.value++;
          }
        },
        onPointerCancel: (e) {
          if (_analogSteerPointer == e.pointer) {
            _analogSteerPointer = null;
            engine.analogSteerTarget = null;
            engine.leftHeld = false;
            engine.rightHeld = false;
            _hudTick.value++;
          }
        },
        child: Column(
          mainAxisSize: MainAxisSize.min,
          children: [
            Container(
              width: padW,
              height: padH,
              decoration: BoxDecoration(
                gradient: LinearGradient(
                  colors: active
                      ? const [Color(0xDD1E3A63), Color(0xDD0E1C36)]
                      : const [Color(0xB8172133), Color(0xB80A0F1A)],
                  begin: Alignment.topCenter,
                  end: Alignment.bottomCenter,
                ),
                borderRadius: BorderRadius.circular(15),
                border: Border.all(color: active ? const Color(0xFF00E5FF) : Colors.white38, width: 1.8),
                boxShadow: const [BoxShadow(color: Color(0x66000000), blurRadius: 6)],
              ),
              child: Stack(
                alignment: Alignment.center,
                children: [
                  const Positioned(
                    left: 12,
                    child: Text('<', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w900, color: Colors.white54)),
                  ),
                  const Positioned(
                    right: 12,
                    child: Text('>', style: TextStyle(fontSize: 20, fontWeight: FontWeight.w900, color: Colors.white54)),
                  ),
                  Container(width: 2, height: 26, color: Colors.white24),
                  Positioned(
                    left: (halfW - 17.0) + curSteer * (halfW - 22.0),
                    child: Container(
                      width: 34,
                      height: 46,
                      decoration: BoxDecoration(
                        gradient: const LinearGradient(
                          colors: [Color(0xFF40EAFF), Color(0xFF0088CC)],
                          begin: Alignment.topCenter,
                          end: Alignment.bottomCenter,
                        ),
                        borderRadius: BorderRadius.circular(10),
                        border: Border.all(color: Colors.white, width: 1.6),
                        boxShadow: const [BoxShadow(color: Color(0x8800E5FF), blurRadius: 8)],
                      ),
                    ),
                  ),
                ],
              ),
            ),
            const SizedBox(height: 5),
            _steerBarIndicator(padW),
          ],
        ),
      );
    }

    const double midX = 89.0; // 84 + (10 / 2)
    return Column(
      mainAxisSize: MainAxisSize.min,
      children: [
        Listener(
          behavior: HitTestBehavior.opaque,
          onPointerDown: (e) {
            _steerPointers[e.pointer] = e.localPosition.dx >= midX;
            _syncSteerPointers();
          },
          onPointerMove: (e) {
            if (_steerPointers.containsKey(e.pointer)) {
              final bool nowRight = e.localPosition.dx >= midX;
              if (_steerPointers[e.pointer] != nowRight) {
                _steerPointers[e.pointer] = nowRight;
                _syncSteerPointers();
              }
            }
          },
          onPointerUp: (e) {
            _steerPointers.remove(e.pointer);
            _syncSteerPointers();
          },
          onPointerCancel: (e) {
            _steerPointers.remove(e.pointer);
            _syncSteerPointers();
          },
          child: Row(
            mainAxisSize: MainAxisSize.min,
            children: [
              _steerKeyBox('<', engine.leftHeld),
              const SizedBox(width: 10),
              _steerKeyBox('>', engine.rightHeld),
            ],
          ),
        ),
        const SizedBox(height: 5),
        _steerBarIndicator(178.0),
      ],
    );
  }

