class RealCircuitMinimapPainter extends CustomPainter {
  final TrackGeometry geometry;
  final double playerProgress;
  final List<double> aiProgresses;
  final Color kerbColor;

  RealCircuitMinimapPainter({
    required this.geometry,
    required this.playerProgress,
    required this.aiProgresses,
    required this.kerbColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final double cx = size.width * 0.5;
    final double cy = size.height * 0.5;
    final double r = min(size.width, size.height) * 0.46;

    final Path path = Path();
    for (int i = 0; i < geometry.smoothPoints.length; i++) {
      final Offset p = geometry.smoothPoints[i];
      final double x = cx + p.dx * r;
      final double y = cy + p.dy * r;
      if (i == 0) {
        path.moveTo(x, y);
      } else {
        path.lineTo(x, y);
      }
    }
    path.close();

    canvas.drawPath(
      path,
      Paint()
        ..isAntiAlias = true
        ..color = Colors.white70
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.6
        ..strokeJoin = StrokeJoin.round,
    );

    final Offset sf = geometry.pointAtProgress(0.0);
    canvas.drawCircle(Offset(cx + sf.dx * r, cy + sf.dy * r), 3.0, Paint()..isAntiAlias = true..color = kerbColor);

    final Paint aiPaint = Paint()..isAntiAlias = true..color = const Color(0xAAFF5252);
    for (final prog in aiProgresses) {
      final Offset ap = geometry.pointAtProgress(prog);
      canvas.drawCircle(Offset(cx + ap.dx * r, cy + ap.dy * r), 1.8, aiPaint);
    }

    final Offset pp = geometry.pointAtProgress(playerProgress);
    canvas.drawCircle(Offset(cx + pp.dx * r, cy + pp.dy * r), 3.9, Paint()..isAntiAlias = true..color = const Color(0xFF00E676));
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}

class F1UltraSmoothPainter extends CustomPainter {
  final RaceEngineState engine;

  // Adaptive 104-slice 3D perspective depth buffer (identical 226m horizon & near-field sharpness, -31% GPU/CPU load!)
  static const int segCount = 104;
  static const int _asphaltClipMaxSlice = 56;
  final List<double> _segZ = List<double>.filled(segCount + 2, 0.0);
  final List<double> _segShift = List<double>.filled(segCount + 2, 0.0);
  final List<double> _segElev = List<double>.filled(segCount + 2, 0.0);
  final List<double> _segCurv = List<double>.filled(segCount + 2, 0.0);
  final List<double> _segRunoffL = List<double>.filled(segCount + 2, 0.0);
  final List<double> _segRunoffR = List<double>.filled(segCount + 2, 0.0);
  final List<Offset> _asphaltEdgeL = List<Offset>.filled(_asphaltClipMaxSlice + 2, Offset.zero);
  final List<Offset> _asphaltEdgeR = List<Offset>.filled(_asphaltClipMaxSlice + 2, Offset.zero);
  final List<AiDriver> _visibleRivals = [];
  final List<List<AiDriver>> _rivalsBySlice = List<List<AiDriver>>.generate(segCount + 2, (_) => <AiDriver>[]);

  final Paint _fillPaint = Paint()..isAntiAlias = true;
  final Paint _gradPaint = Paint()..isAntiAlias = true;
  final Paint _strokePaint = Paint()..isAntiAlias = true..style = PaintingStyle.stroke;
  final Path _quadPath = Path();
  final Path _polyPath = Path();
  final Path _asphaltClipPath = Path();
  final Path _scratchPath = Path();
  final Path _scratchPath2 = Path();
  final Path _farRangePath = Path();
  final Path _midRangePath = Path();
  final Path _nearRangePath = Path();

  Size _cachedSize = Size.zero;
  int _cachedCircuitRound = -1;
  String _cachedLiveryCode = '';
  Paint? _vignettePaint;
  Paint? _colorGradePaint;
  Paint? _visorStripPaint;
  Paint? _turfTexPaint;
  Paint? _asphaltTexPaint;
  Paint? _carbonPaint;
  Paint? _tireTexPaint;
  Paint? _alcantaraPaint;
  Paint? _haloArchPaint;
  Paint? _tubShadowPaint;
  Paint? _bolsterLeftPaint;
  Paint? _bolsterRightPaint;
  final Map<String, TextPainter> _tagCache = {};
  final Map<String, TextPainter> _boardCache = {};
  final Map<String, TextPainter> _wheelTextCache = {};

  F1UltraSmoothPainter({required this.engine}) : super(repaint: engine);

  TextPainter _getCachedTag(String code) {
    return _tagCache.putIfAbsent(code, () {
      return TextPainter(
        text: TextSpan(
          text: code,
          style: const TextStyle(color: Colors.white, fontSize: 11.0, fontWeight: FontWeight.w900, letterSpacing: 0.5),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
    });
  }

  TextPainter _getCachedBoardText(String txt, double fontSize, Color color) {
    final int bucket = fontSize.round().clamp(7, 24).toInt();
    final String key = '${txt}_${bucket}_${color.hashCode}';
    return _boardCache.putIfAbsent(key, () {
      return TextPainter(
        text: TextSpan(
          text: txt,
          style: TextStyle(color: color, fontSize: bucket.toDouble(), fontWeight: FontWeight.w900),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
    });
  }

  double _posMod(double v, double m) {
    final double r = v % m;
    return r < 0.0 ? r + m : r;
  }

  double _kappaAtWorldDist(double dist) {
    final double lapLen = engine.circuit.lapLengthMeters;
    final double prog = _posMod(dist, lapLen) / lapLen;
    return engine.geometry.kappaAtProgress(prog);
  }

  double _runoffLeftWorldAtDist(double dist) {
    final double lapLen = engine.circuit.lapLengthMeters;
    final double prog = _posMod(dist, lapLen) / lapLen;
    return engine.roadHalfWorldX + engine.geometry.runoffLeftAtProgress(prog) * RaceEngineState.kMetersToWorldX;
  }

  double _runoffRightWorldAtDist(double dist) {
    final double lapLen = engine.circuit.lapLengthMeters;
    final double prog = _posMod(dist, lapLen) / lapLen;
    return engine.roadHalfWorldX + engine.geometry.runoffRightAtProgress(prog) * RaceEngineState.kMetersToWorldX;
  }

  double _hillAtWorldDist(double dist) {
    final double lapLen = engine.circuit.lapLengthMeters;
    final double prog = _posMod(dist, lapLen) / lapLen;
    return (sin(prog * pi * 4.0 + engine.circuit.round) * 0.68 +
            cos(prog * pi * 6.0 - engine.circuit.round * 0.6) * 0.32) *
        (engine.circuit.hillAmp * 2.15);
  }

  double _sampleSpineArray(List<double> arr, double z) {
    if (z <= _segZ[0]) return arr[0];
    if (z >= _segZ[segCount + 1]) return arr[segCount + 1];
    int lo = 0;
    int hi = segCount + 1;
    while (lo + 1 < hi) {
      final int mid = (lo + hi) >> 1;
      if (_segZ[mid] <= z) {
        lo = mid;
      } else {
        hi = mid;
      }
    }
    final double dz = max(1e-5, _segZ[hi] - _segZ[lo]);
    final double t = ((z - _segZ[lo]) / dz).clamp(0.0, 1.0).toDouble();
    return arr[lo] + (arr[hi] - arr[lo]) * t;
  }

  double _sampleSpineShift(double z) => _sampleSpineArray(_segShift, z);
  double _sampleSpineElev(double z) => _sampleSpineArray(_segElev, z);

  Offset _project(double x, double y, double z, double w, double horizonY, double fovMult) {
    final double fov = w * fovMult;
    final double scale = fov / max(z, 0.16);
    return Offset(w * 0.5 + x * scale, horizonY - y * scale);
  }

  @override
  void paint(Canvas canvas, Size size) {
    final CircuitInfo circuit = engine.circuit;
    final double w = size.width;
    final double h = size.height;
    final bool cockpit = engine.cockpitCamera;

    if (size != _cachedSize || circuit.round != _cachedCircuitRound || engine.livery.code != _cachedLiveryCode) {
      _cachedSize = size;
      _cachedCircuitRound = circuit.round;
      _cachedLiveryCode = engine.livery.code;
      final TeamLivery liv = engine.livery;
      _vignettePaint = Paint()
        ..shader = const RadialGradient(
          radius: 1.08,
          stops: [0.66, 1.0],
          colors: [Color(0x00000000), Color(0x64000000)],
        ).createShader(Rect.fromLTWH(0, 0, w, h));
      _visorStripPaint = Paint()
        ..shader = const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color(0x8A03060E), Color(0x0003060E)],
        ).createShader(Rect.fromLTWH(0, 0, w, h * 0.045));
      if (circuit.timeLabel == 'Atardecer') {
        _colorGradePaint = Paint()
          ..shader = const LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: [Color(0x16FF9838), Color(0x0AFFE082), Color(0x14200E04)],
          ).createShader(Rect.fromLTWH(0, 0, w, h));
      } else if (circuit.nightMode) {
        _colorGradePaint = Paint()
          ..shader = const LinearGradient(
            begin: Alignment.topCenter,
            end: Alignment.bottomCenter,
            colors: [Color(0x1400B0FF), Color(0x00000000), Color(0x16030714)],
          ).createShader(Rect.fromLTWH(0, 0, w, h));
      } else {
        _colorGradePaint = null;
      }
      _haloArchPaint = Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          stops: const [0.0, 0.45, 0.80, 0.94, 1.0],
          colors: [const Color(0xFF05070B), liv.primaryDark, liv.primary, liv.primaryLight, const Color(0xFF151B26)],
        ).createShader(Rect.fromLTWH(0, 0, w, h * 0.155));
      _tubShadowPaint = Paint()
        ..shader = const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color(0xE2000000), Color(0x52000000), Color(0x88000000)],
        ).createShader(Rect.fromLTWH(w * 0.13, h * 0.74, w * 0.74, h * 0.26));
      _bolsterLeftPaint = Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          colors: [Color(0xFF0A0D13), Color(0xFF1F2633), Color(0xFF10141C)],
        ).createShader(Rect.fromLTWH(0, h * 0.73, w, h * 0.27));
      _bolsterRightPaint = Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          begin: Alignment.centerRight,
          end: Alignment.centerLeft,
          colors: [Color(0xFF0A0D13), Color(0xFF1F2633), Color(0xFF10141C)],
        ).createShader(Rect.fromLTWH(0, h * 0.73, w, h * 0.27));
    }
    if (_turfTexPaint == null && UltraTextures.turfGrainShader != null) {
      _turfTexPaint = Paint()..shader = UltraTextures.turfGrainShader..filterQuality = FilterQuality.low;
    }
    if (_asphaltTexPaint == null && UltraTextures.asphaltGrainShader != null) {
      _asphaltTexPaint = Paint()..shader = UltraTextures.asphaltGrainShader..filterQuality = FilterQuality.medium;
    }
    if (_carbonPaint == null && UltraTextures.carbonShader != null) {
      _carbonPaint = Paint()..isAntiAlias = true..shader = UltraTextures.carbonShader..filterQuality = FilterQuality.high;
    }
    if (_tireTexPaint == null && UltraTextures.tireRubberShader != null) {
      _tireTexPaint = Paint()..isAntiAlias = true..shader = UltraTextures.tireRubberShader..filterQuality = FilterQuality.medium;
    }
    if (_alcantaraPaint == null && UltraTextures.alcantaraShader != null) {
      _alcantaraPaint = Paint()..isAntiAlias = true..shader = UltraTextures.alcantaraShader..filterQuality = FilterQuality.medium;
    }

    // Real-Life Silky 3D Hill Slope Pitch + Helmet G-Force Longitudinal Inertia!
    final double hillSlope = engine.smoothHillSlope;
    final double pitchOffset = (engine.smoothPitch * (cockpit ? 9.5 : 6.0)) -
        (engine.smoothLongG * (cockpit ? 4.8 : 2.5)) +
        (hillSlope * h * 0.34);
    final double horizonY = ((cockpit ? h * 0.442 : h * 0.405) + pitchOffset).clamp(h * 0.28, h * 0.54).toDouble();
    final double fovMult = 0.62 - (engine.smoothFovBoost * 0.088) - (engine.smoothLongG * 0.012);

    // Subtle sun azimuth in world screen coordinates for directional 3D lighting & specular reflections
    final double sunX = ((w * 0.72 + engine.horizonPan * 0.14) % (w * 1.4)) - w * 0.2;
    final double sunNormX = ((sunX / max(w, 1.0)) * 2.0 - 1.0).clamp(-1.0, 1.0).toDouble();

    canvas.save();
    final double totalRoll = engine.smoothCamBank * 1.12 + (engine.smoothLatG * 0.014) + engine.spinYaw * 0.24;
    if (totalRoll.abs() > 0.001) {
      canvas.translate(w * 0.5, h * 0.5);
      canvas.rotate(totalRoll);
      canvas.translate(-w * 0.5, -h * 0.5);
    }

    // 1. Multi-Layered Atmospheric Sky, Volumetric Sun Scattering & 3-Layer Parallax Ridges
    _drawProEnvironment(canvas, w, h, horizonY, sunX, circuit);

    // 2. Deep Base Horizon Ground Plane (seamless blend below perspective terrain slices)
    final Rect groundRect = Rect.fromLTWH(0, horizonY - 2, w, h - horizonY + 64);
    _gradPaint.shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      stops: const [0.0, 0.25, 1.0],
      colors: [
        Color.lerp(circuit.groundColor, circuit.skyBottom, 0.55)!,
        circuit.groundColor,
        Color.lerp(circuit.groundColor, Colors.black, 0.45)!,
      ],
    ).createShader(groundRect);
    canvas.drawRect(groundRect, _gradPaint);

    // 3. Precompute Adaptive 104-Slice TRUE 1:1 FIA 3D Track Spine (Exact 226m Horizon & Zero Wasted Sub-Pixel Slices!)
    final double roadHalfW = engine.roadHalfWorldX;
    final double kerbOuterW = roadHalfW + (circuit.isStreetCircuit ? 0.40 : 0.54);
    final double astroOuterW = circuit.isStreetCircuit ? (kerbOuterW + 0.14) : (kerbOuterW + 0.52);
    const double terrainOuterW = 82.0;
    const double baseSegLen = 0.50;

    final double kerbJitter = (engine.carX.abs() > 0.88 && engine.carX.abs() < 1.05 && engine.speedKmh > 40)
        ? sin(engine.playerDist * 3.4) * 0.032
        : 0.0;
    final double baseCamHeight = (cockpit ? -1.14 : -1.78) + kerbJitter;
    // Exact chase camera Z distance so the player's True-3D Chase Car sits planted on the asphalt at 89.5% height on any screen!
    final double playerChaseZ = cockpit
        ? 0.0
        : ((-baseCamHeight * w * fovMult) / max(45.0, 0.895 * h - horizonY)).clamp(3.15, 5.20).toDouble();
    final double camOriginDist = cockpit ? engine.playerDist : (engine.playerDist - playerChaseZ * 2.0);
    final double camOriginHill = _hillAtWorldDist(camOriginDist);

    final double zOffset = _posMod(camOriginDist * 0.5, baseSegLen);
    _segZ[0] = 0.0;
    _segShift[0] = 0.0;
    _segElev[0] = 0.0;
    _segCurv[0] = _kappaAtWorldDist(camOriginDist);
    _segRunoffL[0] = _runoffLeftWorldAtDist(camOriginDist);
    _segRunoffR[0] = _runoffRightWorldAtDist(camOriginDist);

    // EXACT EUCLIDEAN CURVE INTEGRATION: theta(s) = integral(kappa(s) ds), x(s) = integral(sin(theta) ds)!
    // Guarantees 0.000 laser-straightaways and true 1:1 corner angles (35 deg sweepers, 90 deg corners, 180 deg hairpins)!
    double thetaRoad = 0.0;
    double xRoadMeters = 0.0;
    double prevZVal = 0.0;
    final double yawSlope = (sin(engine.carHeading) * 1.22) + (engine.smoothSteerLook * 0.14);
    for (int i = 1; i <= segCount + 1; i++) {
      final double zVal = (i * baseSegLen) + (i * i * 0.00565) - zOffset;
      _segZ[i] = zVal;
      final double dsMeters = max(0.0, (zVal - prevZVal) * 2.0);
      prevZVal = zVal;
      final double wd = camOriginDist + zVal * 2.0;
      final double kappa = _kappaAtWorldDist(wd);
      _segCurv[i] = kappa;
      _segRunoffL[i] = _runoffLeftWorldAtDist(wd);
      _segRunoffR[i] = _runoffRightWorldAtDist(wd);
      thetaRoad += kappa * dsMeters;
      final double thetaVis = thetaRoad.clamp(-1.36, 1.36).toDouble();
      xRoadMeters += sin(thetaVis) * dsMeters;
      _segShift[i] = (xRoadMeters * RaceEngineState.kMetersToWorldX) - (zVal * yawSlope);
      // Real vertical elevation minus camera tangent plane so crests rise & fall authentically!
      final double relHill = (_hillAtWorldDist(wd) - camOriginHill) - (hillSlope * zVal * 1.45);
      _segElev[i] = relHill * (0.35 + 0.65 * (i / segCount));
    }

    // Smooth lateral G-force & Look-to-Apex camera offset into turns (+ chase spine centering)
    final double gLean = engine.smoothSteerLook * 0.22;
    final double chaseSpineFollow = cockpit ? 0.0 : (_sampleSpineShift(playerChaseZ) * 0.72);
    final double camShift = chaseSpineFollow + engine.carX * engine.laneToWorldX + engine.spinYaw * 1.4 + gLean;

    // Bin visible rivals + player chase car into exact depth slices so cars pass UNDER bridges, behind hill crests & wheel-to-wheel!
    for (int i = 0; i <= segCount + 1; i++) {
      _rivalsBySlice[i].clear();
    }
    int playerChaseSlice = -1;
    if (!cockpit) {
      playerChaseSlice = segCount;
      for (int s = 1; s <= segCount; s++) {
        if (_segZ[s] >= playerChaseZ) {
          playerChaseSlice = s;
          break;
        }
      }
    }
    if (engine.phase == SessionPhase.race) {
      _visibleRivals.clear();
      for (final ai in engine.aiDrivers) {
        final double dz = (ai.trackDist - camOriginDist) / 2.0;
        if (dz > 0.72 && dz < _segZ[segCount]) {
          _visibleRivals.add(ai);
        }
      }
      _visibleRivals.sort((a, b) => b.trackDist.compareTo(a.trackDist));
      for (final ai in _visibleRivals) {
        final double z = (ai.trackDist - camOriginDist) / 2.0;
        int sliceIdx = segCount;
        for (int s = 1; s <= segCount; s++) {
          if (_segZ[s] >= z) {
            sliceIdx = s;
            break;
          }
        }
        _rivalsBySlice[sliceIdx].add(ai);
      }
    }

    _asphaltClipPath.reset();
    int asphaltClipMaxHit = 0;
    double topRunoffY = h;
    final double lapLen = circuit.lapLengthMeters;
    final Color groundDark = Color.lerp(circuit.groundColor, Colors.black, 0.22)!;
    final Color groundLight = Color.lerp(circuit.groundColor, Colors.white, circuit.nightMode ? 0.04 : 0.08)!;
    final Color bermLight = Color.lerp(circuit.groundColor, Colors.white, circuit.nightMode ? 0.06 : 0.14)!;
    final Color bermDark = Color.lerp(circuit.groundColor, Colors.black, 0.34)!;

    // Track world-anchored discrete markers so each world object draws ONCE per frame (zero jitter/popping!)
    int lastPropBucket = -999999;
    int lastFencePostBucket = -999999;
    int lastArchBucket = -999999;
    int lastBrakeBucket = -999999;
    bool drewStartGantry = false;

    for (int i = segCount; i >= 1; i--) {
      final double z1 = _segZ[i];
      final double z2 = _segZ[i + 1];
      if (z1 <= 0.22) continue;

      final double worldDist1 = camOriginDist + z1 * 2.0;
      final double worldDist2 = camOriginDist + z2 * 2.0;
      final double lapDist1 = _posMod(worldDist1, lapLen);
      final int segIndex = (worldDist1 / 1.75).floor();

      final double s1 = _segShift[i] - camShift;
      final double s2 = _segShift[i + 1] - camShift;
      final double y1 = baseCamHeight + _segElev[i];
      final double y2 = baseCamHeight + _segElev[i + 1];
      final double kNow = _segCurv[i];

      final double depthT = (i / segCount).clamp(0.0, 1.0).toDouble();
      final double fogMix = pow(depthT, 2.15).toDouble() * 0.84;

      // 3A. TRUE 3D PERSPECTIVE TERRAIN STRIPS & SIDE EMBANKMENTS (Rushes past in 100% genuine 3D foreshortening!)
      final int terrainBand = (worldDist1 / 9.5).floor();
      final Color rawTerrain = terrainBand % 2 == 0 ? groundLight : groundDark;
      final Color terrainCol = Color.lerp(rawTerrain, circuit.skyBottom, fogMix)!;
      final Offset t1L = _project(-terrainOuterW + s1, y1 - 0.06, z1, w, horizonY, fovMult);
      final Offset t1R = _project(terrainOuterW + s1, y1 - 0.06, z1, w, horizonY, fovMult);
      final Offset t2L = _project(-terrainOuterW + s2, y2 - 0.06, z2, w, horizonY, fovMult);
      final Offset t2R = _project(terrainOuterW + s2, y2 - 0.06, z2, w, horizonY, fovMult);
      _drawQuad(canvas, t1L, t1R, t2R, t2L, terrainCol);

      // Exact Asymmetric Left & Right Real-Meter Barrier Distances at slice z1 and z2!
      final double run1L = _segRunoffL[i];
      final double run2L = _segRunoffL[i + 1];
      final double run1R = _segRunoffR[i];
      final double run2R = _segRunoffR[i + 1];
      final double wallCap1L = run1L + 0.42;
      final double wallCap2L = run2L + 0.42;
      final double wallCap1R = run1R + 0.42;
      final double wallCap2R = run2R + 0.42;
      final double clear1L = max(0.0, run1L - roadHalfW);
      final double clear1R = max(0.0, run1R - roadHalfW);

      // Sloped 3D Terrain Embankments flanking outside the actual asymmetric barriers
      if (i < 88 && circuit.propStyle != PropStyle.skyline) {
        final double bermH = 1.85 + circuit.hillAmp * 1.25;
        final Offset bm1LI = _project(-wallCap1L - 0.4 + s1, y1, z1, w, horizonY, fovMult);
        final Offset bm2LI = _project(-wallCap2L - 0.4 + s2, y2, z2, w, horizonY, fovMult);
        final Offset bm1LO = _project(-wallCap1L - 10.5 + s1, y1 + bermH, z1, w, horizonY, fovMult);
        final Offset bm2LO = _project(-wallCap2L - 10.5 + s2, y2 + bermH, z2, w, horizonY, fovMult);
        final Offset bm1RI = _project(wallCap1R + 0.4 + s1, y1, z1, w, horizonY, fovMult);
        final Offset bm2RI = _project(wallCap2R + 0.4 + s2, y2, z2, w, horizonY, fovMult);
        final Offset bm1RO = _project(wallCap1R + 10.5 + s1, y1 + bermH, z1, w, horizonY, fovMult);
        final Offset bm2RO = _project(wallCap2R + 10.5 + s2, y2 + bermH, z2, w, horizonY, fovMult);
        _drawQuad(canvas, bm1LO, bm1LI, bm2LI, bm2LO, Color.lerp(sunNormX >= 0 ? bermLight : bermDark, circuit.skyBottom, fogMix)!);
        _drawQuad(canvas, bm1RI, bm1RO, bm2RO, bm2RI, Color.lerp(sunNormX >= 0 ? bermDark : bermLight, circuit.skyBottom, fogMix)!);
      }

      // 3B. REAL-SPACE TRACK-TO-BARRIER RUNOFF APRON (Painted FIA Tarmac + Gravel Traps + Grass Verges + Pit Lane!)
      final bool onPitStraight = (lapDist1 < 185.0) || (lapDist1 > lapLen - 85.0);
      final Offset r1L = _project(-run1L + s1, y1, z1, w, horizonY, fovMult);
      final Offset r1R = _project(run1R + s1, y1, z1, w, horizonY, fovMult);
      final Offset r2L = _project(-run2L + s2, y2, z2, w, horizonY, fovMult);
      final Offset r2R = _project(run2R + s2, y2, z2, w, horizonY, fovMult);

      final Color tarmacRunRaw = segIndex % 2 == 0
          ? circuit.runoffColor
          : Color.lerp(circuit.runoffColor, Colors.black, 0.09)!;
      final Color tarmacRunCol = Color.lerp(tarmacRunRaw, circuit.skyBottom, fogMix)!;
      final Color pitLaneRaw = segIndex % 2 == 0 ? const Color(0xFF282E38) : const Color(0xFF232832);
      final Color pitLaneCol = Color.lerp(pitLaneRaw, circuit.skyBottom, fogMix)!;

      // Base runoff plane spanning exact real distance from left barrier to right barrier
      _drawQuad(canvas, r1L, r1R, r2R, r2L, onPitStraight ? pitLaneCol : tarmacRunCol);
      if (i < _asphaltClipMaxSlice) {
        final double minY = min(t1L.dy, min(t1R.dy, min(t2L.dy, t2R.dy)));
        if (minY < topRunoffY) topRunoffY = minY;
      }

      // Left-side & Right-side real-surface layering (Gravel Traps on wide corner runoffs, Mowed Grass Verges, or FIA Painted Tarmac Stripes!)
      if (!circuit.isStreetCircuit) {
        final Color gravelBase = circuit.nightMode
            ? (segIndex % 2 == 0 ? const Color(0xFF6B5D4A) : const Color(0xFF5F5241))
            : (segIndex % 2 == 0 ? const Color(0xFFC2AB82) : const Color(0xFFB39B72));
        final Color gravelCol = Color.lerp(gravelBase, circuit.skyBottom, fogMix)!;
        final Color grassVergeBase = segIndex % 2 == 0
            ? Color.lerp(circuit.groundColor, const Color(0xFF3E7034), 0.25)!
            : Color.lerp(circuit.groundColor, Colors.black, 0.12)!;
        final Color grassVergeCol = Color.lerp(grassVergeBase, circuit.skyBottom, fogMix)!;
        final Color stripeCol = Color.lerp(
          Color.lerp(circuit.kerbA, circuit.runoffColor, 0.42)!,
          circuit.skyBottom,
          fogMix,
        )!;

        // LEFT SIDE RUNOFF DETAIL
        if (circuit.hasGravelTraps && clear1L >= 10.8) {
          // Outer ~56% of wide corner runoff is an authentic raked FIA Gravel Trap (leca de grava)!
          final double g1LI = roadHalfW + clear1L * 0.44;
          final double g2LI = roadHalfW + max(0.0, run2L - roadHalfW) * 0.44;
          final Offset gr1I = _project(-g1LI + s1, y1 + 0.005, z1, w, horizonY, fovMult);
          final Offset gr2I = _project(-g2LI + s2, y2 + 0.005, z2, w, horizonY, fovMult);
          _drawQuad(canvas, r1L, gr1I, gr2I, r2L, gravelCol);
          // Raked FIA gravel trap corduroy ripples
          if (i < 56 && segIndex % 2 == 0) {
            _strokePaint
              ..color = Color.fromARGB((52 * (1.0 - fogMix)).toInt(), 45, 32, 16)
              ..strokeWidth = max(1.0, 3.0 / z1);
            canvas.drawLine(Offset.lerp(r1L, gr1I, 0.35)!, Offset.lerp(r2L, gr2I, 0.35)!, _strokePaint);
            canvas.drawLine(Offset.lerp(r1L, gr1I, 0.70)!, Offset.lerp(r2L, gr2I, 0.70)!, _strokePaint);
          }
          if (i < 68 && segIndex % 4 == 0 && g1LI > astroOuterW + 0.8) {
            _drawQuad(
              canvas,
              _project(-g1LI + 0.25 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
              _project(-astroOuterW - 0.12 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
              _project(-astroOuterW + 0.12 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
              _project(-g2LI + 0.55 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
              stripeCol,
            );
          }
        } else if (circuit.hasGravelTraps && !onPitStraight && clear1L > 2.6) {
          // Classic grass verge between trackside tarmac strip & straightaway barrier
          final double v1LI = min(run1L - 0.4, astroOuterW + 1.45);
          final double v2LI = min(run2L - 0.4, astroOuterW + 1.45);
          _drawQuad(
            canvas,
            r1L,
            _project(-v1LI + s1, y1 + 0.004, z1, w, horizonY, fovMult),
            _project(-v2LI + s2, y2 + 0.004, z2, w, horizonY, fovMult),
            r2L,
            grassVergeCol,
          );
        } else if (!onPitStraight && i < 68 && segIndex % 4 == 0 && clear1L > 2.2) {
          // Painted FIA high-grip diagonal runoff stripes (Abu Dhabi, COTA, Mexico)
          final double stOut1 = min(run1L - 0.35, astroOuterW + 7.5);
          final double stOut2 = min(run2L - 0.35, astroOuterW + 7.5);
          _drawQuad(
            canvas,
            _project(-stOut1 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
            _project(-astroOuterW - 0.12 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
            _project(-astroOuterW + 0.12 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
            _project(-stOut2 + 0.35 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
            stripeCol,
          );
        }

        // RIGHT SIDE RUNOFF DETAIL (skip gravel/grass when on Pit Lane straight!)
        if (!onPitStraight) {
          if (circuit.hasGravelTraps && clear1R >= 10.8) {
            final double g1RI = roadHalfW + clear1R * 0.44;
            final double g2RI = roadHalfW + max(0.0, run2R - roadHalfW) * 0.44;
            final Offset gr1RI = _project(g1RI + s1, y1 + 0.005, z1, w, horizonY, fovMult);
            final Offset gr2RI = _project(g2RI + s2, y2 + 0.005, z2, w, horizonY, fovMult);
            _drawQuad(canvas, gr1RI, r1R, r2R, gr2RI, gravelCol);
            if (i < 56 && segIndex % 2 == 0) {
              _strokePaint
                ..color = Color.fromARGB((52 * (1.0 - fogMix)).toInt(), 45, 32, 16)
                ..strokeWidth = max(1.0, 3.0 / z1);
              canvas.drawLine(Offset.lerp(gr1RI, r1R, 0.35)!, Offset.lerp(gr2RI, r2R, 0.35)!, _strokePaint);
              canvas.drawLine(Offset.lerp(gr1RI, r1R, 0.70)!, Offset.lerp(gr2RI, r2R, 0.70)!, _strokePaint);
            }
            if (i < 68 && segIndex % 4 == 0 && g1RI > astroOuterW + 0.8) {
              _drawQuad(
                canvas,
                _project(astroOuterW + 0.12 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
                _project(g1RI - 0.25 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
                _project(g2RI - 0.55 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
                _project(astroOuterW - 0.12 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
                stripeCol,
              );
            }
          } else if (circuit.hasGravelTraps && clear1R > 2.6) {
            final double v1RI = min(run1R - 0.4, astroOuterW + 1.45);
            final double v2RI = min(run2R - 0.4, astroOuterW + 1.45);
            _drawQuad(
              canvas,
              _project(v1RI + s1, y1 + 0.004, z1, w, horizonY, fovMult),
              r1R,
              r2R,
              _project(v2RI + s2, y2 + 0.004, z2, w, horizonY, fovMult),
              grassVergeCol,
            );
          } else if (i < 68 && segIndex % 4 == 0 && clear1R > 2.2) {
            final double stOut1 = min(run1R - 0.35, astroOuterW + 7.5);
            final double stOut2 = min(run2R - 0.35, astroOuterW + 7.5);
            _drawQuad(
              canvas,
              _project(astroOuterW + 0.12 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
              _project(stOut1 + s1, y1 + 0.008, z1, w, horizonY, fovMult),
              _project(stOut2 - 0.35 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
              _project(astroOuterW - 0.12 + s2, y2 + 0.008, z2, w, horizonY, fovMult),
              stripeCol,
            );
          }
        }
      }

      // Pit Lane White Divider & Team Pit Wall on Right Side of Main Straight
      if (onPitStraight && i < 76) {
        final double pitLine1 = min(run1R - 0.4, astroOuterW + 0.45);
        final double pitLine2 = min(run2R - 0.4, astroOuterW + 0.45);
        final Offset pl1 = _project(pitLine1 + s1, y1 + 0.01, z1, w, horizonY, fovMult);
        final Offset pl2 = _project(pitLine2 + s2, y2 + 0.01, z2, w, horizonY, fovMult);
        _strokePaint
          ..color = Color.lerp(const Color(0xDDFFFFFF), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, 3.6 / z1);
        canvas.drawLine(pl1, pl2, _strokePaint);

        // 3D Pit Wall + Illuminated Telemetry Timing Stands + Team Pit Garages!
        final Offset pw1B = _project(run1R + 0.15 + s1, y1, z1, w, horizonY, fovMult);
        final Offset pw2B = _project(run2R + 0.15 + s2, y2, z2, w, horizonY, fovMult);
        final Offset pw1T = _project(run1R + 0.15 + s1, y1 + 1.62, z1, w, horizonY, fovMult);
        final Offset pw2T = _project(run2R + 0.15 + s2, y2 + 1.62, z2, w, horizonY, fovMult);
        final Offset pw1R = _project(run1R + 1.85 + s1, y1 + 2.05, z1, w, horizonY, fovMult);
        final Offset pw2R = _project(run2R + 1.85 + s2, y2 + 2.05, z2, w, horizonY, fovMult);
        _drawQuad(canvas, pw1B, pw2B, pw2T, pw1T, Color.lerp(const Color(0xFF172030), circuit.skyBottom, fogMix)!);
        _drawQuad(canvas, pw1T, pw2T, pw2R, pw1R, Color.lerp(segIndex % 6 < 3 ? circuit.kerbA : const Color(0xFF0D1320), circuit.skyBottom, fogMix)!);

        // Glowing cyan/amber pit-wall monitor LED ribbon & backlit team garage bay behind pit lane
        final Offset mon1 = _project(run1R + 0.22 + s1, y1 + 1.24, z1, w, horizonY, fovMult);
        final Offset mon2 = _project(run2R + 0.22 + s2, y2 + 1.24, z2, w, horizonY, fovMult);
        _strokePaint
          ..color = Color.lerp(segIndex % 4 == 0 ? const Color(0xCC00E5FF) : const Color(0xAAFFD54F), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, 4.2 / z1);
        canvas.drawLine(mon1, mon2, _strokePaint);

        if (i < 64) {
          final Offset gb1B = _project(run1R + 4.4 + s1, y1, z1, w, horizonY, fovMult);
          final Offset gb2B = _project(run2R + 4.4 + s2, y2, z2, w, horizonY, fovMult);
          final Offset gb1T = _project(run1R + 4.4 + s1, y1 + 4.35, z1, w, horizonY, fovMult);
          final Offset gb2T = _project(run2R + 4.4 + s2, y2 + 4.35, z2, w, horizonY, fovMult);
          final bool litBay = segIndex % 5 != 0;
          _drawQuad(
            canvas,
            gb1B,
            gb2B,
            gb2T,
            gb1T,
            Color.lerp(litBay ? const Color(0xFF222D40) : const Color(0xFF111622), circuit.skyBottom, fogMix)!,
          );
          if (litBay) {
            final Offset gl1 = _project(run1R + 4.32 + s1, y1 + 2.55, z1, w, horizonY, fovMult);
            final Offset gl2 = _project(run2R + 4.32 + s2, y2 + 2.55, z2, w, horizonY, fovMult);
            _strokePaint
              ..color = Color.lerp(const Color(0xCCEAF6FF), circuit.skyBottom, fogMix)!
              ..strokeWidth = max(1.2, 6.2 / z1);
            canvas.drawLine(gl1, gl2, _strokePaint);
          }
        }

        // Iconic 3D FIA Race Control Tower & Glowing Digital Timing Pylon right near the Start/Finish Line!
        if (lapDist1 > 12.0 && lapDist1 < 22.0 && i < 68) {
          final Offset rc1B = _project(run1R + 5.2 + s1, y1, z1, w, horizonY, fovMult);
          final Offset rc2B = _project(run2R + 5.2 + s2, y2, z2, w, horizonY, fovMult);
          final Offset rc1T = _project(run1R + 5.2 + s1, y1 + 8.4, z1, w, horizonY, fovMult);
          final Offset rc2T = _project(run2R + 5.2 + s2, y2 + 8.4, z2, w, horizonY, fovMult);
          _drawQuad(canvas, rc1B, rc2B, rc2T, rc1T, Color.lerp(const Color(0xFF1A2438), circuit.skyBottom, fogMix)!);
          // Illuminated panoramic race-director glass observation floor
          final Offset gl1B = _project(run1R + 5.05 + s1, y1 + 5.4, z1, w, horizonY, fovMult);
          final Offset gl2B = _project(run2R + 5.05 + s2, y2 + 5.4, z2, w, horizonY, fovMult);
          final Offset gl1T = _project(run1R + 5.05 + s1, y1 + 7.2, z1, w, horizonY, fovMult);
          final Offset gl2T = _project(run2R + 5.05 + s2, y2 + 7.2, z2, w, horizonY, fovMult);
          _drawQuad(
            canvas,
            gl1B,
            gl2B,
            gl2T,
            gl1T,
            Color.lerp(circuit.nightMode ? const Color(0xFF56D4FF) : const Color(0xFFAAD8FA), circuit.skyBottom, fogMix * 0.75)!,
          );
          // Red FIA roof band
          final Offset rf1B = _project(run1R + 5.05 + s1, y1 + 7.6, z1, w, horizonY, fovMult);
          final Offset rf2B = _project(run2R + 5.05 + s2, y2 + 7.6, z2, w, horizonY, fovMult);
          _drawQuad(canvas, rf1B, rf2B, rc2T, rc1T, Color.lerp(const Color(0xFFE10600), circuit.skyBottom, fogMix)!);
        }
      }

      // 3C. TRUE 3D MULTI-SLICE EXTRUDED GRANDSTANDS (Anchored smoothly BEHIND the real outer barriers!)
      final int gsBlock = (lapDist1 / 175.0).floor();
      final double gsLocal = lapDist1 % 175.0;
      if (gsLocal >= 14.0 && gsLocal <= 52.0 && i < 90) {
        final bool onLeftSide = (gsBlock % 2 == 0);
        if (!(onPitStraight && !onLeftSide)) {
          _draw3DExtrudedGrandstandSlice(
            canvas,
            onLeftSide ? (-wallCap1L - 0.55) : (wallCap1R + 0.55),
            onLeftSide ? (-wallCap2L - 0.55) : (wallCap2R + 0.55),
            s1,
            s2,
            y1,
            y2,
            z1,
            z2,
            onLeftSide,
            segIndex,
            w,
            horizonY,
            fovMult,
            fogMix,
            circuit,
          );
        }
      }

      // 3D. TRUE 3D EXTRUDED ASYMMETRIC BARRIERS (Cast Shadow + TECPRO/Street Wall + Top Cap + Corner Chevrons + Catch Fence)
      final double wallH = circuit.isStreetCircuit ? 1.12 : 0.96;
      final Offset w1LT = _project(-run1L + s1, y1 + wallH, z1, w, horizonY, fovMult);
      final Offset w2LT = _project(-run2L + s2, y2 + wallH, z2, w, horizonY, fovMult);
      final Offset w1RT = _project(run1R + s1, y1 + wallH, z1, w, horizonY, fovMult);
      final Offset w2RT = _project(run2R + s2, y2 + wallH, z2, w, horizonY, fovMult);

      // Directional Barrier Cast Shadows onto the Runoff / Gravel
      if (i < 75) {
        final double lShadW = min(clear1L * 0.65, sunNormX >= 0 ? 0.92 : 0.48);
        final double rShadW = min(clear1R * 0.65, sunNormX >= 0 ? 0.48 : 0.92);
        final Color bShad = Color.fromARGB((78 * (1.0 - fogMix)).toInt(), 0, 0, 0);
        final Offset bs1L = _project(-run1L + lShadW + s1, y1 + 0.012, z1, w, horizonY, fovMult);
        final Offset bs2L = _project(-run2L + lShadW + s2, y2 + 0.012, z2, w, horizonY, fovMult);
        final Offset bs1R = _project(run1R - rShadW + s1, y1 + 0.012, z1, w, horizonY, fovMult);
        final Offset bs2R = _project(run2R - rShadW + s2, y2 + 0.012, z2, w, horizonY, fovMult);
        _drawQuad(canvas, r1L, bs1L, bs2L, r2L, bShad);
        _drawQuad(canvas, bs1R, r1R, r2R, bs2R, bShad);
      }

      // 3D Top Cap of Concrete/TECPRO Barrier
      if (i < 82) {
        final Offset wc1LT = _project(-wallCap1L + s1, y1 + wallH, z1, w, horizonY, fovMult);
        final Offset wc2LT = _project(-wallCap2L + s2, y2 + wallH, z2, w, horizonY, fovMult);
        final Offset wc1RT = _project(wallCap1R + s1, y1 + wallH, z1, w, horizonY, fovMult);
        final Offset wc2RT = _project(wallCap2R + s2, y2 + wallH, z2, w, horizonY, fovMult);
        final Color capCol = Color.lerp(const Color(0xFFA0B0C4), circuit.skyBottom, fogMix)!;
        _drawQuad(canvas, wc1LT, w1LT, w2LT, wc2LT, capCol);
        _drawQuad(canvas, w1RT, wc1RT, wc2RT, w2RT, capCol);
      }

      // Barrier Front Faces (TECPRO red/white blocks on outer corners R < 90m, dark/sponsor panels on straights)
      final bool leftIsOutsideCorner = kNow > 0.011;
      final bool rightIsOutsideCorner = kNow < -0.011;
      final Color wallBase = (segIndex % 10 < 5)
          ? const Color(0xFF141B27)
          : (segIndex % 20 < 10 ? circuit.kerbA : const Color(0xFFEFF4FA));
      final Color leftWallRaw = leftIsOutsideCorner
          ? (segIndex % 2 == 0 ? const Color(0xFFE10600) : const Color(0xFFF5F8FC))
          : wallBase;
      final Color rightWallRaw = rightIsOutsideCorner
          ? (segIndex % 2 == 0 ? const Color(0xFFE10600) : const Color(0xFFF5F8FC))
          : wallBase;

      final Color wallLeftCol = Color.lerp(Color.lerp(leftWallRaw, Colors.white, sunNormX >= 0 ? 0.14 : 0.03)!, circuit.skyBottom, fogMix)!;
      final Color wallRightCol = Color.lerp(Color.lerp(rightWallRaw, Colors.black, sunNormX >= 0 ? 0.24 : 0.08)!, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, r1L, w1LT, w2LT, r2L, wallLeftCol);
      _drawQuad(canvas, r1R, r2R, w2RT, w1RT, wallRightCol);

      // Metallic Armco guardrail ribs on street circuits & crisp upper bevel accent stripe on permanent barriers!
      if (i < 63) {
        final double ribH1 = wallH * (circuit.isStreetCircuit ? 0.44 : 0.80);
        final double ribH2 = wallH * 0.72;
        final Offset lr1A = _project(-run1L + 0.02 + s1, y1 + ribH1, z1, w, horizonY, fovMult);
        final Offset lr2A = _project(-run2L + 0.02 + s2, y2 + ribH1, z2, w, horizonY, fovMult);
        final Offset rr1A = _project(run1R - 0.02 + s1, y1 + ribH1, z1, w, horizonY, fovMult);
        final Offset rr2A = _project(run2R - 0.02 + s2, y2 + ribH1, z2, w, horizonY, fovMult);
        _strokePaint
          ..color = Color.lerp(
            circuit.isStreetCircuit ? const Color(0xBBCDD9E8) : const Color(0x55FFFFFF),
            circuit.skyBottom,
            fogMix,
          )!
          ..strokeWidth = max(0.8, 3.2 / z1);
        canvas.drawLine(lr1A, lr2A, _strokePaint);
        canvas.drawLine(rr1A, rr2A, _strokePaint);
        if (circuit.isStreetCircuit) {
          final Offset lr1B = _project(-run1L + 0.02 + s1, y1 + ribH2, z1, w, horizonY, fovMult);
          final Offset lr2B = _project(-run2L + 0.02 + s2, y2 + ribH2, z2, w, horizonY, fovMult);
          final Offset rr1B = _project(run1R - 0.02 + s1, y1 + ribH2, z1, w, horizonY, fovMult);
          final Offset rr2B = _project(run2R - 0.02 + s2, y2 + ribH2, z2, w, horizonY, fovMult);
          canvas.drawLine(lr1B, lr2B, _strokePaint);
          canvas.drawLine(rr1B, rr2B, _strokePaint);
        }

        // Animated F1 Digital LED Sponsor Ribbon along main barrier segments (sweeping glowing pulse!)
        if (!leftIsOutsideCorner && !rightIsOutsideCorner && (segIndex % 16 < 6) && i < 54) {
          final int pulseWave = ((segIndex + (engine.totalRaceTime * 7.0).floor()) % 6);
          final Color ledStripCol = pulseWave == 0
              ? const Color(0xEE00E5FF)
              : (pulseWave == 3 ? const Color(0xEEFFD54F) : const Color(0xDDE10600));
          final double ledY = wallH * 0.56;
          _strokePaint
            ..color = Color.lerp(ledStripCol, circuit.skyBottom, fogMix * 0.65)!
            ..strokeWidth = max(1.0, 4.4 / z1);
          canvas.drawLine(
            _project(-run1L + 0.04 + s1, y1 + ledY, z1, w, horizonY, fovMult),
            _project(-run2L + 0.04 + s2, y2 + ledY, z2, w, horizonY, fovMult),
            _strokePaint,
          );
          canvas.drawLine(
            _project(run1R - 0.04 + s1, y1 + ledY, z1, w, horizonY, fovMult),
            _project(run2R - 0.04 + s2, y2 + ledY, z2, w, horizonY, fovMult),
            _strokePaint,
          );
        }
      }

      // 3D Curved FIA Corner Chevron Boards above Outer Barrier on Tight Corners!
      if ((leftIsOutsideCorner || rightIsOutsideCorner) && i < 72) {
        final bool onLeft = leftIsOutsideCorner;
        final double cx1 = (onLeft ? -run1L - 0.05 : run1R + 0.05) + s1;
        final double cx2 = (onLeft ? -run2L - 0.05 : run2R + 0.05) + s2;
        final Offset ch1B = _project(cx1, y1 + wallH + 0.06, z1, w, horizonY, fovMult);
        final Offset ch2B = _project(cx2, y2 + wallH + 0.06, z2, w, horizonY, fovMult);
        final Offset ch1T = _project(cx1, y1 + wallH + 0.72, z1, w, horizonY, fovMult);
        final Offset ch2T = _project(cx2, y2 + wallH + 0.72, z2, w, horizonY, fovMult);
        final Color chevCol = Color.lerp(
          segIndex % 2 == 0 ? const Color(0xFF0E121A) : const Color(0xFFFFEA00),
          circuit.skyBottom,
          fogMix,
        )!;
        _drawQuad(canvas, ch1B, ch1T, ch2T, ch2B, chevCol);
      }

      // World-Anchored 3D Catch Fencing mounted directly along the Asymmetric Outer Barriers
      if (i < 70) {
        final Offset f1LT = _project(-run1L + s1, y1 + 2.35, z1, w, horizonY, fovMult);
        final Offset f2LT = _project(-run2L + s2, y2 + 2.35, z2, w, horizonY, fovMult);
        final Offset f1RT = _project(run1R + s1, y1 + 2.35, z1, w, horizonY, fovMult);
        final Offset f2RT = _project(run2R + s2, y2 + 2.35, z2, w, horizonY, fovMult);
        final Offset f1LM = _project(-run1L + s1, y1 + 1.65, z1, w, horizonY, fovMult);
        final Offset f2LM = _project(-run2L + s2, y2 + 1.65, z2, w, horizonY, fovMult);
        final Offset f1RM = _project(run1R + s1, y1 + 1.65, z1, w, horizonY, fovMult);
        final Offset f2RM = _project(run2R + s2, y2 + 1.65, z2, w, horizonY, fovMult);

        _strokePaint
          ..color = Color.lerp(const Color(0x66C4D4E6), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(0.8, 2.2 / z1);
        canvas.drawLine(f1LT, f2LT, _strokePaint);
        canvas.drawLine(f1RT, f2RT, _strokePaint);
        canvas.drawLine(f1LM, f2LM, _strokePaint);
        canvas.drawLine(f1RM, f2RM, _strokePaint);

        // World-anchored fence posts every 14m (NO screen-space jitter!)
        final int postBucket = (worldDist1 / 14.0).floor();
        if (postBucket != lastFencePostBucket) {
          lastFencePostBucket = postBucket;
          _strokePaint
            ..color = Color.lerp(const Color(0xAA9BB0C7), circuit.skyBottom, fogMix)!
            ..strokeWidth = max(1.2, 5.2 / z1);
          canvas.drawLine(w1LT, f1LT, _strokePaint);
          canvas.drawLine(w1RT, f1RT, _strokePaint);
          final Offset armL = _project(-run1L + 0.42 + s1, y1 + 2.66, z1, w, horizonY, fovMult);
          final Offset armR = _project(run1R - 0.42 + s1, y1 + 2.66, z1, w, horizonY, fovMult);
          canvas.drawLine(f1LT, armL, _strokePaint);
          canvas.drawLine(f1RT, armR, _strokePaint);

          // Glowing 3D FIA LED Marshal Light Panel with zero-shader soft bloom halo every 4 posts
          if (postBucket % 4 == 0 && i < 54) {
            final bool panelLeft = postBucket % 8 == 0;
            final Offset mp = panelLeft ? f1LM : f1RM;
            final double pw = (36.0 / z1).clamp(4.5, 24.0).toDouble();
            final double ph = pw * 0.68;
            final Rect pRect = Rect.fromCenter(center: mp, width: pw, height: ph);
            final Color ledCol = engine.startLightsTimer > 0
                ? const Color(0xFFFF1744)
                : (kNow.abs() > 0.018 ? const Color(0xFFFFD600) : const Color(0xFF00E676));
            if (pw > 7.0) {
              final int baseA = ((92 * (1.0 - fogMix))).toInt().clamp(0, 255).toInt();
              _fillPaint.color = ledCol.withAlpha(baseA >> 1);
              canvas.drawCircle(mp, pw * 1.12, _fillPaint);
              _fillPaint.color = ledCol.withAlpha(baseA);
              canvas.drawCircle(mp, pw * 0.66, _fillPaint);
            }
            _fillPaint.color = const Color(0xFF0A0D14);
            canvas.drawRRect(RRect.fromRectAndRadius(pRect, const Radius.circular(2)), _fillPaint);
            _fillPaint.color = Color.lerp(ledCol, circuit.skyBottom, fogMix * 0.45)!;
            canvas.drawRect(pRect.deflate(max(1.0, pw * 0.14)), _fillPaint);
          }
        }
      }

      // 3E. Astroturf Verge + True 3D Raised Kerbs (Top Face + Vertical Bevel Lip + Cast Shadow on Asphalt)
      final Offset a1LO = _project(-astroOuterW + s1, y1 + 0.02, z1, w, horizonY, fovMult);
      final Offset a2LO = _project(-astroOuterW + s2, y2 + 0.02, z2, w, horizonY, fovMult);
      final Offset a1RO = _project(astroOuterW + s1, y1 + 0.02, z1, w, horizonY, fovMult);
      final Offset a2RO = _project(astroOuterW + s2, y2 + 0.02, z2, w, horizonY, fovMult);

      final Offset k1LO = _project(-kerbOuterW + s1, y1 + 0.125, z1, w, horizonY, fovMult);
      final Offset k2LO = _project(-kerbOuterW + s2, y2 + 0.125, z2, w, horizonY, fovMult);
      final Offset k1RO = _project(kerbOuterW + s1, y1 + 0.125, z1, w, horizonY, fovMult);
      final Offset k2RO = _project(kerbOuterW + s2, y2 + 0.125, z2, w, horizonY, fovMult);

      final Offset k1LI = _project(-roadHalfW - 0.04 + s1, y1 + 0.098, z1, w, horizonY, fovMult);
      final Offset k2LI = _project(-roadHalfW - 0.04 + s2, y2 + 0.098, z2, w, horizonY, fovMult);
      final Offset k1RI = _project(roadHalfW + 0.04 + s1, y1 + 0.098, z1, w, horizonY, fovMult);
      final Offset k2RI = _project(roadHalfW + 0.04 + s2, y2 + 0.098, z2, w, horizonY, fovMult);

      final Offset p1L = _project(-roadHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset p1R = _project(roadHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset p2L = _project(-roadHalfW + s2, y2, z2, w, horizonY, fovMult);
      final Offset p2R = _project(roadHalfW + s2, y2, z2, w, horizonY, fovMult);

      final Color astroCol = Color.lerp(segIndex % 2 == 0 ? const Color(0xFF1A6134) : const Color(0xFF15502A), circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, a1LO, k1LO, k2LO, a2LO, astroCol);
      _drawQuad(canvas, k1RO, a1RO, a2RO, k2RO, astroCol);

      final Color rawKerb = segIndex % 2 == 0 ? circuit.kerbA : circuit.kerbB;
      final Color kerbTopCol = Color.lerp(rawKerb, circuit.skyBottom, fogMix)!;
      final Color kerbLipCol = Color.lerp(Color.lerp(rawKerb, Colors.black, 0.46)!, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, k1LO, k1LI, k2LI, k2LO, kerbTopCol);
      _drawQuad(canvas, k1RI, k1RO, k2RO, k2RI, kerbTopCol);
      if (i < 64) {
        _drawQuad(canvas, k1LI, p1L, p2L, k2LI, kerbLipCol);
        _drawQuad(canvas, p1R, k1RI, k2RI, p2R, kerbLipCol);
        // Glossy clearcoat edge highlight + realistic black apex tire scuff marks along raised 3D kerbs!
        if (i < 46) {
          _strokePaint
            ..color = Color.fromARGB((96 * (1.0 - fogMix)).toInt(), 255, 255, 255)
            ..strokeWidth = max(0.9, 2.2 / z1);
          canvas.drawLine(k1LI, k2LI, _strokePaint);
          canvas.drawLine(k1RI, k2RI, _strokePaint);
          if (kNow.abs() > 0.011) {
            final bool apexRight = kNow > 0;
            final Color scuffCol = Color.fromARGB((82 * (1.0 - fogMix)).toInt(), 8, 10, 14);
            if (apexRight) {
              _drawQuad(canvas, k1RI, Offset.lerp(k1RI, k1RO, 0.58)!, Offset.lerp(k2RI, k2RO, 0.58)!, k2RI, scuffCol);
            } else {
              _drawQuad(canvas, Offset.lerp(k1LI, k1LO, 0.58)!, k1LI, k2LI, Offset.lerp(k2LI, k2LO, 0.58)!, scuffCol);
            }
          }
        }

        // Authentic Raised 3D FIA Yellow/Black Apex Sausage Kerbs on tight corner insides!
        if (kNow.abs() > 0.015 && i < 52 && segIndex % 2 == 0) {
          final bool apexRight = kNow > 0;
          final double skIn = apexRight ? (kerbOuterW + 0.06) : (-kerbOuterW - 0.34);
          final double skOut = apexRight ? (kerbOuterW + 0.34) : (-kerbOuterW - 0.06);
          final Color sausageCol = Color.lerp(
            (segIndex % 4 == 0) ? const Color(0xFFFFD600) : const Color(0xFF141820),
            circuit.skyBottom,
            fogMix,
          )!;
          _drawQuad(
            canvas,
            _project(skIn + s1, y1 + 0.22, z1, w, horizonY, fovMult),
            _project(skOut + s1, y1 + 0.22, z1, w, horizonY, fovMult),
            _project(skOut + s2, y2 + 0.22, z2, w, horizonY, fovMult),
            _project(skIn + s2, y2 + 0.22, z2, w, horizonY, fovMult),
            sausageCol,
          );
        }
      }

      // 3F. Photorealistic 3D Crowned PBR Asphalt + Sector/DRS Markings + Tire Rubber Groove + Specular Sun Glint
      final bool isStartLine = lapDist1 < 5.2;
      final double sec1Dist = lapLen * 0.333;
      final double sec2Dist = lapLen * 0.666;
      final bool isSectorLine = !isStartLine && ((lapDist1 - sec1Dist).abs() < 1.6 || (lapDist1 - sec2Dist).abs() < 1.6);
      final bool isDrsLine = !isStartLine && (lapDist1 > 158.0 && lapDist1 < 161.2);

      final Color rawAsphalt = isStartLine
          ? const Color(0xFFF2F5FA)
          : (segIndex % 2 == 0 ? const Color(0xFF343C4A) : const Color(0xFF2C3340));
      final Color asphaltCol = Color.lerp(rawAsphalt, circuit.skyBottom, fogMix)!;
      if (!isStartLine && i < 60) {
        // Zero-shader-allocation 3-tone PBR crowned asphalt (eliminates 28 shader builds/frame, identical depth!)
        final Color edgeDark = Color.lerp(Color.lerp(rawAsphalt, Colors.black, 0.22)!, circuit.skyBottom, fogMix)!;
        final Color crownHi = Color.lerp(Color.lerp(rawAsphalt, Colors.white, circuit.nightMode ? 0.08 : 0.11)!, circuit.skyBottom, fogMix)!;
        _drawQuad(canvas, p1L, p1R, p2R, p2L, edgeDark);
        _drawQuad(
          canvas,
          Offset.lerp(p1L, p1R, 0.14)!,
          Offset.lerp(p1L, p1R, 0.86)!,
          Offset.lerp(p2L, p2R, 0.86)!,
          Offset.lerp(p2L, p2R, 0.14)!,
          asphaltCol,
        );
        if (i < 24) {
          _drawQuad(
            canvas,
            Offset.lerp(p1L, p1R, 0.32)!,
            Offset.lerp(p1L, p1R, 0.68)!,
            Offset.lerp(p2L, p2R, 0.68)!,
            Offset.lerp(p2L, p2R, 0.32)!,
            crownHi,
          );
        }
      } else {
        _drawQuad(canvas, p1L, p1R, p2R, p2L, asphaltCol);
      }

      // FIA Sector Timing Lines (Red/White) & DRS Activation Line (Bright White + Cyan accent)
      if (isSectorLine && i < 56) {
        _drawQuad(canvas, p1L, p1R, p2R, p2L, Color.lerp(const Color(0xCCE10600), circuit.skyBottom, fogMix)!);
      } else if (isDrsLine && i < 56) {
        _drawQuad(canvas, p1L, p1R, p2R, p2L, Color.lerp(const Color(0xEEFFFFFF), circuit.skyBottom, fogMix)!);
      }

      // Subtle 3D kerb contact shadow onto asphalt edges
      if (i < 55) {
        final Color edgeShad = Color.fromARGB((54 * (1.0 - fogMix)).toInt(), 0, 0, 0);
        final Offset es1L = _project(-roadHalfW + 0.24 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
        final Offset es2L = _project(-roadHalfW + 0.24 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
        final Offset es1R = _project(roadHalfW - 0.24 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
        final Offset es2R = _project(roadHalfW - 0.24 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
        _drawQuad(canvas, p1L, es1L, es2L, p2L, edgeShad);
        _drawQuad(canvas, es1R, p1R, p2R, es2R, edgeShad);
      }

      if (isStartLine && i < 54) {
        final bool alt = (lapDist1 / 2.6).floor() % 2 == 0;
        for (int sq = 0; sq < 8; sq++) {
          if ((sq % 2 == 0) == alt) {
            final double xA = -roadHalfW + (sq * (roadHalfW * 2 / 8));
            final double xB = xA + (roadHalfW * 2 / 8);
            _drawQuad(
              canvas,
              _project(xA + s1, y1, z1, w, horizonY, fovMult),
              _project(xB + s1, y1, z1, w, horizonY, fovMult),
              _project(xB + s2, y2, z2, w, horizonY, fovMult),
              _project(xA + s2, y2, z2, w, horizonY, fovMult),
              Color.lerp(const Color(0xFF141820), circuit.skyBottom, fogMix)!,
            );
          }
        }
      }

      if (!isStartLine && lapDist1 > 10.0 && lapDist1 < 350.0 && i < 58) {
        final double slotMod = (lapDist1 - 14.0) % RaceEngineState.kGridSpacing;
        if (slotMod >= 0.0 && slotMod < 2.2) {
          final int slotIdx = ((lapDist1 - 14.0) / RaceEngineState.kGridSpacing).floor();
          final double boxCenter = (slotIdx % 2 == 0 ? -0.44 : 0.44) * engine.laneToWorldX;
          final Color boxCol = Color.lerp(const Color(0xD8F5F8FC), circuit.skyBottom, fogMix)!;
          final Offset gb1L = _project(boxCenter - 0.72 + s1, y1 + 0.008, z1, w, horizonY, fovMult);
          final Offset gb1R = _project(boxCenter + 0.72 + s1, y1 + 0.008, z1, w, horizonY, fovMult);
          final Offset gb2L = _project(boxCenter - 0.72 + s2, y2 + 0.008, z2, w, horizonY, fovMult);
          final Offset gb2R = _project(boxCenter + 0.72 + s2, y2 + 0.008, z2, w, horizonY, fovMult);
          _strokePaint
            ..color = boxCol
            ..strokeWidth = max(1.0, 4.0 / z1);
          canvas.drawLine(gb2L, gb2R, _strokePaint);
          canvas.drawLine(gb1L, gb2L, _strokePaint);
          canvas.drawLine(gb1R, gb2R, _strokePaint);
          // Official FIA yellow front-wheel contact line inside each starting grid box!
          _strokePaint
            ..color = Color.lerp(const Color(0xEEFFD600), circuit.skyBottom, fogMix)!
            ..strokeWidth = max(1.0, 3.2 / z1);
          canvas.drawLine(Offset.lerp(gb1L, gb2L, 0.78)!, Offset.lerp(gb1R, gb2R, 0.78)!, _strokePaint);
        }
      }

      if (i <= _asphaltClipMaxSlice) {
        _asphaltEdgeL[i] = p1L;
        _asphaltEdgeR[i] = p1R;
        if (i > asphaltClipMaxHit) asphaltClipMaxHit = i;
        if (i == 1) {
          _asphaltEdgeL[0] = p1L;
          _asphaltEdgeR[0] = p1R;
        }
      }

      if (!isStartLine) {
        final double prog1 = lapDist1 / lapLen;
        final double prog2 = _posMod(worldDist2, lapLen) / lapLen;
        final double grooveX1 = engine.geometry.idealLineAtProgress(prog1) * engine.laneToWorldX;
        final double grooveX2 = engine.geometry.idealLineAtProgress(prog2) * engine.laneToWorldX;
        final double targetSpdHere = engine.geometry.targetSpeedAtProgress(prog1);
        final double targetSpdAhead = engine.geometry.targetSpeedAtProgress(_posMod(worldDist1 + 32.0, lapLen) / lapLen);
        final bool isHeavyBrakingZone = (targetSpdHere - targetSpdAhead) > 22.0;

        // Dual real-world F1 wheel-track rubber grooves + crisp heavy-braking lockup skid marks!
        final int rubberAlpha = ((isHeavyBrakingZone ? 78 : 38) * (1.0 - fogMix)).toInt();
        final Color rubberCol = Color.fromARGB(rubberAlpha, 4, 6, 10);
        for (final double wheelOff in const [-0.62, 0.62]) {
          final Offset wt1L = _project(grooveX1 + wheelOff - 0.25 + s1, y1 + 0.005, z1, w, horizonY, fovMult);
          final Offset wt1R = _project(grooveX1 + wheelOff + 0.25 + s1, y1 + 0.005, z1, w, horizonY, fovMult);
          final Offset wt2L = _project(grooveX2 + wheelOff - 0.25 + s2, y2 + 0.005, z2, w, horizonY, fovMult);
          final Offset wt2R = _project(grooveX2 + wheelOff + 0.25 + s2, y2 + 0.005, z2, w, horizonY, fovMult);
          _drawQuad(canvas, wt1L, wt1R, wt2R, wt2L, rubberCol);
        }
        if (isHeavyBrakingZone && i < 50 && segIndex % 3 != 0) {
          final Color skidCol = Color.fromARGB((92 * (1.0 - fogMix)).toInt(), 2, 3, 6);
          final double lockOff = (segIndex % 2 == 0) ? -0.58 : 0.58;
          _strokePaint
            ..color = skidCol
            ..strokeWidth = max(1.2, 6.2 / z1);
          canvas.drawLine(
            _project(grooveX1 + lockOff + s1, y1 + 0.006, z1, w, horizonY, fovMult),
            _project(grooveX2 + lockOff + s2, y2 + 0.006, z2, w, horizonY, fovMult),
            _strokePaint,
          );
        }
        // Authentic Off-Line Rubber Marbles ("Canicas de Goma") darkened strip outside the clean groove!
        if (i < 44) {
          final Color marbleCol = Color.fromARGB((44 * (1.0 - fogMix)).toInt(), 6, 8, 12);
          final Offset m1LI = _project(-roadHalfW + 0.30 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
          final Offset m1LO = _project(-roadHalfW + 1.05 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
          final Offset m2LI = _project(-roadHalfW + 0.30 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
          final Offset m2LO = _project(-roadHalfW + 1.05 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
          final Offset m1RI = _project(roadHalfW - 1.05 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
          final Offset m1RO = _project(roadHalfW - 0.30 + s1, y1 + 0.004, z1, w, horizonY, fovMult);
          final Offset m2RI = _project(roadHalfW - 1.05 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
          final Offset m2RO = _project(roadHalfW - 0.30 + s2, y2 + 0.004, z2, w, horizonY, fovMult);
          _drawQuad(canvas, m1LI, m1LO, m2LO, m2LI, marbleCol);
          _drawQuad(canvas, m1RI, m1RO, m2RO, m2RI, marbleCol);
        }
        // Subtle glossy sky-color reflection sheen across asphalt (dramatic at Sunset & Night GPs!)
        if (i < 48) {
          final int reflA = ((circuit.nightMode ? 22 : (circuit.timeLabel == 'Atardecer' ? 28 : 14)) * (1.0 - fogMix)).toInt();
          final Color reflCol = circuit.skyBottom.withAlpha(reflA.clamp(0, 255).toInt());
          _drawQuad(
            canvas,
            _project(-roadHalfW * 0.62 + s1, y1 + 0.004, z1, w, horizonY, fovMult),
            _project(roadHalfW * 0.62 + s1, y1 + 0.004, z1, w, horizonY, fovMult),
            _project(roadHalfW * 0.62 + s2, y2 + 0.004, z2, w, horizonY, fovMult),
            _project(-roadHalfW * 0.62 + s2, y2 + 0.004, z2, w, horizonY, fovMult),
            reflCol,
          );
        }

        // PBR Directional Sun Specular Glint / Night Floodlight Pool on Asphalt
        final bool lightPool = circuit.nightMode && (segIndex % 9 == 0 || segIndex % 9 == 1);
        final int sheenAlpha = ((lightPool ? 66 : (circuit.nightMode ? 24 : 26)) * (1.0 - fogMix)).toInt();
        final double sheenCenter = lightPool ? 0.0 : (sunNormX * 1.15);
        final double shW = lightPool ? 1.85 : 0.78;
        final Offset sh1L = _project(sheenCenter - shW + s1, y1 + 0.007, z1, w, horizonY, fovMult);
        final Offset sh1R = _project(sheenCenter + shW + s1, y1 + 0.007, z1, w, horizonY, fovMult);
        final Offset sh2L = _project(sheenCenter - shW + s2, y2 + 0.007, z2, w, horizonY, fovMult);
        final Offset sh2R = _project(sheenCenter + shW + s2, y2 + 0.007, z2, w, horizonY, fovMult);
        _drawQuad(
          canvas,
          sh1L,
          sh1R,
          sh2R,
          sh2L,
          Color.fromARGB(sheenAlpha, lightPool ? 225 : 255, lightPool ? 245 : 250, lightPool ? 255 : 235),
        );
      }

      // Crisp White FIA Track-Limit Boundary Lines
      _strokePaint
        ..color = Color.lerp(const Color(0xF5F7FAFE), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.0, 4.8 / z1);
      canvas.drawLine(p1L, p2L, _strokePaint);
      canvas.drawLine(p1R, p2R, _strokePaint);

      // 3G. Optional Dynamic Racing Line painted seamlessly onto the 3D asphalt
      if (RaceEngineState.showRacingLine && i < segCount - 8) {
        final double prog1 = lapDist1 / lapLen;
        final double prog2 = _posMod(worldDist2, lapLen) / lapLen;
        final double lineWorldX1 = engine.geometry.idealLineAtProgress(prog1) * engine.laneToWorldX;
        final double lineWorldX2 = engine.geometry.idealLineAtProgress(prog2) * engine.laneToWorldX;
        final double targetSpd = engine.geometry.targetSpeedAtProgress(prog1);

        final double overKmh = engine.speedKmh - targetSpd;
        Color guideColor;
        if (overKmh <= -12.0) {
          guideColor = const Color(0xFF00E676);
        } else if (overKmh < 12.0) {
          final double t = ((overKmh + 12.0) / 24.0).clamp(0.0, 1.0).toDouble();
          guideColor = Color.lerp(const Color(0xFF00E676), const Color(0xFFFFD600), t)!;
        } else if (overKmh < 34.0) {
          final double t = ((overKmh - 12.0) / 22.0).clamp(0.0, 1.0).toDouble();
          guideColor = Color.lerp(const Color(0xFFFFD600), const Color(0xFFFF1744), t)!;
        } else {
          guideColor = const Color(0xFFFF1744);
        }

        final bool isDash = (segIndex % 2 == 0);
        final double baseAlpha = (isDash ? 0.56 : 0.22) * (1.0 - fogMix);
        final Color outerRibbonCol = Color.lerp(guideColor, circuit.skyBottom, fogMix * 0.65)!
            .withAlpha((baseAlpha * 255.0).clamp(0.0, 255.0).toInt());
        const double lineHalfW = 0.25;
        final Offset rl1L = _project(lineWorldX1 - lineHalfW + s1, y1 + 0.012, z1, w, horizonY, fovMult);
        final Offset rl1R = _project(lineWorldX1 + lineHalfW + s1, y1 + 0.012, z1, w, horizonY, fovMult);
        final Offset rl2L = _project(lineWorldX2 - lineHalfW + s2, y2 + 0.012, z2, w, horizonY, fovMult);
        final Offset rl2R = _project(lineWorldX2 + lineHalfW + s2, y2 + 0.012, z2, w, horizonY, fovMult);
        _drawQuad(canvas, rl1L, rl1R, rl2R, rl2L, outerRibbonCol);

        if (isDash && i < 60) {
          const double coreHalfW = 0.085;
          final Color coreCol = Color.lerp(guideColor, Colors.white, 0.35)!
              .withAlpha(((0.74 * (1.0 - fogMix)) * 255.0).clamp(0.0, 255.0).toInt());
          final Offset rc1L = _project(lineWorldX1 - coreHalfW + s1, y1 + 0.016, z1, w, horizonY, fovMult);
          final Offset rc1R = _project(lineWorldX1 + coreHalfW + s1, y1 + 0.016, z1, w, horizonY, fovMult);
          final Offset rc2L = _project(lineWorldX2 - coreHalfW + s2, y2 + 0.016, z2, w, horizonY, fovMult);
          final Offset rc2R = _project(lineWorldX2 + coreHalfW + s2, y2 + 0.016, z2, w, horizonY, fovMult);
          _drawQuad(canvas, rc1L, rc1R, rc2R, rc2L, coreCol);
        }
      }

      // 3H. WORLD-ANCHORED 3D Braking Marker Boards (150 / 100 / 50 pinned strictly to world meters!)
      final int brakeBucket = (worldDist1 / 28.0).floor();
      if (brakeBucket != lastBrakeBucket && i > 3 && i < 70) {
        lastBrakeBucket = brakeBucket;
        final double aheadK50 = _kappaAtWorldDist(worldDist1 + 55.0);
        final double aheadK100 = _kappaAtWorldDist(worldDist1 + 105.0);
        final double aheadK150 = _kappaAtWorldDist(worldDist1 + 155.0);
        if (kNow.abs() < 0.008) {
          String? markerTxt;
          double markerK = 0.0;
          if (aheadK50.abs() > 0.016) {
            markerTxt = '50';
            markerK = aheadK50;
          } else if (aheadK100.abs() > 0.016) {
            markerTxt = '100';
            markerK = aheadK100;
          } else if (aheadK150.abs() > 0.016) {
            markerTxt = '150';
            markerK = aheadK150;
          }
          if (markerTxt != null) {
            final bool onLeft = markerK > 0;
            final double sideWall = onLeft ? run1L : run1R;
            final double boardOff = min(sideWall - 0.35, roadHalfW + 2.65);
            final double bx = (onLeft ? -boardOff : boardOff) + s1;
            _drawBrakingBoard(canvas, bx, y1, z1, w, horizonY, fovMult, markerTxt, fogMix);
          }
        }
      }

      // 3I. WORLD-ANCHORED 3D Trackside Props, Stadium Floodlights & Trees positioned BEHIND the real outer barriers!
      final int propBucket = (worldDist1 / 32.0).floor();
      if (propBucket != lastPropBucket && i < segCount - 8) {
        lastPropBucket = propBucket;
        final bool inGsLeft = (gsLocal >= 10.0 && gsLocal <= 56.0 && gsBlock % 2 == 0);
        final bool inGsRight = (gsLocal >= 10.0 && gsLocal <= 56.0 && gsBlock % 2 == 1);
        if (!inGsLeft) {
          _drawTracksideProp3D(canvas, -wallCap1L - 2.35 + s1, y1, z1, w, horizonY, fovMult, fogMix, circuit, true, propBucket);
        }
        if (!inGsRight && !onPitStraight) {
          _drawTracksideProp3D(canvas, wallCap1R + 2.35 + s1, y1, z1, w, horizonY, fovMult, fogMix, circuit, false, propBucket + 17);
        }
      }

      // 3J. DEPTH-INTERLEAVED TRUE-3D SURFACE-CONFORMING F1 CARS (Rivals + Player Chase Car grounded 100% flush on the 3D track!)
      final List<AiDriver> sliceRivals = _rivalsBySlice[i];
      final bool drawPlayerHere = (!cockpit && i == playerChaseSlice);
      if (sliceRivals.isNotEmpty || drawPlayerHere) {
        bool playerDrawn = !drawPlayerHere;
        for (final ai in sliceRivals) {
          // Draw player car in exact back-to-front order if wheel-to-wheel in same slice!
          if (!playerDrawn && ai.trackDist < engine.playerDist) {
            _drawPlayerTrue3DChaseCar(
              canvas,
              playerChaseZ,
              baseCamHeight,
              camShift,
              w,
              horizonY,
              fovMult,
              sunNormX,
            );
            playerDrawn = true;
          }
          final double rz = (ai.trackDist - camOriginDist) / 2.0;
          _drawRivalTrue3DCar(
            canvas,
            rz,
            baseCamHeight,
            camShift,
            w,
            horizonY,
            fovMult,
            kNow,
            fogMix * 0.68,
            sunNormX,
            ai,
          );
        }
        if (!playerDrawn) {
          _drawPlayerTrue3DChaseCar(
            canvas,
            playerChaseZ,
            baseCamHeight,
            camShift,
            w,
            horizonY,
            fovMult,
            sunNormX,
          );
        }
      }

      // 3K. WORLD-ANCHORED 3D Overhead Sponsor Bridges (Drawn AFTER rivals at this slice -> true 3D overpass!)
      final int archBucket = (worldDist1 / 380.0).floor();
      final double archLocal = lapDist1 % 380.0;
      if (!isStartLine && archLocal < 12.0 && archBucket != lastArchBucket && i > 2 && i < 76) {
        lastArchBucket = archBucket;
        _draw3DSponsorArch(
          canvas,
          s1,
          s2,
          y1,
          y2,
          z1,
          z2,
          roadHalfW,
          w,
          horizonY,
          fovMult,
          fogMix,
          circuit,
          archBucket,
        );
      }

      // 3L. True 3D Start/Finish Truss Gantry with Live Red Start Lights & Overpass Depth
      if (isStartLine && !drewStartGantry && i > 2 && i < 74) {
        drewStartGantry = true;
        _drawStartGantry3D(canvas, s1, s2, y1, y2, z1, z2, roadHalfW, w, horizonY, fovMult, fogMix, circuit);
      }
    }

    // Fast Axis-Aligned Rect Turf / Sand / Gravel Micro-Grain (ZERO stencil GPU overhead, identical grain!)
    if (_turfTexPaint != null && topRunoffY < h) {
      final double turfTop = max(horizonY, topRunoffY);
      canvas.save();
      canvas.clipRect(Rect.fromLTWH(0, turfTop, w, h - turfTop));
      final double turfScrollY = (engine.playerDist * 20.0) % 512.0;
      canvas.translate(0, turfScrollY);
      canvas.drawRect(Rect.fromLTWH(0, turfTop - 512, w, h - turfTop + 1024), _turfTexPaint!);
      canvas.restore();
    }

    // Single-Contour Clean Polygon Asphalt Micro-Aggregate Texture (~85% faster GPU stencil pass!)
    if (_asphaltTexPaint != null && asphaltClipMaxHit >= 2) {
      _asphaltClipPath
        ..reset()
        ..moveTo(_asphaltEdgeL[1].dx, _asphaltEdgeL[1].dy);
      for (int k = 2; k <= asphaltClipMaxHit; k += 2) {
        _asphaltClipPath.lineTo(_asphaltEdgeL[k].dx, _asphaltEdgeL[k].dy);
      }
      _asphaltClipPath.lineTo(_asphaltEdgeL[asphaltClipMaxHit].dx, _asphaltEdgeL[asphaltClipMaxHit].dy);
      _asphaltClipPath.lineTo(_asphaltEdgeR[asphaltClipMaxHit].dx, _asphaltEdgeR[asphaltClipMaxHit].dy);
      for (int k = asphaltClipMaxHit - 1; k >= 1; k -= 2) {
        _asphaltClipPath.lineTo(_asphaltEdgeR[k].dx, _asphaltEdgeR[k].dy);
      }
      _asphaltClipPath
        ..lineTo(_asphaltEdgeR[1].dx, _asphaltEdgeR[1].dy)
        ..close();

      canvas.save();
      canvas.clipPath(_asphaltClipPath);
      final double scrollY = (engine.playerDist * 34.0) % 1024.0;
      canvas.translate(0, scrollY);
      canvas.drawRect(Rect.fromLTWH(0, horizonY - 1024, w, h - horizonY + 2048), _asphaltTexPaint!);
      canvas.restore();
    }

    // Soft Atmospheric Horizon Mist Ribbon + Warm/Cool Aerial Depth Haze (reused _gradPaint!)
    final Rect mistRect = Rect.fromLTWH(0, horizonY - 22, w, 46);
    _gradPaint.shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      stops: const [0.0, 0.45, 1.0],
      colors: [
        circuit.skyBottom.withAlpha(0),
        circuit.skyBottom.withAlpha(195),
        circuit.skyBottom.withAlpha(0),
      ],
    ).createShader(mistRect);
    canvas.drawRect(mistRect, _gradPaint);

    // Subtle Cinematic Solar Lens Flare when facing toward the sun (day / sunset circuits)
    if (!circuit.nightMode && sunX > w * 0.08 && sunX < w * 0.92) {
      final Offset sunPt = Offset(sunX, horizonY * 0.28);
      final Offset screenMid = Offset(w * 0.5, h * 0.52);
      final double centerProx = (1.0 - ((sunX - w * 0.5).abs() / (w * 0.48))).clamp(0.0, 1.0).toDouble();
      if (centerProx > 0.12) {
        final Offset f1 = Offset.lerp(sunPt, screenMid, 0.55)!;
        final Offset f2 = Offset.lerp(sunPt, screenMid, 1.18)!;
        final double r1 = 36.0 * centerProx;
        final double r2 = 22.0 * centerProx;
        _gradPaint.shader = RadialGradient(
          colors: [
            Color.fromARGB((42 * centerProx).toInt(), 255, 232, 165),
            const Color(0x00FFE8A5),
          ],
        ).createShader(Rect.fromCircle(center: f1, radius: r1));
        canvas.drawCircle(f1, r1, _gradPaint);
        _gradPaint.shader = RadialGradient(
          colors: [
            Color.fromARGB((34 * centerProx).toInt(), 160, 225, 255),
            const Color(0x00A0E1FF),
          ],
        ).createShader(Rect.fromCircle(center: f2, radius: r2));
        canvas.drawCircle(f2, r2, _gradPaint);
        // Cinematic Horizontal Anamorphic Broadcast Camera Streak across Sun!
        final Rect anaRect = Rect.fromCenter(center: sunPt, width: w * 0.56 * centerProx, height: 10.0);
        _gradPaint.shader = LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          stops: const [0.0, 0.5, 1.0],
          colors: [
            const Color(0x00FFF0C8),
            Color.fromARGB((54 * centerProx).toInt(), 255, 244, 210),
            const Color(0x00FFF0C8),
          ],
        ).createShader(anaRect);
        canvas.drawRect(anaRect, _gradPaint);
      }
    }

    // 4. Incandescent Sparks (Glowing Outer Trail + White-Hot Core) & Gravel/Grass Particles
    for (final p in engine.particles) {
      final Offset pt = Offset(p.x * w, p.y * h);
      if (p.isSpark) {
        final Offset tail = Offset(pt.dx - p.vx * 16, pt.dy - p.vy * 16);
        _strokePaint
          ..color = p.color.withAlpha(185)
          ..strokeWidth = p.radius * 1.7
          ..strokeCap = StrokeCap.round;
        canvas.drawLine(pt, tail, _strokePaint);
        _strokePaint
          ..color = const Color(0xF5FFFDE7)
          ..strokeWidth = max(1.0, p.radius * 0.65);
        canvas.drawLine(pt, Offset.lerp(pt, tail, 0.55)!, _strokePaint);
      } else {
        _fillPaint.color = p.color;
        canvas.drawCircle(pt, p.radius, _fillPaint);
      }
    }

    canvas.restore();

    // 5. Photorealistic 3D Cockpit Overlay (Chase Car is already rendered inside the True-3D World Spine above!)
    if (cockpit) {
      _drawCockpitUltra(canvas, w, h, sunNormX, circuit);
    }

    // 6. High-Speed Radial Perspective Motion Streaks + Curved Aerodynamic Slipstream/ERS Wind Ribbons!
    final bool ersOn = engine.ersActive;
    if (engine.speedKmh > 230 || ersOn || engine.playerInSlipstream) {
      final double alphaFrac = ((engine.speedKmh - 220) / 130.0).clamp(0.16, 0.78).toDouble();
      final Color streakCol = ersOn
          ? Color.fromARGB((alphaFrac * 145).toInt(), 0, 229, 255)
          : (engine.playerInSlipstream
              ? Color.fromARGB((alphaFrac * 124).toInt(), 105, 240, 174)
              : Color.fromARGB((alphaFrac * 90).toInt(), 255, 255, 255));
      _strokePaint
        ..color = streakCol
        ..strokeWidth = ersOn ? 2.0 : 1.6
        ..strokeCap = StrokeCap.round;
      for (int k = 0; k < 16; k++) {
        final bool isLeftEdge = k.isEven;
        final double ang = isLeftEdge ? (pi * 0.72 + (k * 0.038)) : (pi * 0.28 - (k * 0.038));
        final double distR = (w * 0.34) + ((engine.playerDist * 44.0 + k * 67.0) % (w * 0.28));
        final Offset a = Offset(w * 0.5 + cos(ang) * distR, horizonY + sin(ang) * distR * 0.65);
        final Offset b = Offset(w * 0.5 + cos(ang) * (distR + 62.0), horizonY + sin(ang) * (distR + 62.0) * 0.65);
        canvas.drawLine(a, b, _strokePaint);
      }
      // Subtle curved slipstream / ERS air-flow arcs sweeping past the peripheral visor (zero Path alloc!)
      if (ersOn || engine.playerInSlipstream) {
        _strokePaint
          ..color = streakCol.withAlpha((streakCol.alpha * 0.55).toInt())
          ..strokeWidth = 2.4;
        final double flowPhase = (engine.totalRaceTime * 10.0) % 1.0;
        for (final double sDir in const [-1.0, 1.0]) {
          _scratchPath
            ..reset()
            ..moveTo(w * (0.5 + sDir * (0.20 + flowPhase * 0.06)), horizonY + 18)
            ..quadraticBezierTo(w * (0.5 + sDir * 0.42), h * 0.56, w * (0.5 + sDir * 0.52), h * 0.86);
          canvas.drawPath(_scratchPath, _strokePaint);
        }
      }
    }

    // 7. Cached Film-Grade Atmospheric Color Grading Wash (ZERO per-frame shader allocations!)
    if (_colorGradePaint != null) {
      canvas.drawRect(Rect.fromLTWH(0, 0, w, h), _colorGradePaint!);
    }

    if (_vignettePaint != null) {
      canvas.drawRect(Rect.fromLTWH(0, 0, w, h), _vignettePaint!);
    }

    if (engine.hitFlash > 0) {
      _gradPaint.shader = RadialGradient(
        radius: 0.95,
        colors: [
          const Color(0x00FF0000),
          Color.fromARGB((engine.hitFlash * 165).toInt(), 255, 18, 18),
        ],
      ).createShader(Rect.fromLTWH(0, 0, w, h));
      canvas.drawRect(Rect.fromLTWH(0, 0, w, h), _gradPaint);
    }
  }

  void _drawQuad(Canvas canvas, Offset a, Offset b, Offset c, Offset d, Color color) {
    _quadPath
      ..reset()
      ..moveTo(a.dx, a.dy)
      ..lineTo(b.dx, b.dy)
      ..lineTo(c.dx, c.dy)
      ..lineTo(d.dx, d.dy)
      ..close();
    _fillPaint.color = color;
    canvas.drawPath(_quadPath, _fillPaint);
  }

  void _drawBrakingBoard(
    Canvas canvas,
    double x,
    double y1,
    double z,
    double w,
    double horizonY,
    double fovMult,
    String text,
    double fogMix,
  ) {
    final Offset base = _project(x, y1, z, w, horizonY, fovMult);
    final Offset top = _project(x, y1 + 1.55, z, w, horizonY, fovMult);
    final double bh = max(6.0, base.dy - top.dy);
    final double bw = bh * 1.18;
    if (bw < 8.0) return;

    // Ground shadow
    _fillPaint.color = Color.fromARGB((68 * (1.0 - fogMix)).toInt(), 0, 0, 0);
    canvas.drawOval(Rect.fromCenter(center: base, width: bw * 1.1, height: max(2.0, bw * 0.20)), _fillPaint);

    _strokePaint
      ..color = Color.lerp(const Color(0xFF1A202B), engine.circuit.skyBottom, fogMix)!
      ..strokeWidth = max(1.4, bw * 0.09);
    canvas.drawLine(Offset(base.dx, base.dy), Offset(top.dx, top.dy + bh * 0.68), _strokePaint);

    final Rect board = Rect.fromLTWH(top.dx - bw * 0.5, top.dy, bw, bh * 0.68);
    // 3D depth edge
    _fillPaint.color = Color.lerp(const Color(0xFF7D8B9E), engine.circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTWH(board.right, board.top + 1.0, max(1.8, bw * 0.11), board.height - 1.0), _fillPaint);

    _fillPaint.color = Color.lerp(const Color(0xFFF6F8FC), engine.circuit.skyBottom, fogMix)!;
    canvas.drawRect(board, _fillPaint);
    _strokePaint
      ..color = Color.lerp(const Color(0xFFE10600), engine.circuit.skyBottom, fogMix)!
      ..strokeWidth = max(1.1, bw * 0.085);
    canvas.drawRect(board, _strokePaint);
    if (bw > 15.0) {
      final TextPainter tp = _getCachedBoardText(text, (bh * 0.36).clamp(7.0, 16.0).toDouble(), const Color(0xFF11141A));
      tp.paint(canvas, Offset(board.center.dx - tp.width * 0.5, board.center.dy - tp.height * 0.5));
    }
  }

  /// Next-Gen Multi-Slice Extruded 3D Grandstand (VIP Skybox Glass, Textured Crowd, LED Roof Strip & Steel Trusses!)
  void _draw3DExtrudedGrandstandSlice(
    Canvas canvas,
    double baseX1,
    double baseX2,
    double s1,
    double s2,
    double y1,
    double y2,
    double z1,
    double z2,
    bool isLeft,
    int segIndex,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
  ) {
    final double dir = isLeft ? -1.0 : 1.0;
    const double deckDepth = 6.6;
    const double frontH = 1.50;
    const double backH = 5.45;
    const double roofH = 6.75;

    final Offset fb1 = _project(baseX1 + s1, y1, z1, w, horizonY, fovMult);
    final Offset fb2 = _project(baseX2 + s2, y2, z2, w, horizonY, fovMult);
    final Offset ft1 = _project(baseX1 + s1, y1 + frontH, z1, w, horizonY, fovMult);
    final Offset ft2 = _project(baseX2 + s2, y2 + frontH, z2, w, horizonY, fovMult);

    final Offset bt1 = _project(baseX1 + dir * deckDepth + s1, y1 + backH, z1, w, horizonY, fovMult);
    final Offset bt2 = _project(baseX2 + dir * deckDepth + s2, y2 + backH, z2, w, horizonY, fovMult);

    final Offset rf1 = _project(baseX1 - dir * 1.25 + s1, y1 + roofH, z1, w, horizonY, fovMult);
    final Offset rf2 = _project(baseX2 - dir * 1.25 + s2, y2 + roofH, z2, w, horizonY, fovMult);
    final Offset rb1 = _project(baseX1 + dir * (deckDepth + 0.7) + s1, y1 + roofH + 0.48, z1, w, horizonY, fovMult);
    final Offset rb2 = _project(baseX2 + dir * (deckDepth + 0.7) + s2, y2 + roofH + 0.48, z2, w, horizonY, fovMult);

    // 1. Architectural Concrete Front Facade Wall + Sponsor Banner + Glowing Upper Rail
    final Color wallCol = Color.lerp(
      circuit.nightMode ? const Color(0xFF172033) : const Color(0xFF424E61),
      circuit.skyBottom,
      fogMix,
    )!;
    _drawQuad(canvas, fb1, ft1, ft2, fb2, wallCol);

    final Offset fs1 = _project(baseX1 + s1, y1 + frontH * 0.68, z1, w, horizonY, fovMult);
    final Offset fs2 = _project(baseX2 + s2, y2 + frontH * 0.68, z2, w, horizonY, fovMult);
    _drawQuad(canvas, fs1, ft1, ft2, fs2, Color.lerp(circuit.kerbA, circuit.skyBottom, fogMix)!);

    // 2. Sloped 3D Seating Deck + High-Res Crowd Texture Overlay
    final Color deckCol = Color.lerp(
      circuit.nightMode ? const Color(0xFF0E1526) : const Color(0xFF27303E),
      circuit.skyBottom,
      fogMix,
    )!;
    _drawQuad(canvas, ft1, bt1, bt2, ft2, deckCol);

    if (UltraTextures.crowdShader != null && fogMix < 0.58) {
      _quadPath
        ..reset()
        ..moveTo(ft1.dx, ft1.dy)
        ..lineTo(bt1.dx, bt1.dy)
        ..lineTo(bt2.dx, bt2.dy)
        ..lineTo(ft2.dx, ft2.dy)
        ..close();
      _gradPaint.shader = UltraTextures.crowdShader;
      canvas.drawPath(_quadPath, _gradPaint);
    }

    // 3. Perspective Tiered Crowd & Vibrant Flag Rows along the sloped 3D deck
    const List<Color> crowdTones = [
      Color(0xFFE53935),
      Color(0xFFF5F7FA),
      Color(0xFF1E88E5),
      Color(0xFFFFCA28),
      Color(0xFF43A047),
      Color(0xFFFF6F00),
    ];
    for (int tier = 0; tier < 5; tier++) {
      final double fA = 0.08 + tier * 0.17;
      final double fB = fA + 0.09;
      final Offset p1A = Offset.lerp(ft1, bt1, fA)!;
      final Offset p2A = Offset.lerp(ft2, bt2, fA)!;
      final Offset p1B = Offset.lerp(ft1, bt1, fB)!;
      final Offset p2B = Offset.lerp(ft2, bt2, fB)!;
      final Color rowRaw = crowdTones[(segIndex + tier * 2).abs() % crowdTones.length];
      _drawQuad(canvas, p1A, p1B, p2B, p2A, Color.lerp(rowRaw, circuit.skyBottom, fogMix * 0.80 + 0.10)!);
    }

    // 4. Illuminated VIP Paddock Club Glass Skybox at Top Rear of Grandstand
    final Offset skyB1 = Offset.lerp(ft1, bt1, 0.86)!;
    final Offset skyB2 = Offset.lerp(ft2, bt2, 0.86)!;
    final Color vipGlass = circuit.nightMode
        ? (segIndex % 3 == 0 ? const Color(0xFF56C8FF) : const Color(0xFFFFE082))
        : const Color(0xFF8CB8D8);
    _drawQuad(canvas, skyB1, bt1, bt2, skyB2, Color.lerp(vipGlass, circuit.skyBottom, fogMix * 0.75 + 0.12)!);

    // 5. Cantilevered 3D Roof Canopy (Shaded underside + glowing LED fascia + steel truss ribs!)
    _drawQuad(
      canvas,
      rf1,
      rb1,
      rb2,
      rf2,
      Color.lerp(circuit.nightMode ? const Color(0xFF1D2840) : const Color(0xFF8494AA), circuit.skyBottom, fogMix)!,
    );
    _strokePaint
      ..color = Color.lerp(circuit.nightMode ? const Color(0xEE69F0FF) : const Color(0xFFF0F5FC), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(1.4, 12.0 / z1);
    canvas.drawLine(rf1, rf2, _strokePaint);

    // 6. Structural Steel Support Columns & Diagonal Roof Braces every 4 slices
    if (segIndex % 4 == 0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF1B2434), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.4, 14.0 / z1);
      canvas.drawLine(bt1, rb1, _strokePaint);
      canvas.drawLine(rb1, rf1, _strokePaint);
      _strokePaint
        ..color = Color.lerp(const Color(0x884B5D78), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(0.9, 6.5 / z1);
      canvas.drawLine(bt1, Offset.lerp(rb1, rf1, 0.52)!, _strokePaint);
    }
  }

  void _draw3DSponsorArch(
    Canvas canvas,
    double s1,
    double s2,
    double y1,
    double y2,
    double z1,
    double z2,
    double roadHalfW,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
    int archIndex,
  ) {
    final double spanX = roadHalfW + 1.55;
    // Crisp dark ground shadow across the entire asphalt
    final Offset sh1L = _project(-roadHalfW + s1, y1 + 0.015, z1, w, horizonY, fovMult);
    final Offset sh1R = _project(roadHalfW + s1, y1 + 0.015, z1, w, horizonY, fovMult);
    final Offset sh2L = _project(-roadHalfW + s2, y2 + 0.015, z2, w, horizonY, fovMult);
    final Offset sh2R = _project(roadHalfW + s2, y2 + 0.015, z2, w, horizonY, fovMult);
    _drawQuad(canvas, sh1L, sh1R, sh2R, sh2L, Color.fromARGB((108 * (1.0 - fogMix)).toInt(), 0, 0, 0));

    final Offset bL = _project(-spanX + s1, y1, z1, w, horizonY, fovMult);
    final Offset bR = _project(spanX + s1, y1, z1, w, horizonY, fovMult);
    final Offset bLBack = _project(-spanX + s2, y2, z2, w, horizonY, fovMult);
    final Offset bRBack = _project(spanX + s2, y2, z2, w, horizonY, fovMult);
    final Offset tL = _project(-spanX + s1, y1 + 4.35, z1, w, horizonY, fovMult);
    final Offset tR = _project(spanX + s1, y1 + 4.35, z1, w, horizonY, fovMult);
    final Offset tLBack = _project(-spanX + s2, y2 + 4.35, z2, w, horizonY, fovMult);
    final Offset tRBack = _project(spanX + s2, y2 + 4.35, z2, w, horizonY, fovMult);
    final double beamH = max(8.0, 82.0 / z1);

    // 3D Thickened Steel Towers (front + depth side + metallic highlight edge)
    _drawQuad(canvas, bL, tL, tLBack, bLBack, Color.lerp(const Color(0xFF141A24), circuit.skyBottom, fogMix)!);
    _drawQuad(canvas, bR, bRBack, tRBack, tR, Color.lerp(const Color(0xFF141A24), circuit.skyBottom, fogMix)!);
    _strokePaint
      ..color = Color.lerp(const Color(0xFF344157), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(3.5, 34.0 / z1);
    canvas.drawLine(bL, tL, _strokePaint);
    canvas.drawLine(bR, tR, _strokePaint);
    // Steel cross-brace struts on towers
    if (beamH > 12.0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xAA6A7E9C), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.0, 6.0 / z1);
      for (int tr = 0; tr < 3; tr++) {
        final double f0 = tr / 3.0;
        final double f1 = (tr + 1) / 3.0;
        canvas.drawLine(Offset.lerp(bL, tL, f0)!, Offset.lerp(bLBack, tLBack, f1)!, _strokePaint);
        canvas.drawLine(Offset.lerp(bR, tR, f0)!, Offset.lerp(bRBack, tRBack, f1)!, _strokePaint);
      }
    }

    // 3D Bridge Underside Slab
    _drawQuad(
      canvas,
      Offset(tL.dx, tL.dy + beamH * 0.52),
      Offset(tR.dx, tR.dy + beamH * 0.52),
      Offset(tRBack.dx, tRBack.dy + beamH * 0.44),
      Offset(tLBack.dx, tLBack.dy + beamH * 0.44),
      Color.lerp(const Color(0xFF090C12), circuit.skyBottom, fogMix)!,
    );

    final Rect bridge = Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.52, tR.dx, tR.dy + beamH * 0.52);
    final bool altBrand = archIndex % 2 == 0;
    final Color brandBg = altBrand ? const Color(0xFF0E1422) : circuit.kerbA;
    final Color brandBgHi = Color.lerp(brandBg, Colors.white, 0.22)!;
    final Color brandAccent = altBrand ? const Color(0xFFFFD54F) : const Color(0xFFFFFFFF);
    _gradPaint.shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      colors: [
        Color.lerp(brandBgHi, circuit.skyBottom, fogMix)!,
        Color.lerp(brandBg, circuit.skyBottom, fogMix)!,
        Color.lerp(Color.lerp(brandBg, Colors.black, 0.30)!, circuit.skyBottom, fogMix)!,
      ],
    ).createShader(bridge);
    canvas.drawRect(bridge, _gradPaint);
    _fillPaint.color = Color.lerp(brandAccent, circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTRB(bridge.left, bridge.top, bridge.right, bridge.top + beamH * 0.16), _fillPaint);
    canvas.drawRect(Rect.fromLTRB(bridge.left, bridge.bottom - beamH * 0.12, bridge.right, bridge.bottom), _fillPaint);

    if (beamH > 13.0) {
      final String label = altBrand ? 'APEX GP 24  •  PIRELLI' : 'FORMULA PRO  •  ${circuit.code}';
      final TextPainter tp = _getCachedBoardText(
        label,
        (beamH * 0.35).clamp(8.0, 22.0).toDouble(),
        Color.lerp(Colors.white, circuit.skyBottom, fogMix)!,
      );
      tp.paint(canvas, Offset(bridge.center.dx - tp.width * 0.5, bridge.center.dy - tp.height * 0.5));
    }
  }

  void _drawProEnvironment(Canvas canvas, double w, double h, double horizonY, double sunX, CircuitInfo circuit) {
    final Color skyUpperMid = Color.lerp(circuit.skyTop, circuit.skyBottom, 0.34)!;
    final Color skyLowerMid = Color.lerp(circuit.skyTop, circuit.skyBottom, 0.72)!;
    final Color horizonGlow = Color.lerp(circuit.skyBottom, Colors.white, circuit.nightMode ? 0.09 : 0.34)!;
    final Rect skyRect = Rect.fromLTWH(0, 0, w, horizonY + 8);
    _gradPaint.shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      stops: const [0.0, 0.32, 0.68, 0.90, 1.0],
      colors: [circuit.skyTop, skyUpperMid, skyLowerMid, circuit.skyBottom, horizonGlow],
    ).createShader(skyRect);
    canvas.drawRect(skyRect, _gradPaint);

    final Offset sunCenter = Offset(sunX, horizonY * 0.28);
    final double haloR = circuit.nightMode ? 76.0 : 240.0;
    _gradPaint.shader = RadialGradient(
      stops: const [0.0, 0.14, 0.42, 0.75, 1.0],
      colors: circuit.nightMode
          ? const [Color(0xF0F4FAFF), Color(0xAA9ED0FF), Color(0x3666A8FF), Color(0x104080FF), Color(0x00000000)]
          : const [Color(0xFFFFFFFF), Color(0xE8FFF5C8), Color(0x66FFD888), Color(0x22FFC470), Color(0x00FFD285)],
    ).createShader(Rect.fromCircle(center: sunCenter, radius: haloR));
    canvas.drawCircle(sunCenter, haloR, _gradPaint);

    if (circuit.nightMode) {
      // Sweeping Stadium Sky-Beams + Horizon Light Pollution + Multi-Magnitude Twinkling Starfield
      for (int beam = 0; beam < 4; beam++) {
        final double bx = ((beam * (w * 0.31) + engine.horizonPan * 0.22) % (w + 140) + (w + 140)) % (w + 140) - 70;
        final double lean = (beam.isEven ? 1.0 : -1.0) * 58.0;
        _drawQuad(
          canvas,
          Offset(bx - 6.0, horizonY),
          Offset(bx + 6.0, horizonY),
          Offset(bx + lean + 28.0, 0.0),
          Offset(bx + lean - 28.0, 0.0),
          const Color(0x1680D8FF),
        );
      }
      final Rect nGlowRect = Rect.fromLTWH(0, horizonY - 62, w, 64);
      _gradPaint.shader = const LinearGradient(
        begin: Alignment.bottomCenter,
        end: Alignment.topCenter,
        colors: [Color(0x5240C4FF), Color(0x181A4480), Color(0x00000000)],
      ).createShader(nGlowRect);
      canvas.drawRect(nGlowRect, _gradPaint);
      for (int s = 0; s < 78; s++) {
        final double sx = ((s * 83.0 + engine.horizonPan * 0.06) % w + w) % w;
        final double sy = (s * 29.0) % (horizonY * 0.72);
        final double twinkle = 0.55 + 0.45 * sin(engine.totalRaceTime * 2.4 + s * 1.7);
        _fillPaint.color = Color.fromARGB((220 * twinkle).toInt(), s % 7 == 0 ? 185 : 255, s % 9 == 0 ? 225 : 255, 255);
        canvas.drawCircle(Offset(sx, sy), (s % 6 == 0) ? 1.75 : 0.90, _fillPaint);
      }
    } else {
      // Subtle Volumetric Sun Rays fanning gently across the sky
      for (int r = -2; r <= 2; r++) {
        final double ang = pi * 0.34 + r * 0.22;
        final Offset tipA = Offset(sunCenter.dx + cos(ang - 0.06) * 280.0, sunCenter.dy + sin(ang - 0.06) * 280.0);
        final Offset tipB = Offset(sunCenter.dx + cos(ang + 0.06) * 280.0, sunCenter.dy + sin(ang + 0.06) * 280.0);
        _drawPoly(canvas, [sunCenter, tipA, tipB], const Color(0x14FFF4CC));
      }
      // High-Altitude Wispy Cirrus Cloud Streaks (adds natural photographic sky depth!)
      _strokePaint..color = const Color(0x20FFFFFF)..strokeWidth = 2.0..strokeCap = StrokeCap.round;
      for (int ci = 0; ci < 6; ci++) {
        final double cix = ((ci * 265.0 + engine.horizonPan * 0.07) % (w + 300) + (w + 300)) % (w + 300) - 150;
        final double ciy = horizonY * (0.09 + (ci % 3) * 0.08);
        canvas.drawLine(Offset(cix - 64, ciy), Offset(cix + 64, ciy - 4.0), _strokePaint);
        canvas.drawLine(Offset(cix - 36, ciy + 3.2), Offset(cix + 46, ciy - 1.2), _strokePaint);
      }
      // Sculpted Multi-Puff Volumetric Clouds (ZERO shader allocations — 2-layer soft translucent puffs = 10x cooler GPU!)
      final Color cloudShadowOuter = Color.lerp(circuit.skyBottom, const Color(0xFF475C78), 0.38)!.withAlpha(42);
      final Color cloudShadowCore = Color.lerp(circuit.skyBottom, const Color(0xFF475C78), 0.38)!.withAlpha(64);
      final Color cloudLitOuter = Color.lerp(Colors.white, const Color(0xFFFFF3D6), 0.25)!.withAlpha(54);
      final Color cloudLitCore = Color.lerp(Colors.white, const Color(0xFFFFF3D6), 0.25)!.withAlpha(96);
      for (int c = 0; c < 8; c++) {
        final double cx = ((c * 218.0 + engine.horizonPan * 0.13) % (w + 380) + (w + 380)) % (w + 380) - 190;
        final double cy = horizonY * (0.14 + (c % 3) * 0.165);
        final double cwCloud = 185.0 + (c % 3) * 48.0;
        final double chCloud = 26.0 + (c % 2) * 10.0;
        _fillPaint.color = cloudShadowOuter;
        canvas.drawOval(Rect.fromCenter(center: Offset(cx, cy + chCloud * 0.24), width: cwCloud, height: chCloud * 0.72), _fillPaint);
        _fillPaint.color = cloudShadowCore;
        canvas.drawOval(Rect.fromCenter(center: Offset(cx, cy + chCloud * 0.20), width: cwCloud * 0.68, height: chCloud * 0.46), _fillPaint);
        for (final double off in const [-0.24, 0.0, 0.26]) {
          final double pwC = cwCloud * (off == 0.0 ? 0.62 : 0.44);
          final double phC = chCloud * (off == 0.0 ? 1.08 : 0.78);
          final Offset pc = Offset(cx + cwCloud * off, cy - (off == 0.0 ? 4.0 : 0.0));
          _fillPaint.color = cloudLitOuter;
          canvas.drawOval(Rect.fromCenter(center: pc, width: pwC, height: phC), _fillPaint);
          _fillPaint.color = cloudLitCore;
          canvas.drawOval(Rect.fromCenter(center: pc, width: pwC * 0.62, height: phC * 0.60), _fillPaint);
        }
      }
    }

    // Layer 1: Far Atmospheric Mountain Silhouette with Gradient Depth Shading
    _farRangePath
      ..reset()
      ..moveTo(0, horizonY + 2);
    for (double x = 0; x <= w + 32; x += 22) {
      final double wx = x - engine.horizonPan * 0.15;
      final double pk = 36.0 + sin(wx * 0.0068) * 30.0 + cos(wx * 0.017) * 14.0 + sin(wx * 0.031) * 5.0;
      _farRangePath.lineTo(x, horizonY - pk);
    }
    _farRangePath
      ..lineTo(w, horizonY + 2)
      ..close();
    final Color farTop = Color.lerp(circuit.nightMode ? const Color(0xFF142240) : const Color(0xFF4C688C), circuit.skyBottom, 0.48)!;
    final Color farBot = Color.lerp(circuit.nightMode ? const Color(0xFF0A1124) : const Color(0xFF334966), circuit.skyBottom, 0.70)!;
    _gradPaint.shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      colors: [farTop, farBot],
    ).createShader(Rect.fromLTWH(0, horizonY - 86, w, 90));
    canvas.drawPath(_farRangePath, _gradPaint);

    // Layer 2: Mid-Distance Ridges / Distant City Towers with Gradient Depth Shading
    _midRangePath
      ..reset()
      ..moveTo(0, horizonY + 2);
    for (double x = 0; x <= w + 32; x += 24) {
      final double wx = x - engine.horizonPan * 0.28;
      final double pk = circuit.propStyle == PropStyle.skyline
          ? (28.0 + ((wx ~/ 30).abs() % 7) * 17.0)
          : (22.0 + sin(wx * 0.012 + 1.1) * 20.0 + cos(wx * 0.028) * 9.0);
      _midRangePath.lineTo(x, horizonY - pk);
    }
    _midRangePath
      ..lineTo(w, horizonY + 2)
      ..close();
    final Color midTop = Color.lerp(circuit.nightMode ? const Color(0xFF172546) : const Color(0xFF314B6B), circuit.skyBottom, 0.28)!;
    final Color midBot = Color.lerp(circuit.nightMode ? const Color(0xFF0B1328) : const Color(0xFF1E2F44), circuit.skyBottom, 0.46)!;
    _gradPaint.shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      colors: [midTop, midBot],
    ).createShader(Rect.fromLTWH(0, horizonY - 140, w, 144));
    canvas.drawPath(_midRangePath, _gradPaint);

    // Layer 3: Closer Tree Line / Skyline Foreground Silhouette
    _nearRangePath
      ..reset()
      ..moveTo(0, horizonY + 2);
    for (double x = 0; x <= w + 28; x += 18) {
      final double wx = x - engine.horizonPan * 0.44;
      final double pk = circuit.propStyle == PropStyle.skyline
          ? (15.0 + ((wx ~/ 22).abs() % 5) * 12.0)
          : (11.0 + sin(wx * 0.026) * 8.5 + cos(wx * 0.058) * 5.0);
      _nearRangePath.lineTo(x, horizonY - pk);
    }
    _nearRangePath
      ..lineTo(w, horizonY + 2)
      ..close();
    _fillPaint.color = Color.lerp(circuit.nightMode ? const Color(0xFF0A1120) : const Color(0xFF172838), circuit.skyBottom, 0.14)!;
    canvas.drawPath(_nearRangePath, _fillPaint);

    // Sunlit Golden Alpine Rim-Light along distant mountain peaks on day/sunset circuits
    if (!circuit.nightMode && circuit.propStyle != PropStyle.skyline) {
      _strokePaint
        ..color = Color.lerp(const Color(0x55FFF0C2), circuit.skyBottom, 0.35)!
        ..strokeWidth = 1.6;
      canvas.drawPath(_farRangePath, _strokePaint);
    }

    // Iconic Coastal Shimmering Water Band on Seaside Circuits (Monaco, Miami, Jeddah, Abu Dhabi, Australia, Zandvoort)
    if (circuit.code == 'MON' ||
        circuit.code == 'MIA' ||
        circuit.code == 'SAU' ||
        circuit.code == 'ABU' ||
        circuit.code == 'AUS' ||
        circuit.code == 'NED') {
      final Rect seaBand = Rect.fromLTWH(0, horizonY - 7.5, w, 10.0);
      _gradPaint.shader = LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: circuit.nightMode
            ? const [Color(0xBB0A1F3D), Color(0xCC061326)]
            : const [Color(0xCC1E6FA8), Color(0xBB0E4673)],
      ).createShader(seaBand);
      canvas.drawRect(seaBand, _gradPaint);
      // Shimmering sun/moonlight water glints
      _fillPaint.color = circuit.nightMode ? const Color(0x7790D8FF) : const Color(0xAAFFF4C2);
      for (int gl = 0; gl < 14; gl++) {
        final double gx = sunX + sin(gl * 1.9 + engine.totalRaceTime * 1.4) * (24.0 + gl * 5.0);
        final double gy = horizonY - 5.5 + (gl % 3) * 2.2;
        canvas.drawRect(Rect.fromLTWH(gx - 6.0, gy, 12.0 - (gl % 4) * 1.5, 1.3), _fillPaint);
      }
      // Iconic Luxury Harbor Superyachts moored on Monaco / Miami / Abu Dhabi / Jeddah waterfront!
      if (circuit.code == 'MON' || circuit.code == 'MIA' || circuit.code == 'ABU' || circuit.code == 'SAU') {
        for (int yt = 0; yt < 5; yt++) {
          final double yx = ((yt * 195.0 + 70.0 + engine.horizonPan * 0.32) % (w + 140) + (w + 140)) % (w + 140) - 70;
          final double yy = horizonY - 4.2;
          _fillPaint.color = circuit.nightMode ? const Color(0xCCCDD9E8) : const Color(0xEEFFFFFF);
          canvas.drawRect(Rect.fromLTWH(yx - 14.0, yy - 3.0, 28.0, 3.2), _fillPaint);
          canvas.drawRect(Rect.fromLTWH(yx - 9.0, yy - 6.2, 16.0, 3.2), _fillPaint);
          _fillPaint.color = const Color(0xCC112036);
          canvas.drawRect(Rect.fromLTWH(yx - 7.0, yy - 5.2, 12.0, 1.5), _fillPaint);
          // Yacht mast & warm evening deck lights
          _strokePaint..color = const Color(0xBBDCE8F8)..strokeWidth = 1.0;
          canvas.drawLine(Offset(yx - 1.0, yy - 6.2), Offset(yx - 1.0, yy - 13.5), _strokePaint);
          if (circuit.nightMode || circuit.timeLabel == 'Atardecer') {
            _fillPaint.color = const Color(0xEEFFE082);
            canvas.drawCircle(Offset(yx - 5.0, yy - 1.6), 1.0, _fillPaint);
            canvas.drawCircle(Offset(yx + 4.0, yy - 1.6), 1.0, _fillPaint);
          }
        }
      }
    }

    // Iconic Giant Illuminated Observation Ferris Wheel on Skyline / Night / Suzuka Circuits!
    if (circuit.code == 'SIN' ||
        circuit.code == 'JPN' ||
        circuit.code == 'LVG' ||
        circuit.code == 'ABU' ||
        circuit.code == 'SAU') {
      final double fx = ((w * 0.24 + engine.horizonPan * 0.26) % (w + 180) + (w + 180)) % (w + 180) - 90;
      final double fr = (horizonY * 0.26).clamp(24.0, 48.0).toDouble();
      final Offset fc = Offset(fx, horizonY - fr * 1.06);
      final Color wheelRimCol = circuit.nightMode ? const Color(0xCC00E5FF) : const Color(0x99CFD8E6);
      final Color wheelAccent = circuit.nightMode ? const Color(0xAAFF1744) : const Color(0x88E10600);
      // A-frame steel legs
      _strokePaint..color = const Color(0xAA253247)..strokeWidth = 2.4;
      canvas.drawLine(fc, Offset(fx - fr * 0.48, horizonY + 2), _strokePaint);
      canvas.drawLine(fc, Offset(fx + fr * 0.48, horizonY + 2), _strokePaint);
      // Slowly rotating spokes
      final double rot = engine.totalRaceTime * 0.16;
      _strokePaint..color = wheelRimCol.withAlpha(115)..strokeWidth = 1.0;
      for (int sp = 0; sp < 10; sp++) {
        final double a = rot + (sp * pi / 5.0);
        canvas.drawLine(fc, Offset(fc.dx + cos(a) * fr, fc.dy + sin(a) * fr), _strokePaint);
      }
      _strokePaint..color = wheelRimCol..strokeWidth = 2.2;
      canvas.drawCircle(fc, fr, _strokePaint);
      _strokePaint..color = wheelAccent..strokeWidth = 1.3;
      canvas.drawCircle(fc, fr * 0.72, _strokePaint);
      // Glowing gondola pods around rim
      _fillPaint.color = circuit.nightMode ? const Color(0xEEFFF59D) : const Color(0xBBFFFFFF);
      for (int pod = 0; pod < 12; pod++) {
        final double a = rot + (pod * pi / 6.0);
        canvas.drawCircle(Offset(fc.dx + cos(a) * fr, fc.dy + sin(a) * fr), 1.9, _fillPaint);
      }
    }

    // Distant Cruising Broadcast Airship / Blimp in the upper sky with blinking red beacon!
    final double blimpX = ((w * 0.80 + engine.horizonPan * 0.18 + engine.totalRaceTime * 4.5) % (w + 160) + (w + 160)) % (w + 160) - 80;
    final double blimpY = horizonY * 0.24;
    final Rect blimpHull = Rect.fromCenter(center: Offset(blimpX, blimpY), width: 34.0, height: 11.0);
    _gradPaint.shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      colors: circuit.nightMode
          ? const [Color(0xAA4D6485), Color(0xAA182438)]
          : const [Color(0xDDFFFFFF), Color(0xBB8A9BB2)],
    ).createShader(blimpHull);
    canvas.drawOval(blimpHull, _gradPaint);
    _fillPaint.color = const Color(0xDDE10600);
    canvas.drawRect(Rect.fromCenter(center: Offset(blimpX, blimpY), width: 16.0, height: 2.6), _fillPaint);
    if ((engine.totalRaceTime * 2.5).floor() % 2 == 0) {
      _fillPaint.color = const Color(0xFFFF1744);
      canvas.drawCircle(Offset(blimpX, blimpY + 6.5), 1.6, _fillPaint);
    }

    // Night distant city window glints & red rooftop aviation beacons along skyline
    if (circuit.nightMode && circuit.propStyle == PropStyle.skyline) {
      for (int b = 0; b < 38; b++) {
        final double bx = ((b * 42.0 + engine.horizonPan * 0.28) % (w + 60) + (w + 60)) % (w + 60) - 30;
        final double by = horizonY - 12.0 - (b % 5) * 14.0;
        _fillPaint.color = (b % 3 == 0) ? const Color(0xAA40E5FF) : const Color(0xAAFFE082);
        canvas.drawRect(Rect.fromLTWH(bx, by, 3.2, 2.0), _fillPaint);
        canvas.drawRect(Rect.fromLTWH(bx + 6.0, by + 5.0, 3.2, 2.0), _fillPaint);
        if (b % 6 == 0) {
          _fillPaint.color = const Color(0xEEFF1744);
          canvas.drawCircle(Offset(bx + 3.0, by - 8.0), 1.6, _fillPaint);
        }
      }
    }
  }

  void _drawStartGantry3D(
    Canvas canvas,
    double s1,
    double s2,
    double y1,
    double y2,
    double z1,
    double z2,
    double roadHalfW,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
  ) {
    final Offset sh1L = _project(-roadHalfW + s1, y1 + 0.015, z1, w, horizonY, fovMult);
    final Offset sh1R = _project(roadHalfW + s1, y1 + 0.015, z1, w, horizonY, fovMult);
    final Offset sh2L = _project(-roadHalfW + s2, y2 + 0.015, z2, w, horizonY, fovMult);
    final Offset sh2R = _project(roadHalfW + s2, y2 + 0.015, z2, w, horizonY, fovMult);
    _drawQuad(canvas, sh1L, sh1R, sh2R, sh2L, Color.fromARGB((115 * (1.0 - fogMix)).toInt(), 0, 0, 0));

    final Offset bL = _project(-roadHalfW - 1.05 + s1, y1, z1, w, horizonY, fovMult);
    final Offset bR = _project(roadHalfW + 1.05 + s1, y1, z1, w, horizonY, fovMult);
    final Offset tL = _project(-roadHalfW - 1.05 + s1, y1 + 4.15, z1, w, horizonY, fovMult);
    final Offset tR = _project(roadHalfW + 1.05 + s1, y1 + 4.15, z1, w, horizonY, fovMult);
    final Offset tLBack = _project(-roadHalfW - 1.05 + s2, y2 + 4.15, z2, w, horizonY, fovMult);
    final Offset tRBack = _project(roadHalfW + 1.05 + s2, y2 + 4.15, z2, w, horizonY, fovMult);
    final double beamH = max(7.0, 74.0 / z1);

    _strokePaint
      ..color = Color.lerp(const Color(0xFF232C3B), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(3.5, 34.0 / z1);
    canvas.drawLine(bL, tL, _strokePaint);
    canvas.drawLine(bR, tR, _strokePaint);

    _drawQuad(
      canvas,
      Offset(tL.dx, tL.dy + beamH * 0.5),
      Offset(tR.dx, tR.dy + beamH * 0.5),
      Offset(tRBack.dx, tRBack.dy + beamH * 0.42),
      Offset(tLBack.dx, tLBack.dy + beamH * 0.42),
      Color.lerp(const Color(0xFF0A0D14), circuit.skyBottom, fogMix)!,
    );

    final Rect bridge = Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.5, tR.dx, tR.dy + beamH * 0.5);
    _fillPaint.color = Color.lerp(const Color(0xFF101520), circuit.skyBottom, fogMix)!;
    canvas.drawRect(bridge, _fillPaint);
    _fillPaint.color = Color.lerp(const Color(0xFFE10600), circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.5, tR.dx, tL.dy - beamH * 0.22), _fillPaint);

    if (beamH > 12.0) {
      final double podW = max(4.0, (bridge.width * 0.045));
      final double podH = beamH * 0.68;
      final double totalCountdown = engine.phase == SessionPhase.qualifying ? 2.2 : 3.2;
      for (int idx = 0; idx < 5; idx++) {
        final double px = bridge.center.dx + (idx - 2) * (podW * 1.85);
        final Rect pod = Rect.fromCenter(center: Offset(px, bridge.bottom + podH * 0.42), width: podW, height: podH);
        _fillPaint.color = const Color(0xFF0B0E14);
        canvas.drawRRect(RRect.fromRectAndRadius(pod, const Radius.circular(2)), _fillPaint);
        final bool lit = engine.startLightsTimer > 0 &&
            engine.startLightsTimer < (totalCountdown - 0.15 - idx * (totalCountdown * 0.15));
        final Offset lampC = Offset(px, pod.bottom - podW * 0.45);
        if (lit) {
          final double lr = podW * 1.15;
          _gradPaint.shader = const RadialGradient(
            colors: [Color(0xEEFF526A), Color(0x88FF1744), Color(0x00FF1744)],
          ).createShader(Rect.fromCircle(center: lampC, radius: lr));
          canvas.drawCircle(lampC, lr, _gradPaint);
        }
        _fillPaint.color = lit ? const Color(0xFFFF3D57) : const Color(0xFF2E1216);
        canvas.drawCircle(lampC, podW * 0.34, _fillPaint);
        if (lit) {
          _fillPaint.color = const Color(0xEEFFD6DC);
          canvas.drawCircle(lampC, podW * 0.15, _fillPaint);
        }
      }
    }
  }

  void _drawTracksideProp3D(
    Canvas canvas,
    double x,
    double y1,
    double z,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
    bool isLeft,
    int seed,
  ) {
    final Offset base = _project(x, y1, z, w, horizonY, fovMult);
    final double heightScale = 4.6 + ((seed.abs() % 3) * 0.85);
    final Offset top = _project(x, y1 + heightScale, z, w, horizonY, fovMult);
    final double ph = max(8.0, base.dy - top.dy);
    final double pw = max(6.0, ph * 0.54);

    if (pw > 9.0) {
      _fillPaint.color = Color.fromARGB((82 * (1.0 - fogMix)).toInt(), 0, 0, 0);
      canvas.drawOval(Rect.fromCenter(center: base, width: pw * 1.65, height: max(2.5, pw * 0.30)), _fillPaint);
    }

    // Night circuits: tall Stadium Floodlight Towers with volumetric downward light cones!
    if (circuit.nightMode && (seed.abs() % 2 == 0)) {
      final double armDir = isLeft ? 1.0 : -1.0;
      final Offset towerTop = _project(x, y1 + 7.2, z, w, horizonY, fovMult);
      final Offset head = Offset(towerTop.dx + armDir * pw * 0.58, towerTop.dy - ph * 0.08);

      // Volumetric light cone onto the track
      if (pw > 10.0) {
        final Offset coneL = _project(x + armDir * 3.8, y1, z, w, horizonY, fovMult);
        final Offset coneR = _project(x + armDir * 0.6, y1, z, w, horizonY, fovMult);
        _drawQuad(
          canvas,
          Offset(head.dx - pw * 0.14, head.dy),
          Offset(head.dx + pw * 0.14, head.dy),
          coneR,
          coneL,
          Color.fromARGB((26 * (1.0 - fogMix)).toInt(), 210, 238, 255),
        );
      }

      _strokePaint
        ..color = Color.lerp(const Color(0xFF7D90A6), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.0, pw * 0.14);
      canvas.drawLine(base, towerTop, _strokePaint);
      canvas.drawLine(towerTop, head, _strokePaint);
      _fillPaint.color = Color.lerp(const Color(0xFFE0ECFA), circuit.skyBottom, fogMix)!;
      canvas.drawRect(Rect.fromCenter(center: head, width: max(5.0, pw * 0.52), height: max(3.0, pw * 0.22)), _fillPaint);

      final double glowR = max(10.0, pw * 1.15);
      _fillPaint.color = const Color(0x3CD6F0FF);
      canvas.drawCircle(head, glowR, _fillPaint);
      _fillPaint.color = const Color(0x78E8F6FF);
      canvas.drawCircle(head, glowR * 0.52, _fillPaint);
      _fillPaint.color = const Color(0xF5FFFFFF);
      canvas.drawCircle(head, glowR * 0.22, _fillPaint);
      return;
    }

    // Occasional World-Anchored 3D FIA Trackside TV Broadcast Crane Camera & Animated Waving Marshal Flag Post!
    if ((seed.abs() % 7 == 3) && pw > 10.0) {
      final double armDir = isLeft ? 1.0 : -1.0;
      final Offset craneTop = _project(x, y1 + 5.8, z, w, horizonY, fovMult);
      final Offset camHead = Offset(craneTop.dx + armDir * pw * 0.95, craneTop.dy - ph * 0.05);
      _strokePaint
        ..color = Color.lerp(const Color(0xFF2B3548), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.0, pw * 0.14);
      canvas.drawLine(base, craneTop, _strokePaint);
      _strokePaint
        ..color = Color.lerp(const Color(0xFF536682), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.6, pw * 0.10);
      canvas.drawLine(craneTop, camHead, _strokePaint);
      // Broadcast TV camera box + glowing red "ON AIR" tally LED
      _fillPaint.color = Color.lerp(const Color(0xFF141922), circuit.skyBottom, fogMix)!;
      canvas.drawRRect(
        RRect.fromRectAndRadius(Rect.fromCenter(center: camHead, width: max(5.0, pw * 0.42), height: max(3.5, pw * 0.26)), const Radius.circular(2)),
        _fillPaint,
      );
      _fillPaint.color = const Color(0xFFFF1744);
      canvas.drawCircle(Offset(camHead.dx + armDir * pw * 0.14, camHead.dy - pw * 0.06), max(1.3, pw * 0.06), _fillPaint);
      return;
    } else if ((seed.abs() % 9 == 4) && pw > 12.0) {
      // Towering 3D Trackside Giant F1 Broadcast Jumbotron Video Screen!
      final Offset poleTop = _project(x, y1 + 3.6, z, w, horizonY, fovMult);
      final double scrW = max(14.0, pw * 2.15);
      final double scrH = scrW * 0.56;
      final Rect scrFrame = Rect.fromCenter(center: Offset(poleTop.dx, poleTop.dy - scrH * 0.42), width: scrW, height: scrH);
      _strokePaint..color = Color.lerp(const Color(0xFF1F2838), circuit.skyBottom, fogMix)!..strokeWidth = max(2.4, pw * 0.16);
      canvas.drawLine(base, poleTop, _strokePaint);
      // Dark carbon screen housing
      _fillPaint.color = Color.lerp(const Color(0xFF0A0D14), circuit.skyBottom, fogMix * 0.6)!;
      canvas.drawRRect(RRect.fromRectAndRadius(scrFrame.inflate(2.2), const Radius.circular(3)), _fillPaint);
      // Illuminated live TV screen surface (sky + tarmac + live race graphic bar!)
      _gradPaint.shader = LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        stops: const [0.0, 0.52, 0.54, 1.0],
        colors: [
          Color.lerp(circuit.skyTop, Colors.white, 0.12)!,
          circuit.skyBottom,
          const Color(0xFF2B3240),
          const Color(0xFF161B24),
        ],
      ).createShader(scrFrame);
      canvas.drawRect(scrFrame, _gradPaint);
      // Red F1 broadcast telemetry lower-third ticker bar + live green status dot
      _fillPaint.color = Color.lerp(const Color(0xFFE10600), circuit.skyBottom, fogMix * 0.5)!;
      canvas.drawRect(Rect.fromLTWH(scrFrame.left, scrFrame.bottom - scrH * 0.22, scrW, scrH * 0.22), _fillPaint);
      _fillPaint.color = const Color(0xEEFFFFFF);
      canvas.drawRect(Rect.fromLTWH(scrFrame.left + scrW * 0.08, scrFrame.bottom - scrH * 0.14, scrW * 0.48, max(1.2, scrH * 0.06)), _fillPaint);
      _fillPaint.color = const Color(0xFF00E676);
      canvas.drawCircle(Offset(scrFrame.right - scrW * 0.10, scrFrame.top + scrH * 0.16), max(1.4, scrH * 0.07), _fillPaint);
      return;
    } else if ((seed.abs() % 7 == 5) && pw > 11.0) {
      // Animated Trackside FIA Marshal Booth with Waving Green Flag!
      final Offset postTop = _project(x, y1 + 3.2, z, w, horizonY, fovMult);
      final double wave = sin(engine.totalRaceTime * 7.5 + seed) * pw * 0.16;
      _strokePaint
        ..color = Color.lerp(const Color(0xFFD0DCEB), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.5, pw * 0.09);
      canvas.drawLine(base, postTop, _strokePaint);
      final double fDir = isLeft ? 1.0 : -1.0;
      _drawQuad(
        canvas,
        postTop,
        Offset(postTop.dx + fDir * pw * 0.62, postTop.dy + wave),
        Offset(postTop.dx + fDir * pw * 0.58, postTop.dy + pw * 0.38 + wave),
        Offset(postTop.dx, postTop.dy + pw * 0.36),
        Color.lerp(const Color(0xFF00E676), circuit.skyBottom, fogMix * 0.5)!,
      );
      return;
    }

    if (circuit.propStyle == PropStyle.palms) {
      final double bend = isLeft ? -pw * 0.24 : pw * 0.24;
      _scratchPath
        ..reset()
        ..moveTo(base.dx, base.dy)
        ..quadraticBezierTo(base.dx + bend * 0.5, (base.dy + top.dy) * 0.5, top.dx + bend, top.dy);
      _strokePaint
        ..color = Color.lerp(const Color(0xFF6B483A), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.4, pw * 0.19)
        ..strokeCap = StrokeCap.round;
      canvas.drawPath(_scratchPath, _strokePaint);

      final Offset crown = Offset(top.dx + bend, top.dy);
      // Darker lower fronds + sunlit upper fronds (reusing _scratchPath -> zero Path allocations!)
      final Color frondDark = Color.lerp(circuit.nightMode ? const Color(0xFF143D24) : const Color(0xFF1B5E27), circuit.skyBottom, fogMix)!;
      final Color frondLight = Color.lerp(circuit.nightMode ? const Color(0xFF246940) : const Color(0xFF45A049), circuit.skyBottom, fogMix)!;
      for (int a = 0; a < 9; a++) {
        final double ang = -pi + (a * pi / 8);
        final Offset tip = Offset(crown.dx + cos(ang) * pw * 1.18, crown.dy + sin(ang) * pw * 0.45 + pw * 0.20);
        _strokePaint
          ..color = (a % 2 == 0) ? frondLight : frondDark
          ..strokeWidth = max(2.2, pw * 0.14);
        _scratchPath
          ..reset()
          ..moveTo(crown.dx, crown.dy)
          ..quadraticBezierTo((crown.dx + tip.dx) * 0.5, crown.dy - pw * 0.26, tip.dx, tip.dy);
        canvas.drawPath(_scratchPath, _strokePaint);
      }
    } else if (circuit.propStyle == PropStyle.skyline) {
      final double bTop = top.dy - ph * 0.65;
      final double bH = base.dy - bTop;
      final double frontW = pw * 1.28;
      final double sideW = pw * 0.55;
      final double leftEdge = top.dx - frontW * 0.5;
      final Rect frontRect = Rect.fromLTWH(leftEdge, bTop, frontW, bH);
      final Color frontCol = Color.lerp(circuit.nightMode ? const Color(0xFF1A2540) : const Color(0xFF44536E), circuit.skyBottom, fogMix)!;
      final Color sideCol = Color.lerp(circuit.nightMode ? const Color(0xFF0E1526) : const Color(0xFF253145), circuit.skyBottom, fogMix)!;

      _fillPaint.color = frontCol;
      canvas.drawRect(frontRect, _fillPaint);
      final double sx = isLeft ? frontRect.right : frontRect.left;
      final double sxOut = isLeft ? (frontRect.right + sideW) : (frontRect.left - sideW);
      _drawQuad(
        canvas,
        Offset(sx, bTop),
        Offset(sxOut, bTop + ph * 0.10),
        Offset(sxOut, base.dy - ph * 0.04),
        Offset(sx, base.dy),
        sideCol,
      );

      // Glass curtain-wall gradient reflection + individual window panes + rooftop spire beacon!
      _gradPaint.shader = LinearGradient(
        begin: Alignment.topLeft,
        end: Alignment.bottomRight,
        colors: [
          Color.lerp(frontCol, Colors.white, 0.22)!,
          frontCol,
          Color.lerp(frontCol, Colors.black, 0.25)!,
        ],
      ).createShader(frontRect);
      canvas.drawRect(frontRect, _gradPaint);
      if (pw > 12) {
        for (int r = 0; r < 6; r++) {
          final Color winCol = circuit.nightMode
              ? ((r + seed) % 3 == 0 ? const Color(0xCC40E5FF) : const Color(0xCCFFE082))
              : const Color(0x90DCEEFF);
          _fillPaint.color = Color.lerp(winCol, circuit.skyBottom, fogMix * 0.7)!;
          final double wy = bTop + bH * (0.08 + r * 0.145);
          canvas.drawRect(Rect.fromLTWH(frontRect.left + frontW * 0.12, wy, frontW * 0.34, bH * 0.065), _fillPaint);
          canvas.drawRect(Rect.fromLTWH(frontRect.left + frontW * 0.54, wy, frontW * 0.34, bH * 0.065), _fillPaint);
        }
        // Rooftop antenna + red aviation warning beacon
        _strokePaint
          ..color = Color.lerp(const Color(0xFF8C9BB0), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, pw * 0.05);
        canvas.drawLine(Offset(frontRect.center.dx, bTop), Offset(frontRect.center.dx, bTop - ph * 0.18), _strokePaint);
        if (circuit.nightMode) {
          _fillPaint.color = const Color(0xEEFF1744);
          canvas.drawCircle(Offset(frontRect.center.dx, bTop - ph * 0.19), max(1.4, pw * 0.06), _fillPaint);
        }
      }
    } else if (circuit.propStyle == PropStyle.trees) {
      // Shaded bark trunk + 4-layer volumetric sunlit foliage canopy!
      _strokePaint
        ..color = Color.lerp(const Color(0xFF4A3128), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.4, pw * 0.22)
        ..strokeCap = StrokeCap.round;
      canvas.drawLine(base, Offset(top.dx, base.dy - ph * 0.44), _strokePaint);
      _fillPaint.color = Color.lerp(const Color(0xFF0C2B12), circuit.skyBottom, fogMix)!;
      canvas.drawCircle(Offset(top.dx + pw * 0.16, base.dy - ph * 0.54), pw * 0.64, _fillPaint);
      _fillPaint.color = Color.lerp(const Color(0xFF194F21), circuit.skyBottom, fogMix)!;
      canvas.drawCircle(Offset(top.dx - pw * 0.14, base.dy - ph * 0.62), pw * 0.58, _fillPaint);
      _fillPaint.color = Color.lerp(const Color(0xFF287330), circuit.skyBottom, fogMix)!;
      canvas.drawCircle(Offset(top.dx + pw * 0.02, base.dy - ph * 0.74), pw * 0.54, _fillPaint);
      _fillPaint.color = Color.lerp(const Color(0xFF5EB354), circuit.skyBottom, fogMix)!;
      canvas.drawCircle(Offset(top.dx - pw * 0.16, base.dy - ph * 0.84), pw * 0.34, _fillPaint);
    } else {
      final double armDir = isLeft ? 1.0 : -1.0;
      final Offset head = Offset(top.dx + armDir * pw * 0.44, top.dy - ph * 0.16);
      _strokePaint
        ..color = Color.lerp(const Color(0xFF90A4AE), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.0, pw * 0.13);
      canvas.drawLine(base, top, _strokePaint);
      canvas.drawLine(top, head, _strokePaint);
      _fillPaint.color = Color.lerp(const Color(0xFFCFD8DC), circuit.skyBottom, fogMix)!;
      canvas.drawRect(Rect.fromCenter(center: head, width: max(4.0, pw * 0.38), height: max(2.5, pw * 0.17)), _fillPaint);
    }
  }

  void _drawPoly(Canvas canvas, List<Offset> pts, Color color) {
    if (pts.length < 3) return;
    _polyPath.reset();
    _polyPath.moveTo(pts[0].dx, pts[0].dy);
    for (int i = 1; i < pts.length; i++) {
      _polyPath.lineTo(pts[i].dx, pts[i].dy);
    }
    _polyPath.close();
    _fillPaint.color = color;
    canvas.drawPath(_polyPath, _fillPaint);
  }

  void _drawGradQuad(Canvas canvas, Offset a, Offset b, Offset c, Offset d, Shader shader) {
    _quadPath
      ..reset()
      ..moveTo(a.dx, a.dy)
      ..lineTo(b.dx, b.dy)
      ..lineTo(c.dx, c.dy)
      ..lineTo(d.dx, d.dy)
      ..close();
    _gradPaint.shader = shader;
    canvas.drawPath(_quadPath, _gradPaint);
  }

  /// True 3D Cylindrical Pirelli Slick Tire with:
  /// - 100% Grounded Contact Patch + Flat Bottom Rubber at ly = 0.0 (ZERO floating!)
  /// - True 3D Front-Wheel Steering Rotation around vertical kingpin axis (`wheelSteerYaw`)
  /// - Real Physical Wheel Rolling (`wheelRollAngle = dist / radius`) with spinning Pirelli red sidewall arcs, 6 rotating aero rim spokes & moving tread bands!
  /// - Glowing Carbon Brake Discs when braking
  void _draw3DTire(
    Canvas canvas,
    Offset Function(double lx, double ly, double lz) pGround,
    double sideDir,
    double zCenter,
    double halfW,
    double radius,
    bool isRear,
    bool isNearSide,
    bool isBraking,
    double wheelSteerYaw,
    double wheelRollAngle,
    double cw,
    double fogMix,
    double envShade,
    Color skyBottom,
  ) {
    final double xCenter = sideDir * (isRear ? 0.75 : 0.73);
    final double cosW = cos(wheelSteerYaw);
    final double sinW = sin(wheelSteerYaw);

    // Local wheel-frame -> car-frame projector (rotates front tires cleanly around their steering kingpin!)
    Offset pw(double wx, double wy, double wz) {
      final double lx = xCenter + wx * cosW + wz * sinW;
      final double lz = zCenter + wz * cosW - wx * sinW;
      return pGround(lx, wy, lz);
    }

    final double xIn = -sideDir * halfW;
    final double xOut = sideDir * halfW;
    final double xL = min(xIn, xOut);
    final double xR = max(xIn, xOut);

    // 1. Pitch-Black Grounded Tire Contact Patch Shadow directly under rubber at ly = 0.002!
    _drawQuad(
      canvas,
      pw(xL - 0.06, 0.002, -radius * 1.12),
      pw(xR + 0.06, 0.002, -radius * 1.12),
      pw(xR + 0.06, 0.002, radius * 1.12),
      pw(xL - 0.06, 0.002, radius * 1.12),
      Color.fromARGB((225 * (1.0 - fogMix)).toInt(), 0, 0, 0),
    );
    // Soft outer tire shadow skirt
    _drawQuad(
      canvas,
      pw(xL - 0.13, 0.001, -radius * 1.24),
      pw(xR + 0.13, 0.001, -radius * 1.24),
      pw(xR + 0.13, 0.001, radius * 1.24),
      pw(xL - 0.13, 0.001, radius * 1.24),
      Color.fromARGB((95 * (1.0 - fogMix)).toInt(), 0, 0, 0),
    );

    // 2. Inner Carbon Brake Duct, Glowing Brake Disc & Warm Orange Asphalt Underglow (when braking!)
    if (isBraking && cw > 24.0) {
      final Offset discC = pw(xIn - sideDir * 0.035, radius * 0.96, 0.0);
      final double dr = max(3.2, cw * (isRear ? 0.10 : 0.086));
      _gradPaint.shader = const RadialGradient(
        colors: [Color(0xFFFFF59D), Color(0xF5FF6D00), Color(0x00FF3D00)],
      ).createShader(Rect.fromCircle(center: discC, radius: dr));
      canvas.drawCircle(discC, dr, _gradPaint);
      // Warm glowing brake reflection cast onto the asphalt right below the hub!
      final Offset groundGlow = pw(xIn, 0.008, 0.0);
      _gradPaint.shader = const RadialGradient(
        colors: [Color(0x66FF5722), Color(0x00FF3D00)],
      ).createShader(Rect.fromCircle(center: groundGlow, radius: dr * 1.35));
      canvas.drawOval(Rect.fromCenter(center: groundGlow, width: dr * 2.4, height: dr * 0.72), _gradPaint);
    }

    // 3. Exposed Inner Sidewall / Rim Barrel when viewing far-side wheel OR steered front wheel from inside!
    final bool innerVisible = !isNearSide || (wheelSteerYaw * sideDir > 0.08);
    if (innerVisible && cw > 18.0) {
      final List<Offset> innerWall = [];
      const int nIn = 8;
      for (int k = 0; k < nIn; k++) {
        final double a = (k / nIn) * pi * 2.0;
        innerWall.add(pw(xIn, radius * (1.0 + sin(a) * 0.96), radius * cos(a) * 0.96));
      }
      _drawPoly(canvas, innerWall, Color.lerp(const Color(0xFF0A0D13), skyBottom, fogMix * 0.6)!);
    }

    // 4. Sculpted 3D Cylindrical Tire Tread (6 curved bands including flat ground contact strip at ly = 0.0!)
    final Color rubberBaseDark = Color.lerp(const Color(0xFF090C12), Colors.black, envShade * 0.4)!;
    final Color rubberBaseMid = Color.lerp(const Color(0xFF232A36), Colors.black, envShade * 0.45)!;
    final Color rubberBaseHi = Color.lerp(const Color(0xFF4C596E), Colors.black, envShade * 0.45)!;
    final Color rubberBaseTop = Color.lerp(const Color(0xFF343E50), Colors.black, envShade * 0.45)!;

    final Color rubberDark = Color.lerp(rubberBaseDark, skyBottom, fogMix * 0.62)!;
    final Color rubberMid = Color.lerp(rubberBaseMid, skyBottom, fogMix * 0.62)!;
    final Color rubberHi = Color.lerp(rubberBaseHi, skyBottom, fogMix * 0.62)!;
    final Color rubberTop = Color.lerp(rubberBaseTop, skyBottom, fogMix * 0.62)!;

    // Bottom contact pad sitting strictly at ly = 0.0 so the rubber physically rests on the asphalt!
    final Offset cFL = pw(xL, 0.0, radius * 0.36);
    final Offset cFR = pw(xR, 0.0, radius * 0.36);
    final Offset cRL = pw(xL, 0.0, -radius * 0.46);
    final Offset cRR = pw(xR, 0.0, -radius * 0.46);
    final Offset lL = pw(xL, radius * 0.36, -radius * 0.92);
    final Offset lR = pw(xR, radius * 0.36, -radius * 0.92);
    final Offset mL = pw(xL, radius * 1.05, -radius * 1.02);
    final Offset mR = pw(xR, radius * 1.05, -radius * 1.02);
    final Offset uL = pw(xL, radius * 1.72, -radius * 0.78);
    final Offset uR = pw(xR, radius * 1.72, -radius * 0.78);
    final Offset tL = pw(xL, radius * 2.00, -radius * 0.06);
    final Offset tR = pw(xR, radius * 2.00, -radius * 0.06);
    final Offset fL = pw(xL, radius * 1.80, radius * 0.68);
    final Offset fR = pw(xR, radius * 1.80, radius * 0.68);

    _drawQuad(canvas, cRL, cRR, cFR, cFL, const Color(0xFF05070A));
    _drawQuad(canvas, tL, tR, fR, fL, rubberTop);
    _drawQuad(canvas, uL, uR, tR, tL, rubberHi);
    _drawQuad(canvas, mL, mR, uR, uL, rubberMid);
    _drawQuad(canvas, lL, lR, mR, mL, Color.lerp(rubberMid, rubberDark, 0.52)!);
    _drawQuad(canvas, cRL, cRR, lR, lL, rubberDark);

    // 5. HIGH-VISIBILITY ROLLING TREAD BANDS & ROTATING RUBBER SHEEN (moves smoothly at exact wheel angular speed!)
    if (cw > 24.0) {
      final double treadFrac = _posMod(wheelRollAngle / (pi * 2.0), 1.0);
      final Color treadDarkCol = Color.fromARGB((96 * (1.0 - fogMix)).toInt(), 0, 0, 0);
      final Color treadSheenCol = Color.fromARGB((74 * (1.0 - fogMix)).toInt(), 200, 215, 238);
      for (int b = 0; b < 4; b++) {
        final double ph = (treadFrac + b * 0.25) % 1.0;
        final double ang = -0.42 + ph * 2.42;
        final double ty = radius * (1.0 + sin(ang));
        final double tz = -radius * cos(ang);
        _strokePaint
          ..color = (b % 2 == 0) ? treadDarkCol : treadSheenCol
          ..strokeWidth = max(1.1, cw * (b % 2 == 0 ? 0.022 : 0.015));
        canvas.drawLine(pw(xL + 0.02, ty, tz), pw(xR - 0.02, ty, tz), _strokePaint);
      }

      _strokePaint
        ..color = Color.fromARGB((82 * (1.0 - fogMix)).toInt(), 218, 230, 248)
        ..strokeWidth = max(1.0, cw * 0.014);
      canvas.drawLine(pw(xL + 0.04, radius * 1.95, -radius * 0.22), pw(xR - 0.04, radius * 1.95, -radius * 0.22), _strokePaint);
    }

    // 6. TRUE 3D OUTER SIDEWALL + SPINNING PIRELLI RED ARCS + ROTATING 6-SPOKE AERO WHEEL COVER!
    final bool outerVisible = isNearSide || (wheelSteerYaw * sideDir < -0.06);
    if (outerVisible && cw > 16.0) {
      final List<Offset> outerWall = [];
      final List<Offset> rimCover = [];
      const int nSeg = 12;
      for (int k = 0; k < nSeg; k++) {
        final double a = (k / nSeg) * pi * 2.0;
        final double ca = cos(a);
        final double sa = sin(a);
        outerWall.add(pw(xOut, radius * (1.0 + sa * 0.98), radius * ca * 0.98));
        if (cw > 24.0) {
          rimCover.add(pw(xOut + sideDir * 0.008, radius * (1.0 + sa * 0.58), radius * ca * 0.58));
        }
      }
      _drawPoly(canvas, outerWall, Color.lerp(const Color(0xFF131720), skyBottom, fogMix * 0.6)!);

      if (cw > 24.0) {
        // TWO OPPOSING SPINNING PIRELLI SOFT RED SIDEWALL ARCS (unmistakable rolling wheel motion!)
        _strokePaint
          ..color = Color.lerp(const Color(0xFFE50914), skyBottom, fogMix * 0.45)!
          ..strokeWidth = max(1.3, cw * 0.018)
          ..strokeCap = StrokeCap.round;
        for (int arcIdx = 0; arcIdx < 2; arcIdx++) {
          final double baseA = wheelRollAngle + arcIdx * pi;
          const int arcSteps = 4;
          Offset? prevPt;
          for (int st = 0; st <= arcSteps; st++) {
            final double a = baseA + (st / arcSteps) * 1.38;
            final Offset pt = pw(xOut + sideDir * 0.004, radius * (1.0 + sin(a) * 0.80), radius * cos(a) * 0.80);
            if (prevPt != null) {
              canvas.drawLine(prevPt, pt, _strokePaint);
            }
            prevPt = pt;
          }
        }

        // White Pirelli logo tick opposing the red arcs (rotates with tire!)
        _strokePaint
          ..color = Color.lerp(const Color(0xDDF2F5FA), skyBottom, fogMix * 0.45)!
          ..strokeWidth = max(1.0, cw * 0.012);
        for (int wIdx = 0; wIdx < 2; wIdx++) {
          final double a0 = wheelRollAngle + 1.92 + wIdx * pi;
          final double a1 = a0 + 0.55;
          canvas.drawLine(
            pw(xOut + sideDir * 0.005, radius * (1.0 + sin(a0) * 0.80), radius * cos(a0) * 0.80),
            pw(xOut + sideDir * 0.005, radius * (1.0 + sin(a1) * 0.80), radius * cos(a1) * 0.80),
            _strokePaint,
          );
        }

        // Aero Carbon Wheel Cover + 6 SPINNING METALLIC WHEEL SPOKES / LUG SLOTS!
        _drawPoly(canvas, rimCover, Color.lerp(const Color(0xFF1F2734), skyBottom, fogMix * 0.6)!);
        final Offset hubC = pw(xOut + sideDir * 0.012, radius, 0.0);
        if (cw > 34.0) {
          _strokePaint
            ..color = Color.lerp(const Color(0xAA6A7A94), skyBottom, fogMix * 0.5)!
            ..strokeWidth = max(1.0, cw * 0.011);
          for (int sp = 0; sp < 6; sp++) {
            final double sa = wheelRollAngle + (sp * pi / 3.0);
            final Offset spTip = pw(xOut + sideDir * 0.010, radius * (1.0 + sin(sa) * 0.52), radius * cos(sa) * 0.52);
            canvas.drawLine(hubC, spTip, _strokePaint);
          }
        }
        _fillPaint.color = Color.lerp(const Color(0xFFB8C7DC), skyBottom, fogMix * 0.5)!;
        canvas.drawCircle(hubC, max(1.3, cw * 0.020), _fillPaint);
      }
    } else if (cw > 26.0) {
      final double edgePulse = 0.55 + 0.45 * sin(wheelRollAngle * 2.0);
      _strokePaint
        ..color = Color.lerp(const Color(0xFFE10600), skyBottom, fogMix * 0.5)!.withAlpha((edgePulse * 235).toInt())
        ..strokeWidth = max(1.2, cw * 0.016);
      canvas.drawLine(
        pw(xOut, radius * 0.34, -radius * 0.84),
        pw(xOut, radius * 1.62, -radius * 0.78),
        _strokePaint,
      );
    }
  }

  /// True 3D Sculpted Sidepod Assembly (Undercut Flank, Upper Shoulder, Livery Stripe, Cooling Louvers & Radiator Intake)
  void _draw3DSidepod(
    Canvas canvas,
    Offset Function(double lx, double ly, double lz) p3,
    double sideDir,
    bool isLitSide,
    double cw,
    double fogMix,
    Color bodyCol,
    Color hiCol,
    Color darkCol,
    Color wingCol,
    Color skyBottom,
  ) {
    final Color sideFaceCol = isLitSide
        ? Color.lerp(bodyCol, hiCol, 0.24)!
        : Color.lerp(bodyCol, Colors.black, 0.28)!;
    final Color undercutCol = Color.lerp(bodyCol, Colors.black, isLitSide ? 0.44 : 0.62)!;
    final Color topShoulderCol = isLitSide
        ? Color.lerp(hiCol, Colors.white, 0.14)!
        : Color.lerp(bodyCol, hiCol, 0.35)!;

    final Offset fBot = p3(sideDir * 0.52, 0.14, 1.64);
    final Offset fMid = p3(sideDir * 0.64, 0.34, 1.64);
    final Offset fTop = p3(sideDir * 0.58, 0.52, 1.64);
    final Offset fInT = p3(sideDir * 0.28, 0.55, 1.64);

    final Offset mBot = p3(sideDir * 0.50, 0.12, 0.92);
    final Offset mMid = p3(sideDir * 0.66, 0.36, 0.92);
    final Offset mTop = p3(sideDir * 0.56, 0.54, 0.92);
    final Offset mInT = p3(sideDir * 0.24, 0.60, 0.92);

    final Offset rBot = p3(sideDir * 0.30, 0.15, 0.08);
    final Offset rMid = p3(sideDir * 0.42, 0.35, 0.08);
    final Offset rTop = p3(sideDir * 0.32, 0.48, 0.08);
    final Offset rInT = p3(sideDir * 0.14, 0.54, 0.08);

    _drawQuad(canvas, fBot, fMid, mMid, mBot, undercutCol);
    _drawQuad(canvas, mBot, mMid, rMid, rBot, Color.lerp(undercutCol, Colors.black, 0.18)!);
    _drawQuad(canvas, fMid, fTop, mTop, mMid, sideFaceCol);
    _drawQuad(canvas, mMid, mTop, rTop, rMid, Color.lerp(sideFaceCol, darkCol, 0.22)!);
    // PBR Metallic Clearcoat Sky-Reflection Gradient on Sidepod Upper Shoulder!
    _drawGradQuad(
      canvas,
      fTop,
      fInT,
      mInT,
      mTop,
      LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: [
          Color.lerp(topShoulderCol, Colors.white, isLitSide ? 0.34 : 0.12)!,
          topShoulderCol,
          bodyCol,
        ],
      ).createShader(Rect.fromPoints(fInT, mTop)),
    );
    _drawQuad(canvas, mTop, mInT, rInT, rTop, Color.lerp(topShoulderCol, bodyCol, 0.32)!);

    _drawQuad(
      canvas,
      p3(sideDir * 0.18, 0.22, 0.07),
      p3(sideDir * 0.36, 0.22, 0.07),
      p3(sideDir * 0.32, 0.45, 0.07),
      p3(sideDir * 0.16, 0.45, 0.07),
      Color.lerp(const Color(0xFF0A0D13), skyBottom, fogMix * 0.6)!,
    );

    if (cw > 34.0) {
      _strokePaint
        ..color = wingCol.withAlpha((235 * (1.0 - fogMix * 0.4)).toInt())
        ..strokeWidth = max(1.2, cw * 0.018);
      canvas.drawLine(fMid, mMid, _strokePaint);
      canvas.drawLine(mMid, rMid, _strokePaint);

      _strokePaint
        ..color = Color.fromARGB((140 * (1.0 - fogMix)).toInt(), 255, 255, 255)
        ..strokeWidth = max(1.0, cw * 0.012);
      canvas.drawLine(fTop, mTop, _strokePaint);
      canvas.drawLine(mTop, rTop, _strokePaint);

      _strokePaint
        ..color = Color.fromARGB((150 * (1.0 - fogMix)).toInt(), 10, 14, 20)
        ..strokeWidth = max(0.9, cw * 0.010);
      for (int g = 0; g < 4; g++) {
        final double gz = 0.48 + g * 0.24;
        canvas.drawLine(
          p3(sideDir * 0.34, 0.54, gz),
          p3(sideDir * 0.50, 0.51, gz - 0.04),
          _strokePaint,
        );
      }

      _drawQuad(
        canvas,
        p3(sideDir * 0.34, 0.34, 1.65),
        p3(sideDir * 0.58, 0.34, 1.65),
        p3(sideDir * 0.56, 0.48, 1.65),
        p3(sideDir * 0.34, 0.48, 1.65),
        const Color(0xFF07090E),
      );
    }
  }

  /// True 3D Rear Wing Endplate with Inner/Outer Side Faces, Team Livery & Vertical FIA LED Strip!
  void _draw3DRearWingEndplate(
    Canvas canvas,
    Offset Function(double lx, double ly, double lz) p3,
    double sideDir,
    bool isLitSide,
    bool ledFlash,
    bool isBraking,
    double cw,
    double fogMix,
    Color bodyCol,
    Color wingCol,
    Color skyBottom,
  ) {
    final double xOut = sideDir * 0.63;
    final double xIn = sideDir * 0.595;

    final Offset eRearB = p3(xOut, 0.34, -0.32);
    final Offset eRearT = p3(xOut, 0.88, -0.35);
    final Offset eFrontT = p3(xOut, 0.86, 0.04);
    final Offset eFrontB = p3(xOut, 0.44, 0.04);

    final Color plateBase = Color.lerp(
      isLitSide ? const Color(0xFF1D232E) : const Color(0xFF10141C),
      skyBottom,
      fogMix * 0.65,
    )!;
    _drawQuad(canvas, eRearB, eRearT, eFrontT, eFrontB, plateBase);

    if (cw > 28.0) {
      _drawQuad(
        canvas,
        p3(xOut + sideDir * 0.004, 0.60, -0.33),
        p3(xOut + sideDir * 0.004, 0.85, -0.34),
        p3(xOut + sideDir * 0.004, 0.83, 0.01),
        p3(xOut + sideDir * 0.004, 0.60, 0.01),
        isLitSide ? bodyCol : Color.lerp(bodyCol, Colors.black, 0.25)!,
      );
      _strokePaint
        ..color = wingCol.withAlpha(220)
        ..strokeWidth = max(1.0, cw * 0.012);
      canvas.drawLine(eRearT, eFrontT, _strokePaint);
    }

    final Offset edgeInB = p3(xIn, 0.34, -0.32);
    final Offset edgeInT = p3(xIn, 0.88, -0.35);
    _drawQuad(
      canvas,
      edgeInB,
      eRearB,
      eRearT,
      edgeInT,
      Color.lerp(const Color(0xFF181E29), skyBottom, fogMix * 0.6)!,
    );

    if (ledFlash && cw > 30.0) {
      final Offset ledB = p3(sideDir * 0.612, 0.42, -0.33);
      final Offset ledT = p3(sideDir * 0.612, 0.62, -0.34);
      _strokePaint
        ..color = isBraking ? const Color(0xFFFF5252) : const Color(0xDDFF1744)
        ..strokeWidth = max(1.3, cw * 0.016)
        ..strokeCap = StrokeCap.round;
      canvas.drawLine(ledB, ledT, _strokePaint);
    }
  }

  /// Wrapper for Rival F1 Car using the Unified True-3D Surface-Conforming Engine
  void _drawRivalTrue3DCar(
    Canvas canvas,
    double rz,
    double baseCamHeight,
    double camShift,
    double w,
    double horizonY,
    double fovMult,
    double trackCurv,
    double fogMix,
    double sunNormX,
    AiDriver ai,
  ) {
    final double carYaw = (ai.steerTilt * 1.15 + trackCurv * 2.2).clamp(-0.32, 0.32).toDouble();
    final double frontWheelSteer = (ai.steerTilt * 2.25 + trackCurv * 7.8).clamp(-0.46, 0.46).toDouble();
    _drawTrue3DF1Car(
      canvas: canvas,
      rz: rz,
      laneX: ai.laneX,
      trackDist: ai.trackDist,
      speedKmh: ai.currentSpeedKmh,
      carYaw: carYaw,
      frontWheelSteer: frontWheelSteer,
      baseCamHeight: baseCamHeight,
      camShift: camShift,
      w: w,
      horizonY: horizonY,
      fovMult: fovMult,
      trackCurv: trackCurv,
      fogMix: fogMix,
      sunNormX: sunNormX,
      rawBodyColor: ai.bodyColor,
      rawHiColor: ai.bodyHighlight,
      rawWingColor: ai.wingColor,
      rawHelmetColor: ai.helmetColor,
      drsOpen: ai.drsOpen,
      isBraking: ai.isBraking,
      isAccelerating: !ai.isBraking && ai.currentSpeedKmh > 15.0,
      yellowTCam: ai.skill > 0.92,
      driverCode: ai.code,
    );
  }

  /// Wrapper for Player Chase Car using the EXACT SAME Unified True-3D Surface-Conforming Engine!
  void _drawPlayerTrue3DChaseCar(
    Canvas canvas,
    double playerChaseZ,
    double baseCamHeight,
    double camShift,
    double w,
    double horizonY,
    double fovMult,
    double sunNormX,
  ) {
    final TeamLivery livery = engine.livery;
    final double curvHere = _kappaAtWorldDist(engine.playerDist);
    final double carYaw = (engine.carHeading * 0.65 + engine.steerAngle * 0.14 + engine.spinYaw * 0.55).clamp(-0.38, 0.38).toDouble();
    final double frontWheelSteer = (engine.steerAngle * 0.48).clamp(-0.48, 0.48).toDouble();
    _drawTrue3DF1Car(
      canvas: canvas,
      rz: playerChaseZ,
      laneX: engine.carX,
      trackDist: engine.playerDist,
      speedKmh: engine.speedKmh,
      carYaw: carYaw,
      frontWheelSteer: frontWheelSteer,
      baseCamHeight: baseCamHeight,
      camShift: camShift,
      w: w,
      horizonY: horizonY,
      fovMult: fovMult,
      trackCurv: curvHere,
      fogMix: 0.0,
      sunNormX: sunNormX,
      rawBodyColor: livery.primary,
      rawHiColor: livery.primaryLight,
      rawWingColor: livery.secondary,
      rawHelmetColor: livery.secondary,
      drsOpen: engine.ersActive,
      isBraking: engine.brakeHeld && engine.speedKmh > 20.0,
      isAccelerating: engine.gasHeld && !engine.brakeHeld,
      yellowTCam: true,
      driverCode: null,
    );
  }

  /// UNIFIED TRUE-3D SURFACE-CONFORMING ULTRA-HD F1 CAR ENGINE
  /// - Conforms EVERY vertex (lx, ly, lz) to the exact continuous 3D curved & sloped road spine (ZERO FLOATING!)
  /// - Real 3D Front-Wheel Steering (`frontWheelSteer`) + True Angular Wheel Rolling (`trackDist / radius`)
  /// - Live Environment Interaction: Overhead Bridge Shadows, Night Floodlight Glints, Kerb Suspension Rumble,
  ///   Brake Dive / ERS Squat, Tire Smoke Wisps, Gravel Dust Plumes & Titanium Skid Sparks!
  void _drawTrue3DF1Car({
    required Canvas canvas,
    required double rz,
    required double laneX,
    required double trackDist,
    required double speedKmh,
    required double carYaw,
    required double frontWheelSteer,
    required double baseCamHeight,
    required double camShift,
    required double w,
    required double horizonY,
    required double fovMult,
    required double trackCurv,
    required double fogMix,
    required double sunNormX,
    required Color rawBodyColor,
    required Color rawHiColor,
    required Color rawWingColor,
    required Color rawHelmetColor,
    required bool drsOpen,
    required bool isBraking,
    required bool isAccelerating,
    required bool yellowTCam,
    required String? driverCode,
  }) {
    if (rz <= 0.42) return;

    final double cosY = cos(carYaw);
    final double sinY = sin(carYaw);
    final double carLaneWorldX = laneX * engine.laneToWorldX;
    final double lapLen = engine.circuit.lapLengthMeters;
    final double lapDist = _posMod(trackDist, lapLen);

    // ENVIRONMENT INTERACTION 1: Overhead Sponsor Bridge / Start Gantry Shadows & Night Floodlight Specular Pools!
    final bool underStartGantry = lapDist < 8.5 || lapDist > lapLen - 4.0;
    final double archMod = lapDist % 380.0;
    final bool underBridge = !underStartGantry && (archMod < 11.0 || archMod > 374.0);
    final double envShade = (underStartGantry || underBridge) ? 0.42 : 0.0;
    final int lightBand = (trackDist / 1.75).floor() % 9;
    final double floodlightBoost = (engine.circuit.nightMode && envShade == 0.0 && (lightBand == 0 || lightBand == 1)) ? 0.24 : 0.0;

    // ENVIRONMENT INTERACTION 2: Kerb Suspension Rumble, Real Gravel-Trap/Grass Shake, Brake Dive, ERS Squat & Corner Roll!
    final bool onKerb = laneX.abs() > 0.84 && laneX.abs() <= 1.06;
    final double carProg = lapDist / lapLen;
    final bool onGravel = engine.isInGravelAt(laneX, carProg) || engine.isOnGrassAt(laneX, carProg);
    final double speedNorm = (speedKmh / 260.0).clamp(0.0, 1.0).toDouble();
    final double kerbBounce = (onKerb && speedKmh > 35.0)
        ? (sin(trackDist * 4.8).abs() * 0.036 * speedNorm)
        : (onGravel && speedKmh > 25.0 ? sin(trackDist * 3.6) * 0.030 * speedNorm : 0.0);
    final double suspPitch = isBraking
        ? (-0.024 * speedNorm)
        : (drsOpen ? (0.016 * speedNorm) : (isAccelerating ? (0.008 * speedNorm) : 0.0));
    final double suspRoll = (-frontWheelSteer * 0.055 * speedNorm) + (onKerb ? (-laneX.sign * 0.032) : 0.0);

    // SURFACE-CONFORMING 3D PROJECTOR (Wheels & Ground Shadows sit strictly on roadY(wz) — ZERO FLOATING!)
    Offset pGround(double lx, double ly, double lz) {
      final double wz = max(0.24, rz + lz * cosY - lx * sinY);
      final double spineX = _sampleSpineShift(wz) - camShift;
      final double spineY = baseCamHeight + _sampleSpineElev(wz);
      final double wx = spineX + carLaneWorldX + lx * cosY + lz * sinY;
      final double wy = spineY + ly;
      return _project(wx, wy, wz, w, horizonY, fovMult);
    }

    // SPRUNG CHASSIS 3D PROJECTOR (Body rides on live suspension above the road-locked tires!)
    Offset p3(double lx, double ly, double lz) {
      final double suspDy = kerbBounce + (lz - 0.80) * suspPitch + lx * suspRoll;
      return pGround(lx, max(0.015, ly + suspDy), lz);
    }

    final Offset rearL = pGround(-0.94, 0.0, 0.0);
    final Offset rearR = pGround(0.94, 0.0, 0.0);
    final double cw = (rearR.dx - rearL.dx).abs().clamp(6.0, 460.0).toDouble();
    final Color skyBottom = engine.circuit.skyBottom;

    Color shadeEnv(Color c) {
      Color out = c;
      if (envShade > 0.0) out = Color.lerp(out, Colors.black, envShade)!;
      if (floodlightBoost > 0.0) out = Color.lerp(out, const Color(0xFFE6F4FF), floodlightBoost)!;
      return Color.lerp(out, skyBottom, fogMix * 0.62)!;
    }

    final Color bodyCol = shadeEnv(rawBodyColor);
    final Color hiCol = shadeEnv(rawHiColor);
    final Color darkCol = shadeEnv(Color.lerp(rawBodyColor, Colors.black, 0.46)!);
    final Color wingCol = shadeEnv(rawWingColor);

    final double centerWorldX = (_sampleSpineShift(rz) - camShift) + carLaneWorldX;
    final double camRelX = -centerWorldX * cosY + rz * sinY;
    final double farDir = camRelX > 0.0 ? -1.0 : 1.0;
    final double nearDir = -farDir;
    final bool leftLit = sunNormX <= 0.0;
    final bool flashOn = isBraking || ((engine.totalRaceTime * 6.0).floor() % 2 == 0);

    final double rearWheelRoll = trackDist / 0.305;
    final double frontWheelRoll = trackDist / 0.270;

    if (cw < 12.0) {
      _drawQuad(
        canvas,
        pGround(-0.96, 0.004, -0.25),
        pGround(0.96, 0.004, -0.25),
        pGround(0.86, 0.004, 2.60),
        pGround(-0.86, 0.004, 2.60),
        const Color(0xBB000000),
      );
      _drawQuad(canvas, pGround(-0.92, 0.0, 0.0), pGround(-0.56, 0.0, 0.0), pGround(-0.56, 0.56, 0.0), pGround(-0.92, 0.56, 0.0), const Color(0xFF141820));
      _drawQuad(canvas, pGround(0.56, 0.0, 0.0), pGround(0.92, 0.0, 0.0), pGround(0.92, 0.56, 0.0), pGround(0.56, 0.56, 0.0), const Color(0xFF141820));
      _drawQuad(canvas, p3(-0.56, 0.14, 0.0), p3(0.56, 0.14, 0.0), p3(0.42, 0.62, 1.0), p3(-0.42, 0.62, 1.0), bodyCol);
      _drawQuad(canvas, p3(-0.62, 0.68, -0.26), p3(0.62, 0.68, -0.26), p3(0.62, 0.86, -0.26), p3(-0.62, 0.86, -0.26), wingCol);
      return;
    }

    // 1. MULTI-LAYER 3D SURFACE-CONFORMING UNDERBODY SHADOW & DIRECTIONAL SUN CAST SHADOW (ZERO FLOATING!)
    final double shOffX = -sunNormX * 0.36;
    _drawQuad(
      canvas,
      pGround(-1.14 + shOffX, 0.002, -0.46),
      pGround(1.14 + shOffX, 0.002, -0.46),
      pGround(1.04 + shOffX, 0.002, 3.28),
      pGround(-1.04 + shOffX, 0.002, 3.28),
      Color.fromARGB((92 * (1.0 - fogMix)).toInt(), 0, 0, 0),
    );
    _drawQuad(
      canvas,
      pGround(-0.88, 0.003, -0.26),
      pGround(0.88, 0.003, -0.26),
      pGround(0.78, 0.003, 2.86),
      pGround(-0.78, 0.003, 2.86),
      Color.fromARGB((212 * (1.0 - fogMix)).toInt(), 0, 0, 0),
    );
    // Subtle Car-to-Asphalt Livery Bounce-Light Reflection directly under/behind close cars!
    if (cw > 44.0) {
      final Offset bounceC = pGround(0.0, 0.006, 0.70);
      final double br = cw * 0.52;
      _fillPaint.color = rawBodyColor.withAlpha(((engine.circuit.nightMode ? 44 : 26) * (1.0 - fogMix)).toInt().clamp(0, 255).toInt());
      canvas.drawOval(Rect.fromCenter(center: bounceC, width: br * 1.35, height: br * 0.28), _fillPaint);
    }
    // Real-Time Dark Tire Scrub / Skid Streaks trailing immediately behind rear tires under hard braking or high-G slip!
    if (cw > 36.0 && speedKmh > 75.0 && (isBraking || trackCurv.abs() > 0.019)) {
      _strokePaint
        ..color = Color.fromARGB(((isBraking ? 122 : 76) * (1.0 - fogMix)).toInt(), 5, 6, 10)
        ..strokeWidth = max(2.0, cw * 0.055)
        ..strokeCap = StrokeCap.round;
      for (final double sDir in const [-1.0, 1.0]) {
        canvas.drawLine(pGround(sDir * 0.75, 0.006, -0.05), pGround(sDir * 0.76, 0.006, -1.65), _strokePaint);
      }
    }
    if (flashOn && cw > 36.0) {
      final Offset glowGround = pGround(0.0, 0.008, -0.50);
      final double gr = cw * (isBraking ? 0.26 : 0.15);
      _gradPaint.shader = RadialGradient(
        colors: [
          Color.fromARGB((isBraking ? 136 : 72), 255, 24, 58),
          const Color(0x00FF1744),
        ],
      ).createShader(Rect.fromCircle(center: glowGround, radius: gr));
      canvas.drawOval(Rect.fromCenter(center: glowGround, width: gr * 1.9, height: gr * 0.52), _gradPaint);
    }

    // 2. 3D MULTI-ELEMENT FRONT WING & FRONT WING ENDPLATES (z = 2.68 .. 3.18)
    _drawQuad(
      canvas,
      p3(-0.96, 0.09, 2.72),
      p3(0.96, 0.09, 2.72),
      p3(0.92, 0.07, 3.16),
      p3(-0.92, 0.07, 3.16),
      Color.lerp(const Color(0xFF141820), skyBottom, fogMix * 0.6)!,
    );
    _drawQuad(
      canvas,
      p3(-0.94, 0.16, 2.68),
      p3(0.94, 0.16, 2.68),
      p3(0.90, 0.11, 2.98),
      p3(-0.90, 0.11, 2.98),
      wingCol,
    );
    if (cw > 26.0) {
      // Multi-element upper front wing cascade flap + curved endplates + nose wing pylons!
      _drawQuad(
        canvas,
        p3(-0.88, 0.21, 2.62),
        p3(0.88, 0.21, 2.62),
        p3(0.84, 0.16, 2.86),
        p3(-0.84, 0.16, 2.86),
        Color.lerp(bodyCol, hiCol, 0.35)!,
      );
      for (final double sDir in [farDir, nearDir]) {
        _drawQuad(
          canvas,
          p3(sDir * 0.96, 0.07, 2.66),
          p3(sDir * 0.96, 0.28, 2.66),
          p3(sDir * 0.94, 0.22, 3.16),
          p3(sDir * 0.94, 0.07, 3.16),
          bodyCol,
        );
        // Sculpted carbon front-wing mounting pylon
        _strokePaint
          ..color = const Color(0xFF141820)
          ..strokeWidth = max(1.0, cw * 0.013);
        canvas.drawLine(p3(sDir * 0.08, 0.16, 2.98), p3(sDir * 0.08, 0.09, 3.02), _strokePaint);
      }
    }

    // 3. FRONT DOUBLE-WISHBONE CARBON SUSPENSION + STEERING 3D FRONT TIRES (Far -> Near!)
    if (cw > 26.0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF1C222D), skyBottom, fogMix * 0.6)!
        ..strokeWidth = max(1.1, cw * 0.016);
      canvas.drawLine(p3(farDir * 0.22, 0.34, 2.34), pGround(farDir * 0.64, 0.34, 2.38), _strokePaint);
      canvas.drawLine(p3(farDir * 0.20, 0.18, 2.30), pGround(farDir * 0.64, 0.18, 2.38), _strokePaint);
    }
    _draw3DTire(canvas, pGround, farDir, 2.38, 0.155, 0.27, false, false, isBraking, frontWheelSteer, frontWheelRoll, cw, fogMix, envShade, skyBottom);

    // 4. 3D TAPERED SCULPTED NOSECONE (z = 1.90 .. 3.12)
    final Offset nRearL = p3(-0.26, 0.48, 1.92);
    final Offset nRearR = p3(0.26, 0.48, 1.92);
    final Offset nTipL = p3(-0.10, 0.18, 3.12);
    final Offset nTipR = p3(0.10, 0.18, 3.12);
    final Offset nBotFarRear = p3(farDir * 0.24, 0.22, 1.92);
    final Offset nBotFarTip = p3(farDir * 0.09, 0.11, 3.12);
    final Offset nBotNearRear = p3(nearDir * 0.24, 0.22, 1.92);
    final Offset nBotNearTip = p3(nearDir * 0.09, 0.11, 3.12);

    _drawQuad(canvas, nBotFarRear, p3(farDir * 0.26, 0.48, 1.92), p3(farDir * 0.10, 0.18, 3.12), nBotFarTip, darkCol);
    // PBR Clearcoat Specular Gradient across the sculpted nosecone top surface
    _drawGradQuad(
      canvas,
      nRearL,
      nRearR,
      nTipR,
      nTipL,
      LinearGradient(
        begin: Alignment(sunNormX * 0.6, -1.0),
        end: Alignment(-sunNormX * 0.6, 1.0),
        colors: [
          Color.lerp(hiCol, Colors.white, 0.30)!,
          Color.lerp(bodyCol, hiCol, 0.42)!,
          bodyCol,
        ],
      ).createShader(Rect.fromPoints(nRearL, nTipR)),
    );
    _drawQuad(canvas, nBotNearRear, p3(nearDir * 0.26, 0.48, 1.92), p3(nearDir * 0.10, 0.18, 3.12), nBotNearTip, Color.lerp(bodyCol, Colors.black, 0.22)!);
    if (cw > 34.0) {
      _strokePaint
        ..color = wingCol
        ..strokeWidth = max(1.1, cw * 0.015);
      canvas.drawLine(p3(0.0, 0.49, 1.95), p3(0.0, 0.18, 3.06), _strokePaint);
    }

    // Near front suspension & near steering front tire!
    if (cw > 26.0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF1F2633), skyBottom, fogMix * 0.6)!
        ..strokeWidth = max(1.2, cw * 0.017);
      canvas.drawLine(p3(nearDir * 0.22, 0.34, 2.34), pGround(nearDir * 0.64, 0.34, 2.38), _strokePaint);
      canvas.drawLine(p3(nearDir * 0.20, 0.18, 2.30), pGround(nearDir * 0.64, 0.18, 2.38), _strokePaint);
    }
    _draw3DTire(canvas, pGround, nearDir, 2.38, 0.155, 0.27, false, true, isBraking, frontWheelSteer, frontWheelRoll, cw, fogMix, envShade, skyBottom);

    // 5. 3D CARBON FLOOR PLANK (Live Twill Carbon Weave Shader up close!), VENTURI EDGE WINGS & SPARKS
    final Color carbonBase = Color.lerp(const Color(0xFF0E1118), skyBottom, fogMix * 0.6)!;
    final Color carbonEdge = Color.lerp(const Color(0xFF313D52), skyBottom, fogMix * 0.6)!;
    if (cw > 46.0 && UltraTextures.carbonShader != null) {
      _drawGradQuad(canvas, p3(-0.75, 0.07, -0.16), p3(0.75, 0.07, -0.16), p3(0.74, 0.07, 1.95), p3(-0.74, 0.07, 1.95), UltraTextures.carbonShader!);
    } else {
      _drawQuad(canvas, p3(-0.75, 0.07, -0.16), p3(0.75, 0.07, -0.16), p3(0.74, 0.07, 1.95), p3(-0.74, 0.07, 1.95), carbonBase);
    }
    if (cw > 32.0) {
      _strokePaint
        ..color = carbonEdge
        ..strokeWidth = max(1.2, cw * 0.015);
      canvas.drawLine(p3(-0.76, 0.09, -0.12), p3(-0.75, 0.09, 1.92), _strokePaint);
      canvas.drawLine(p3(0.76, 0.09, -0.12), p3(0.75, 0.09, 1.92), _strokePaint);
      if ((speedKmh > 265.0 || (onKerb && speedKmh > 165.0)) && ((engine.totalRaceTime * 26.0 + trackDist).floor() % 3 == 0)) {
        final Offset sp1 = pGround(-0.15, 0.03, -0.22);
        final Offset sp2 = pGround(0.17, 0.02, -0.32);
        final Offset sp3 = pGround(0.02, 0.06, -0.52);
        _strokePaint
          ..color = const Color(0xF5FFE082)
          ..strokeWidth = max(1.4, cw * 0.014)
          ..strokeCap = StrokeCap.round;
        canvas.drawLine(sp1, pGround(-0.24, 0.08, -0.68), _strokePaint);
        canvas.drawLine(sp2, pGround(0.26, 0.07, -0.74), _strokePaint);
        _fillPaint.color = const Color(0xFFFFF59D);
        canvas.drawCircle(sp3, max(1.6, cw * 0.015), _fillPaint);
      }
    }

    // 6. FAR-SIDE SCULPTED 3D SIDEPOD
    _draw3DSidepod(canvas, p3, farDir, farDir < 0 ? leftLit : !leftLit, cw, fogMix, bodyCol, hiCol, darkCol, wingCol, skyBottom);

    // 7. 3D COCKPIT SURROUND, SIDE MIRRORS, DRIVER HELMET, VISOR, TITANIUM HALO, AIRBOX, SHARK FIN & T-CAM
    _drawQuad(
      canvas,
      p3(-0.27, 0.50, 1.44),
      p3(0.27, 0.50, 1.44),
      p3(0.25, 0.48, 2.04),
      p3(-0.25, 0.48, 2.04),
      const Color(0xFF0A0D13),
    );
    if (cw > 36.0) {
      for (final double sDir in [farDir, nearDir]) {
        final Offset stalkBase = p3(sDir * 0.34, 0.50, 1.82);
        final Offset mirrorC = p3(sDir * 0.50, 0.58, 1.84);
        _strokePaint
          ..color = const Color(0xFF151922)
          ..strokeWidth = max(1.0, cw * 0.012);
        canvas.drawLine(stalkBase, mirrorC, _strokePaint);
        _drawQuad(
          canvas,
          p3(sDir * 0.44, 0.55, 1.82),
          p3(sDir * 0.56, 0.55, 1.82),
          p3(sDir * 0.56, 0.62, 1.82),
          p3(sDir * 0.44, 0.62, 1.82),
          bodyCol,
        );
      }
    }

    final double helmetTiltX = frontWheelSteer * 0.055;
    final Offset helmetC = p3(helmetTiltX, 0.68, 1.66);
    final double helmetR = max(2.2, (p3(helmetTiltX + 0.145, 0.68, 1.66).dx - helmetC.dx).abs());
    _gradPaint.shader = RadialGradient(
      center: Alignment(sunNormX * 0.4, -0.45),
      colors: [
        Color.lerp(rawHelmetColor, Colors.white, 0.42)!,
        shadeEnv(rawHelmetColor),
        Color.lerp(rawHelmetColor, Colors.black, 0.42)!,
      ],
    ).createShader(Rect.fromCircle(center: helmetC, radius: helmetR));
    canvas.drawCircle(helmetC, helmetR, _gradPaint);
    if (cw > 34.0) {
      // Iridescent Metallic F1 Helmet Visor (Sapphire -> Cyan -> Gold Sheen!)
      final Rect visorRect = Rect.fromCenter(
        center: Offset(helmetC.dx, helmetC.dy - helmetR * 0.05),
        width: helmetR * 1.56,
        height: helmetR * 0.45,
      );
      _gradPaint.shader = const LinearGradient(
        begin: Alignment.centerLeft,
        end: Alignment.centerRight,
        colors: [Color(0xF00A1428), Color(0xF000A8E8), Color(0xF0FFE082), Color(0xF00D182E)],
      ).createShader(visorRect);
      canvas.drawRRect(RRect.fromRectAndRadius(visorRect, Radius.circular(helmetR * 0.2)), _gradPaint);
      // Specular highlight dot on helmet crown
      _fillPaint.color = const Color(0xBBFFFFFF);
      canvas.drawCircle(Offset(helmetC.dx - helmetR * 0.28, helmetC.dy - helmetR * 0.35), max(1.1, helmetR * 0.17), _fillPaint);
      // Visible 3D Driver Shoulders & Steering Arms inside open cockpit when close!
      if (cw > 62.0) {
        _strokePaint
          ..color = Color.lerp(bodyCol, Colors.black, 0.25)!
          ..strokeWidth = max(2.2, cw * 0.032)
          ..strokeCap = StrokeCap.round;
        final double armShift = frontWheelSteer * 0.08;
        canvas.drawLine(p3(-0.18, 0.53, 1.62), p3(-0.08 + armShift, 0.56, 1.94), _strokePaint);
        canvas.drawLine(p3(0.18, 0.53, 1.62), p3(0.08 + armShift, 0.56, 1.94), _strokePaint);
      }
    }

    if (cw > 24.0) {
      final Offset haloFront = p3(0.0, 0.69, 2.08);
      final Offset haloBase = p3(0.0, 0.48, 2.12);
      final Offset haloFarMid = p3(farDir * 0.24, 0.72, 1.82);
      final Offset haloFarBack = p3(farDir * 0.25, 0.62, 1.46);
      final Offset haloNearMid = p3(nearDir * 0.24, 0.72, 1.82);
      final Offset haloNearBack = p3(nearDir * 0.25, 0.62, 1.46);

      _strokePaint
        ..color = Color.lerp(const Color(0xFF151922), skyBottom, fogMix * 0.5)!
        ..strokeWidth = max(1.6, cw * 0.024)
        ..strokeCap = StrokeCap.round;
      canvas.drawLine(haloBase, haloFront, _strokePaint);
      canvas.drawLine(haloFront, haloFarMid, _strokePaint);
      canvas.drawLine(haloFarMid, haloFarBack, _strokePaint);
      canvas.drawLine(haloFront, haloNearMid, _strokePaint);
      canvas.drawLine(haloNearMid, haloNearBack, _strokePaint);

      _strokePaint
        ..color = Color.lerp(hiCol, Colors.white, 0.35)!.withAlpha(185)
        ..strokeWidth = max(0.8, cw * 0.009);
      canvas.drawLine(haloFront, haloNearMid, _strokePaint);
      canvas.drawLine(haloNearMid, haloNearBack, _strokePaint);
    }

    final Offset abFarRear = p3(farDir * 0.14, 0.56, 0.04);
    final Offset abFarTop = p3(farDir * 0.12, 0.87, 1.42);
    final Offset abNearTop = p3(nearDir * 0.12, 0.87, 1.42);
    final Offset abNearRear = p3(nearDir * 0.14, 0.56, 0.04);
    final Offset abTopRear = p3(0.0, 0.60, 0.04);
    final Offset abTopFront = p3(0.0, 0.90, 1.44);

    _drawQuad(canvas, p3(farDir * 0.24, 0.56, 1.44), abFarTop, abTopRear, abFarRear, darkCol);
    _drawGradQuad(
      canvas,
      p3(nearDir * 0.24, 0.56, 1.44),
      abNearTop,
      abTopRear,
      abNearRear,
      LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: [Color.lerp(hiCol, Colors.white, 0.22)!, bodyCol, darkCol],
      ).createShader(Rect.fromPoints(abNearTop, abNearRear)),
    );
    _drawGradQuad(
      canvas,
      abFarTop,
      abNearTop,
      abNearRear,
      abFarRear,
      LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: [Color.lerp(hiCol, Colors.white, 0.36)!, hiCol, bodyCol],
      ).createShader(Rect.fromPoints(abFarTop, abNearRear)),
    );

    if (cw > 30.0) {
      _drawPoly(
        canvas,
        [p3(-0.09, 0.78, 1.46), p3(0.09, 0.78, 1.46), p3(0.0, 0.88, 1.46)],
        const Color(0xFF07090E),
      );
    }

    _drawQuad(
      canvas,
      p3(0.0, 0.54, 0.04),
      p3(0.0, 0.74, 0.06),
      abTopFront,
      p3(0.0, 0.62, 1.38),
      bodyCol,
    );
    if (cw > 26.0) {
      _strokePaint
        ..color = wingCol
        ..strokeWidth = max(1.1, cw * 0.015);
      canvas.drawLine(p3(0.0, 0.74, 0.06), abTopFront, _strokePaint);
    }

    final Offset tStemB = p3(0.0, 0.89, 1.44);
    final Offset tStemT = p3(0.0, 0.96, 1.44);
    _strokePaint
      ..color = const Color(0xFF141820)
      ..strokeWidth = max(1.3, cw * 0.018);
    canvas.drawLine(tStemB, tStemT, _strokePaint);
    _drawQuad(
      canvas,
      p3(-0.15, 0.95, 1.42),
      p3(0.15, 0.95, 1.42),
      p3(0.15, 0.99, 1.42),
      p3(-0.15, 0.99, 1.42),
      yellowTCam ? const Color(0xFFFFEB3B) : const Color(0xFF1A202B),
    );

    // 8. NEAR-SIDE SCULPTED 3D SIDEPOD
    _draw3DSidepod(canvas, p3, nearDir, nearDir < 0 ? leftLit : !leftLit, cw, fogMix, bodyCol, hiCol, darkCol, wingCol, skyBottom);

    // 9. FAR-SIDE REAR ROLLING TIRE & REAR SUSPENSION
    _draw3DTire(canvas, pGround, farDir, 0.04, 0.19, 0.305, true, false, isBraking, 0.0, rearWheelRoll, cw, fogMix, envShade, skyBottom);
    if (cw > 24.0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF1A202B), skyBottom, fogMix * 0.6)!
        ..strokeWidth = max(1.3, cw * 0.019);
      canvas.drawLine(p3(farDir * 0.18, 0.38, 0.00), pGround(farDir * 0.56, 0.42, 0.04), _strokePaint);
      canvas.drawLine(p3(farDir * 0.22, 0.22, -0.02), pGround(farDir * 0.56, 0.22, 0.04), _strokePaint);
    }

    // 10. HYPER-DETAILED 3D REAR DIFFUSER, VENTURI STRAKES, BEAM WING & METALLIC EXHAUST
    final Offset dfL = p3(-0.52, 0.06, -0.18);
    final Offset dfR = p3(0.52, 0.06, -0.18);
    final Offset dfTR = p3(0.48, 0.28, -0.16);
    final Offset dfTL = p3(-0.48, 0.28, -0.16);
    _drawQuad(canvas, dfL, dfR, dfTR, dfTL, Color.lerp(const Color(0xFF0B0E14), skyBottom, fogMix * 0.6)!);
    _drawQuad(
      canvas,
      dfTL,
      dfTR,
      p3(0.46, 0.30, -0.04),
      p3(-0.46, 0.30, -0.04),
      Color.lerp(const Color(0xFF283140), skyBottom, fogMix * 0.6)!,
    );
    if (cw > 28.0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF56667D), skyBottom, fogMix * 0.5)!
        ..strokeWidth = max(1.0, cw * 0.013);
      for (final double sx in const [-0.36, -0.18, 0.18, 0.36]) {
        canvas.drawLine(p3(sx, 0.06, -0.18), p3(sx * 0.94, 0.27, -0.16), _strokePaint);
      }
      _drawQuad(
        canvas,
        p3(-0.08, 0.15, -0.22),
        p3(0.08, 0.15, -0.22),
        p3(0.07, 0.34, -0.22),
        p3(-0.07, 0.34, -0.22),
        const Color(0xFF171C26),
      );
    }

    _drawQuad(
      canvas,
      p3(-0.54, 0.35, -0.24),
      p3(0.54, 0.35, -0.24),
      p3(0.54, 0.43, -0.20),
      p3(-0.54, 0.43, -0.20),
      Color.lerp(const Color(0xFF1A212E), skyBottom, fogMix * 0.6)!,
    );

    if (cw > 26.0) {
      final Offset exC = p3(0.0, 0.44, -0.16);
      final double exR = max(1.8, cw * 0.038);
      // Machined titanium exhaust ring + live ERS / high-RPM exhaust glow!
      _fillPaint.color = Color.lerp(const Color(0xFFC2CFE0), skyBottom, fogMix * 0.5)!;
      canvas.drawCircle(exC, exR, _fillPaint);
      _fillPaint.color = drsOpen ? const Color(0xFF1B3B5A) : const Color(0xFF0A0C10);
      canvas.drawCircle(exC, exR * 0.64, _fillPaint);
      if ((drsOpen || (isAccelerating && speedKmh > 210.0)) && cw > 42.0) {
        final double plumeR = exR * (drsOpen ? 2.6 : 1.8);
        _gradPaint.shader = RadialGradient(
          colors: drsOpen
              ? const [Color(0xDD60F4FF), Color(0x6600B0FF), Color(0x0000B0FF)]
              : const [Color(0xAAFFAB40), Color(0x44FF5722), Color(0x00FF5722)],
        ).createShader(Rect.fromCircle(center: exC, radius: plumeR));
        canvas.drawCircle(exC, plumeR, _gradPaint);
      }
      // Subtle shimmering thermal exhaust heat-haze wave behind tailpipe!
      if (cw > 52.0 && speedKmh > 60.0) {
        final double shimmer = sin(engine.totalRaceTime * 28.0 + trackDist) * 0.05;
        final Offset hazeC = p3(shimmer, 0.45, -0.52);
        _fillPaint.color = Color.fromARGB((28 * (1.0 - fogMix)).toInt(), 255, 240, 210);
        canvas.drawOval(Rect.fromCenter(center: hazeC, width: exR * 3.8, height: exR * 2.1), _fillPaint);
      }
    }

    // 11. NEAR-SIDE REAR SUSPENSION & NEAR-SIDE REAR ROLLING TIRE
    if (cw > 24.0) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF1F2634), skyBottom, fogMix * 0.6)!
        ..strokeWidth = max(1.3, cw * 0.019);
      canvas.drawLine(p3(nearDir * 0.18, 0.38, 0.00), pGround(nearDir * 0.56, 0.42, 0.04), _strokePaint);
      canvas.drawLine(p3(nearDir * 0.22, 0.22, -0.02), pGround(nearDir * 0.56, 0.22, 0.04), _strokePaint);
    }
    _draw3DTire(canvas, pGround, nearDir, 0.04, 0.19, 0.305, true, true, isBraking, 0.0, rearWheelRoll, cw, fogMix, envShade, skyBottom);

    // ENVIRONMENT INTERACTION 3: Surface-Aware Tire Smoke (Hard Braking / Cornering Slip) & Gravel Dust Plumes!
    if (cw > 34.0 && speedKmh > 45.0) {
      final bool highSlipSmoke = (isBraking && speedKmh > 125.0) || (trackCurv.abs() > 0.018 && speedKmh > 145.0);
      if (onGravel || highSlipSmoke) {
        final Color puffBase = onGravel ? const Color(0xFFC5AB80) : const Color(0xFFE5EDF5);
        final double puffPhase = (trackDist * 0.45) % 1.0;
        for (final double sDir in const [-1.0, 1.0]) {
          for (int k = 0; k < 2; k++) {
            final double pFrac = (puffPhase + k * 0.5) % 1.0;
            final Offset puffC = pGround(sDir * (0.75 + pFrac * 0.08), 0.10 + pFrac * 0.24, -0.26 - pFrac * 0.72);
            final double pr = max(3.0, cw * (0.048 + pFrac * 0.055));
            final int a = (((1.0 - pFrac) * (onGravel ? 115 : 84)) * (1.0 - fogMix)).toInt().clamp(0, 255).toInt();
            _gradPaint.shader = RadialGradient(
              colors: [puffBase.withAlpha(a), puffBase.withAlpha(0)],
            ).createShader(Rect.fromCircle(center: puffC, radius: pr));
            canvas.drawCircle(puffC, pr, _gradPaint);
          }
        }
      }
    }

    // 12. TRUE 3D MULTI-PLANE REAR WING (Far Endplate -> Swan-Neck Pylons -> Spoon Mainplane -> Animated DRS Flap -> Near Endplate!)
    _draw3DRearWingEndplate(canvas, p3, farDir, farDir < 0 ? leftLit : !leftLit, flashOn, isBraking, cw, fogMix, bodyCol, wingCol, skyBottom);

    _strokePaint
      ..color = Color.lerp(const Color(0xFF161B24), skyBottom, fogMix * 0.6)!
      ..strokeWidth = max(1.4, cw * 0.020);
    canvas.drawLine(p3(-0.07, 0.38, -0.14), p3(-0.07, 0.72, -0.22), _strokePaint);
    canvas.drawLine(p3(0.07, 0.38, -0.14), p3(0.07, 0.72, -0.22), _strokePaint);

    final Offset mpL = p3(-0.60, 0.66, -0.26);
    final Offset mpMid = p3(0.0, 0.63, -0.28);
    final Offset mpR = p3(0.60, 0.66, -0.26);
    final Offset mpLT = p3(-0.60, 0.74, -0.28);
    final Offset mpMidT = p3(0.0, 0.72, -0.30);
    final Offset mpRT = p3(0.60, 0.74, -0.28);
    _drawQuad(
      canvas,
      mpL,
      mpR,
      p3(0.60, 0.64, -0.04),
      p3(-0.60, 0.64, -0.04),
      Color.lerp(const Color(0xFF0A0D14), skyBottom, fogMix * 0.6)!,
    );
    _drawQuad(canvas, mpL, mpMid, mpMidT, mpLT, Color.lerp(wingCol, Colors.black, 0.14)!);
    _drawQuad(canvas, mpMid, mpR, mpRT, mpMidT, Color.lerp(wingCol, Colors.black, 0.24)!);

    final double flapLowY = drsOpen ? 0.83 : 0.75;
    final double flapHighY = drsOpen ? 0.88 : 0.86;
    final double flapLowZ = drsOpen ? -0.14 : -0.29;
    final Offset flL = p3(-0.60, flapLowY, flapLowZ);
    final Offset flR = p3(0.60, flapLowY, flapLowZ);
    final Offset flTR = p3(0.60, flapHighY, -0.34);
    final Offset flTL = p3(-0.60, flapHighY, -0.34);
    final Rect flapBounds = Rect.fromPoints(flTL, flR);
    _drawGradQuad(
      canvas,
      flL,
      flR,
      flTR,
      flTL,
      LinearGradient(
        begin: Alignment.topCenter,
        end: Alignment.bottomCenter,
        colors: drsOpen
            ? [const Color(0xFFA6F8FF), wingCol]
            : [Color.lerp(wingCol, Colors.white, 0.30)!, wingCol],
      ).createShader(flapBounds),
    );
    if (cw > 30.0) {
      _drawQuad(
        canvas,
        p3(-0.045, 0.71, -0.30),
        p3(0.045, 0.71, -0.30),
        p3(0.04, 0.85, -0.34),
        p3(-0.04, 0.85, -0.34),
        drsOpen ? const Color(0xFF00E5FF) : const Color(0xFF141820),
      );
    }

    _draw3DRearWingEndplate(canvas, p3, nearDir, nearDir < 0 ? leftLit : !leftLit, flashOn, isBraking, cw, fogMix, bodyCol, wingCol, skyBottom);

    // 12B. HIGH-SPEED REAR WINGTIP AERO VORTEX RIBBONS (Visible >230 km/h or DRS/ERS open!)
    if ((speedKmh > 230.0 || drsOpen) && cw > 38.0) {
      final double vAlpha = (((speedKmh - 215.0) / 145.0).clamp(0.18, 0.85).toDouble() * (1.0 - fogMix));
      final Color vortCol = drsOpen
          ? Color.fromARGB((vAlpha * 115).toInt(), 110, 240, 255)
          : Color.fromARGB((vAlpha * 72).toInt(), 235, 245, 255);
      final double wave = sin(trackDist * 0.85) * 0.04;
      _strokePaint
        ..color = vortCol
        ..strokeWidth = max(1.1, cw * 0.012)
        ..strokeCap = StrokeCap.round;
      for (final double sDir in const [-1.0, 1.0]) {
        final Offset vt0 = p3(sDir * 0.62, 0.86, -0.35);
        final Offset vt1 = p3(sDir * 0.67 + wave, 0.80, -0.82);
        final Offset vt2 = p3(sDir * 0.72 - wave, 0.72, -1.35);
        canvas.drawLine(vt0, vt1, _strokePaint);
        _strokePaint.color = vortCol.withAlpha((vortCol.alpha * 0.45).toInt());
        canvas.drawLine(vt1, vt2, _strokePaint);
        _strokePaint.color = vortCol;
      }
    }

    // 13. CENTRAL VERTICAL FIA LED RAIN / BRAKE LIGHT WITH BLOOM
    if (flashOn) {
      final Offset lightC = p3(0.0, 0.24, -0.23);
      final double lr = max(3.5, cw * (isBraking ? 0.14 : 0.085));
      _gradPaint.shader = const RadialGradient(
        colors: [Color(0xFFFF526A), Color(0x88FF1744), Color(0x00FF1744)],
      ).createShader(Rect.fromCircle(center: lightC, radius: lr));
      canvas.drawCircle(lightC, lr, _gradPaint);
      _fillPaint.color = isBraking ? const Color(0xFFFFB2BD) : const Color(0xFFFF4562);
      canvas.drawRRect(
        RRect.fromRectAndRadius(
          Rect.fromCenter(center: lightC, width: max(2.0, cw * 0.036), height: max(4.0, cw * 0.085)),
          const Radius.circular(1.5),
        ),
        _fillPaint,
      );
    }

    // 14. BROADCAST DRIVER TELEMETRY TAG (Only on Rivals!)
    if (driverCode != null && cw > 22.0) {
      final Offset tagAnchor = p3(0.0, 1.16, 0.90);
      final TextPainter tp = _getCachedTag(driverCode);
      final double pillW = tp.width + (drsOpen ? 18.0 : 10.0);
      final double bx = tagAnchor.dx - pillW * 0.5;
      final double by = tagAnchor.dy - tp.height - 2.0;
      _fillPaint.color = const Color(0xD4070B12);
      canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(bx, by - 1, pillW, tp.height + 2), const Radius.circular(4)), _fillPaint);
      _fillPaint.color = drsOpen ? const Color(0xFF00E5FF) : rawBodyColor;
      canvas.drawRect(Rect.fromLTWH(bx, by - 1, 3.0, tp.height + 2), _fillPaint);
      tp.paint(canvas, Offset(bx + 5.5, by));
      if (drsOpen) {
        _fillPaint.color = const Color(0xFF00E5FF);
        canvas.drawCircle(Offset(bx + pillW - 5.0, by + tp.height * 0.5), 2.5, _fillPaint);
      }
    }
  }

  /// Hyper-Realistic 3D F1 Broadcast Cockpit (Real G-Force Head Inertia, Monocoque Bolsters, Aeroscreen Lip,
  /// Airfoil Suspension, Thermal Carbon Brakes, Halo Fairing, Side Marshal LEDs & Broadcast OLED Steering Wheel!)
  void _drawCockpitUltra(Canvas canvas, double w, double h, double sunNormX, CircuitInfo circuit) {
    final TeamLivery livery = engine.livery;
    final double cx = w * 0.5;
    final double vib = engine.smoothCockpitHeave;
    // Real-life helmet lateral G-force sway & longitudinal braking/ERS head zoom!
    final double gShiftX = (-engine.steerAngle * 6.5) - (engine.smoothLatG * 7.5);
    final double headZoom = (1.0 - engine.smoothLongG * 0.018).clamp(0.975, 1.028).toDouble();

    canvas.save();
    if ((headZoom - 1.0).abs() > 0.0005) {
      canvas.translate(cx, h * 0.72);
      canvas.scale(headZoom, headZoom);
      canvas.translate(-cx, -h * 0.72);
    }

    final Paint carbonPaint = _carbonPaint ?? (_fillPaint..color = const Color(0xFF14171E));

    final double wheelShift = engine.steerAngle * 24.0;

    // 1. Sculpted 3D Multi-Element Front Wing (Primary Paint Plane + Carbon Cascade + Metallic Flap Turnbuckles + Endplates)
    _gradPaint.shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      colors: [livery.primaryLight, livery.primary, livery.primaryDark],
    ).createShader(Rect.fromLTWH(0, h * 0.56, w, 48));
    _scratchPath
      ..reset()
      ..moveTo(w * 0.052 + wheelShift * 0.65, h * 0.585 + vib)
      ..lineTo(w * 0.218 + wheelShift * 0.55, h * 0.605 + vib)
      ..lineTo(w * 0.208 + wheelShift * 0.55, h * 0.629 + vib)
      ..lineTo(w * 0.045 + wheelShift * 0.65, h * 0.609 + vib)
      ..close();
    canvas.drawPath(_scratchPath, _gradPaint);
    _scratchPath
      ..reset()
      ..moveTo(w * 0.948 + wheelShift * 0.65, h * 0.585 + vib)
      ..lineTo(w * 0.782 + wheelShift * 0.55, h * 0.605 + vib)
      ..lineTo(w * 0.792 + wheelShift * 0.55, h * 0.629 + vib)
      ..lineTo(w * 0.955 + wheelShift * 0.65, h * 0.609 + vib)
      ..close();
    canvas.drawPath(_scratchPath, _gradPaint);

    // Secondary Carbon Upper Cascade Flap + Titanium Flap Adjuster Struts
    _scratchPath
      ..reset()
      ..moveTo(w * 0.060 + wheelShift * 0.65, h * 0.576 + vib)
      ..lineTo(w * 0.198 + wheelShift * 0.55, h * 0.594 + vib)
      ..lineTo(w * 0.194 + wheelShift * 0.55, h * 0.607 + vib)
      ..lineTo(w * 0.056 + wheelShift * 0.65, h * 0.590 + vib)
      ..close();
    canvas.drawPath(_scratchPath, carbonPaint);
    _scratchPath
      ..reset()
      ..moveTo(w * 0.940 + wheelShift * 0.65, h * 0.576 + vib)
      ..lineTo(w * 0.802 + wheelShift * 0.55, h * 0.594 + vib)
      ..lineTo(w * 0.806 + wheelShift * 0.55, h * 0.607 + vib)
      ..lineTo(w * 0.944 + wheelShift * 0.65, h * 0.590 + vib)
      ..close();
    canvas.drawPath(_scratchPath, carbonPaint);
    _strokePaint..color = const Color(0xBBFFFFFF)..strokeWidth = 1.4;
    canvas.drawLine(Offset(w * 0.060 + wheelShift * 0.65, h * 0.576 + vib), Offset(w * 0.198 + wheelShift * 0.55, h * 0.594 + vib), _strokePaint);
    canvas.drawLine(Offset(w * 0.940 + wheelShift * 0.65, h * 0.576 + vib), Offset(w * 0.802 + wheelShift * 0.55, h * 0.594 + vib), _strokePaint);
    // Metallic flap adjuster turnbuckles
    _strokePaint..color = const Color(0xFFD6E2F0)..strokeWidth = 2.0;
    canvas.drawLine(Offset(w * 0.135 + wheelShift * 0.60, h * 0.586 + vib), Offset(w * 0.135 + wheelShift * 0.60, h * 0.606 + vib), _strokePaint);
    canvas.drawLine(Offset(w * 0.865 + wheelShift * 0.60, h * 0.586 + vib), Offset(w * 0.865 + wheelShift * 0.60, h * 0.606 + vib), _strokePaint);

    // Sculpted Vertical Wing Endplates with Specular Rim
    _fillPaint.color = livery.secondary;
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.044 + wheelShift * 0.65, h * 0.566 + vib, 8.0, 32), const Radius.circular(2.5)), _fillPaint);
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.948 + wheelShift * 0.65, h * 0.566 + vib, 8.0, 32), const Radius.circular(2.5)), _fillPaint);
    _fillPaint.color = const Color(0x99FFFFFF);
    canvas.drawRect(Rect.fromLTWH(w * 0.046 + wheelShift * 0.65, h * 0.568 + vib, 2.2, 28), _fillPaint);
    canvas.drawRect(Rect.fromLTWH(w * 0.950 + wheelShift * 0.65, h * 0.568 + vib, 2.2, 28), _fillPaint);

    // 2. Massive 3D Perspective Front Pirelli Slicks (with Carbon Brake Ducts & Thermal Glowing Carbon Discs!)
    _drawFrontTireUltra(canvas, Offset(w * 0.165 + wheelShift, h * 0.718 + vib), w * 0.174, h * 0.338, true);
