  void _drawSideMirrorUltra(Canvas canvas, Offset pos, bool isLeft, bool rivalBehind, CircuitInfo circuit) {
    final TeamLivery livery = engine.livery;
    final double dir = isLeft ? -1.0 : 1.0;
    // Sculpted dual aerodynamic mirror stalks
    _strokePaint..color = const Color(0xFF141822)..strokeWidth = 5.0..strokeCap = StrokeCap.round;
    canvas.drawLine(Offset(pos.dx - dir * 13, pos.dy + 20), Offset(pos.dx, pos.dy + 4), _strokePaint);
    _strokePaint..color = const Color(0xFF2D3648)..strokeWidth = 2.6;
    canvas.drawLine(Offset(pos.dx + dir * 9, pos.dy + 17), Offset(pos.dx + dir * 13, pos.dy + 3), _strokePaint);

    final RRect shell = RRect.fromRectAndRadius(Rect.fromCenter(center: pos, width: 58, height: 24), const Radius.circular(9));
    _gradPaint.shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      colors: [livery.primaryLight, livery.primary, livery.primaryDark],
    ).createShader(shell.outerRect);
    canvas.drawRRect(shell, _gradPaint);
    _strokePaint..color = const Color(0x55FFFFFF)..strokeWidth = 1.1;
    canvas.drawRRect(shell, _strokePaint);

    final RRect glassRRect = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset(pos.dx, pos.dy + 1), width: 47, height: 15),
      const Radius.circular(5),
    );
    final Rect glass = glassRRect.outerRect;
    canvas.save();
    canvas.clipRRect(glassRRect);
    // Live horizon roll inside the mirror matching car lean!
    canvas.translate(pos.dx, pos.dy + 1);
    canvas.rotate(-engine.smoothCamBank * 1.4);
    canvas.translate(-pos.dx, -(pos.dy + 1));
    _gradPaint.shader = LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      stops: const [0.0, 0.46, 0.52, 1.0],
      colors: [circuit.skyTop, circuit.skyBottom, const Color(0xFF363E4B), const Color(0xFF1A1F28)],
    ).createShader(glass.inflate(4.0));
    canvas.drawRect(glass.inflate(4.0), _gradPaint);
    // Live moving kerb & white track line reflection inside the mirror!
    final double reflShift = (-engine.carX * 8.0) - (engine.steerAngle * 5.0);
    final bool kerbAlt = ((engine.playerDist / 3.5).floor() % 2 == 0);
    _strokePaint
      ..color = kerbAlt ? circuit.kerbA : Colors.white
      ..strokeWidth = 2.2;
    canvas.drawLine(
      Offset(pos.dx + dir * 8 + reflShift * 0.4, pos.dy + 1.5),
      Offset(pos.dx + dir * 18 + reflShift, glass.bottom + 2),
      _strokePaint,
    );
    // Diagonal anti-glare glass specular streak
    _strokePaint..color = const Color(0x48FFFFFF)..strokeWidth = 2.6;
    canvas.drawLine(Offset(glass.left + 6, glass.top), Offset(glass.left + 16, glass.bottom), _strokePaint);
    if (rivalBehind) {
      _gradPaint.shader = const RadialGradient(
        colors: [Color(0xFFFF526A), Color(0xAAFF1744), Color(0x00FF1744)],
      ).createShader(Rect.fromCircle(center: Offset(pos.dx, pos.dy + 3), radius: 9.0));
      canvas.drawCircle(Offset(pos.dx, pos.dy + 3), 9.0, _gradPaint);
      _fillPaint.color = const Color(0xFFFFE5E8);
      canvas.drawCircle(Offset(pos.dx, pos.dy + 3), 2.9, _fillPaint);
    }
    canvas.restore();
    _strokePaint..color = rivalBehind ? const Color(0xFFFF1744) : const Color(0x88CFD8E6)..strokeWidth = 1.3;
    canvas.drawRRect(glassRRect, _strokePaint);
  }

  void _drawFrontTireUltra(Canvas canvas, Offset center, double tw, double th, bool isLeft) {
    final double steer = engine.steerAngle;
    final double dir = isLeft ? 1.0 : -1.0;
    final bool onKerb = engine.carX.abs() > 0.85 && engine.carX.abs() <= 1.05;
    final double kerbJoltY = (onKerb && engine.speedKmh > 35.0) ? (sin(engine.playerDist * 4.8) * 3.4) : 0.0;

    canvas.save();
    canvas.translate(center.dx, center.dy + kerbJoltY);
    canvas.rotate(steer * 0.24);
    canvas.skew(steer * 0.12, 0.0);

    final RRect tireRect = RRect.fromRectAndRadius(Rect.fromCenter(center: Offset.zero, width: tw, height: th), const Radius.circular(25));

    // Inner Carbon Brake Duct Fairing & Aero Wheel Drum tucked behind inner wheel shoulder!
    final Rect brakeDrum = Rect.fromCenter(center: Offset(dir * tw * 0.44, 0), width: tw * 0.26, height: th * 0.62);
    _fillPaint.color = const Color(0xFF10141C);
    canvas.drawRRect(RRect.fromRectAndRadius(brakeDrum, const Radius.circular(8)), _fillPaint);
    _strokePaint..color = const Color(0x557D90AB)..strokeWidth = 1.4;
    canvas.drawRRect(RRect.fromRectAndRadius(brakeDrum, const Radius.circular(8)), _strokePaint);

    // Exposed outer/inner 3D tire sidewall crescent + metallic wheel-nut spindle when turning sharply!
    final double sideExpose = (steer * dir * 18.0).clamp(-14.0, 16.0).toDouble();
    if (sideExpose.abs() > 1.5) {
      final double sideX = sideExpose > 0 ? (-tw * 0.48) : (tw * 0.48);
      final Rect sideOval = Rect.fromCenter(center: Offset(sideX, 0), width: sideExpose.abs() * 1.4 + 10.0, height: th * 0.88);
      _fillPaint.color = const Color(0xFF0E121A);
      canvas.drawOval(sideOval, _fillPaint);
      final double rollPhase = engine.playerDist / 0.30;
      _strokePaint
        ..color = const Color(0xFFE50914)
        ..strokeWidth = 3.8
        ..strokeCap = StrokeCap.round;
      canvas.drawArc(sideOval.deflate(4.0), rollPhase, 1.35, false, _strokePaint);
      canvas.drawArc(sideOval.deflate(4.0), rollPhase + pi, 1.35, false, _strokePaint);
      // Center metallic wheel nut highlight
      _fillPaint.color = const Color(0xFFAABBD2);
      canvas.drawCircle(Offset(sideX, 0), 3.4, _fillPaint);
    }

    // Real-Life Thermal Carbon Brake Disc Glow (heats smoothly under braking, cools down realistically after release!)
    if (engine.smoothBrakeHeat > 0.08) {
      final double heat = engine.smoothBrakeHeat.clamp(0.0, 1.0).toDouble();
      final Offset discCenter = Offset(isLeft ? tw * 0.47 : -tw * 0.47, 0);
      final double dr = tw * (0.26 + 0.22 * heat);
      _gradPaint.shader = RadialGradient(
        colors: [
          Color.fromARGB((248 * heat).toInt(), 255, 244, 132),
          Color.fromARGB((216 * heat).toInt(), 255, 72, 0),
          const Color(0x00FF3D00),
        ],
      ).createShader(Rect.fromCircle(center: discCenter, radius: dr));
      canvas.drawCircle(discCenter, dr, _gradPaint);
      // Rotating glowing vented carbon brake rotor ring & radial cooling slots!
      final double rotorSpin = engine.playerDist / 0.18;
      _strokePaint
        ..color = Color.fromARGB((185 * heat).toInt(), 255, 224, 130)
        ..strokeWidth = 2.0;
      canvas.drawCircle(discCenter, dr * 0.56, _strokePaint);
      for (int sl = 0; sl < 6; sl++) {
        final double a = rotorSpin + sl * (pi / 3.0);
        canvas.drawLine(
          Offset(discCenter.dx + cos(a) * dr * 0.28, discCenter.dy + sin(a) * dr * 0.28),
          Offset(discCenter.dx + cos(a) * dr * 0.62, discCenter.dy + sin(a) * dr * 0.62),
          _strokePaint,
        );
      }
      if (engine.brakeHeld && heat > 0.52 && engine.speedKmh > 125) {
        final Offset smokeC = Offset(0, -th * 0.42);
        _gradPaint.shader = const RadialGradient(
          colors: [Color(0x6CE8F0F8), Color(0x00E8F0F8)],
        ).createShader(Rect.fromCircle(center: smokeC, radius: tw * 0.46));
        canvas.drawCircle(smokeC, tw * 0.46, _gradPaint);
      }
    }

    // Sculpted 3D Cylindrical Rubber Tread + Live Scrolling Blistered Pirelli Rubber Grain Texture!
    _gradPaint.shader = const LinearGradient(
      begin: Alignment.centerLeft,
      end: Alignment.centerRight,
      stops: [0.0, 0.16, 0.48, 0.80, 1.0],
      colors: [Color(0xFF040508), Color(0xFF222936), Color(0xFF586782), Color(0xFF1B2029), Color(0xFF040508)],
    ).createShader(tireRect.outerRect);
    canvas.drawRRect(tireRect, _gradPaint);

    if (_tireTexPaint != null) {
      canvas.save();
      canvas.clipRRect(tireRect);
      final double rubScrollY = _posMod(engine.playerDist * 48.0, 256.0);
      canvas.translate(0, rubScrollY);
      canvas.drawRect(Rect.fromLTWH(-tw * 0.6, -th * 0.6 - 256.0, tw * 1.2, th * 1.2 + 512.0), _tireTexPaint!);
      canvas.restore();
    }

    // Smooth Velocity-Locked Rolling Tread Bands & Subtle Rubber Grain Lines
    if (engine.speedKmh > 2.0) {
      final double phase = _posMod(engine.playerDist / (pi * 0.62), 1.0);
      for (int b = 0; b < 6; b++) {
        final double yFrac = ((b / 6.0 + phase) % 1.0) - 0.5;
        final double yy = yFrac * th * 0.88;
        final double edgeFade = (1.0 - (yFrac.abs() * 1.9)).clamp(0.0, 1.0).toDouble();
        _strokePaint
          ..color = (b % 2 == 0)
              ? Color.fromARGB((98 * edgeFade).toInt(), 0, 0, 0)
              : Color.fromARGB((58 * edgeFade).toInt(), 215, 228, 248)
          ..strokeWidth = (b % 2 == 0) ? 5.0 : 3.2;
        canvas.drawLine(Offset(-tw * 0.39, yy), Offset(tw * 0.39, yy), _strokePaint);
      }
    }

    // Inner Tire Shoulder Molding
    _strokePaint..color = const Color(0xFF141822)..strokeWidth = 7.2..strokeCap = StrokeCap.round;
    canvas.drawArc(
      Rect.fromCenter(center: Offset(dir * tw * 0.18, -th * 0.04), width: tw * 0.86, height: th * 0.96),
      isLeft ? -pi * 0.34 : pi * 0.66,
      pi * 0.68,
      false,
      _strokePaint,
    );

    // Modern F1 Carbon-Fiber Over-Wheel Aero Brow Winglet mounted over the inner shoulder!
    _scratchPath2
      ..reset()
      ..moveTo(dir * tw * 0.48, -th * 0.36)
      ..quadraticBezierTo(dir * tw * 0.64, -th * 0.18, dir * tw * 0.59, th * 0.06)
      ..lineTo(dir * tw * 0.44, th * 0.04)
      ..quadraticBezierTo(dir * tw * 0.49, -th * 0.16, dir * tw * 0.36, -th * 0.32)
      ..close();
    _fillPaint.color = const Color(0xFF141923);
    canvas.drawPath(_scratchPath2, _fillPaint);
    _strokePaint..color = const Color(0x99B4C8E2)..strokeWidth = 1.6;
    canvas.drawPath(_scratchPath2, _strokePaint);

    // Spinning Pirelli Soft Red Sidewall Marking + White Counter-Tick
    final double pPhase = engine.playerDist / 0.31;
    _strokePaint..color = const Color(0xFFE50914)..strokeWidth = 4.6;
    canvas.drawArc(
      Rect.fromCenter(center: Offset(dir * tw * 0.24, 0), width: tw * 0.48, height: th * 0.72),
      -pi * 0.38 + sin(pPhase) * 0.16,
      pi * 0.52,
      false,
      _strokePaint,
    );
    _strokePaint..color = const Color(0xCCF5F7FA)..strokeWidth = 2.4;
    canvas.drawArc(
      Rect.fromCenter(center: Offset(dir * tw * 0.24, 0), width: tw * 0.48, height: th * 0.72),
      pi * 0.30 + sin(pPhase) * 0.16,
      pi * 0.20,
      false,
      _strokePaint,
    );

    canvas.restore();
  }

  void _drawButterflyWheelUltra(
    Canvas canvas,
    double cx,
    double cy,
    double w,
    double h,
    Paint carbonPaint,
  ) {
    final bool ersOn = engine.ersActive;
    final int rpm = engine.rpm;
    final int gear = engine.gear;
    final double kNow = _kappaAtWorldDist(engine.playerDist).abs();

    canvas.save();
    canvas.translate(cx, cy);
    canvas.rotate(engine.steerAngle * 0.46 + engine.spinYaw * 0.5);

    final double swW = (w * 0.40).clamp(228.0, 360.0).toDouble();
    final double swH = (h * 0.325).clamp(126.0, 192.0).toDouble();

    // Animated Machined Carbon/Titanium Gear Shift Paddles (pull inward subtly on shift!)
    final double pullL = (engine.shiftKickTimer > 0 && !engine.shiftWasUp) ? 4.5 : 0.0;
    final double pullR = (engine.shiftKickTimer > 0 && engine.shiftWasUp) ? -4.5 : 0.0;
    final RRect padL = RRect.fromRectAndRadius(Rect.fromLTWH(-swW * 0.54 + pullL, -swH * 0.27, swW * 0.15, swH * 0.15), const Radius.circular(6));
    final RRect padR = RRect.fromRectAndRadius(Rect.fromLTWH(swW * 0.39 + pullR, -swH * 0.27, swW * 0.15, swH * 0.15), const Radius.circular(6));
    _fillPaint.color = const Color(0xFF242C3B);
    canvas.drawRRect(padL, _fillPaint);
    canvas.drawRRect(padR, _fillPaint);
    _strokePaint..color = const Color(0xB8A6BCD6)..strokeWidth = 1.4;
    canvas.drawRRect(padL, _strokePaint);
    canvas.drawRRect(padR, _strokePaint);

    // Sculpted 3D Carbon Butterfly Chassis Plate (reused _scratchPath2 -> zero alloc!)
    _scratchPath2
      ..reset()
      ..moveTo(-swW * 0.42, -swH * 0.47)
      ..lineTo(-swW * 0.24, -swH * 0.47)
      ..lineTo(-swW * 0.18, -swH * 0.37)
      ..lineTo(swW * 0.18, -swH * 0.37)
      ..lineTo(swW * 0.24, -swH * 0.47)
      ..lineTo(swW * 0.42, -swH * 0.47)
      ..quadraticBezierTo(swW * 0.52, -swH * 0.45, swW * 0.50, -swH * 0.12)
      ..lineTo(swW * 0.47, swH * 0.37)
      ..quadraticBezierTo(swW * 0.44, swH * 0.49, swW * 0.24, swH * 0.47)
      ..lineTo(-swW * 0.24, swH * 0.47)
      ..quadraticBezierTo(-swW * 0.44, swH * 0.49, -swW * 0.47, swH * 0.37)
      ..lineTo(-swW * 0.50, -swH * 0.12)
      ..quadraticBezierTo(-swW * 0.52, -swH * 0.45, -swW * 0.42, -swH * 0.47)
      ..close();

    // Soft ambient shadow behind wheel plate
    canvas.save();
    canvas.translate(0, 5.0);
    _fillPaint.color = const Color(0x78000000);
    canvas.drawPath(_scratchPath2, _fillPaint);
    canvas.restore();

    canvas.drawPath(_scratchPath2, carbonPaint);
    // Subtle top metallic specular lighting sweep across the carbon face
    _gradPaint.shader = const LinearGradient(
      begin: Alignment.topCenter,
      end: Alignment.bottomCenter,
      stops: [0.0, 0.35, 1.0],
      colors: [Color(0x28FFFFFF), Color(0x04FFFFFF), Color(0x45000000)],
    ).createShader(Rect.fromCenter(center: Offset.zero, width: swW, height: swH));
    canvas.drawPath(_scratchPath2, _gradPaint);
    _strokePaint..color = const Color(0xFF7486A3)..strokeWidth = 2.6;
    canvas.drawPath(_scratchPath2, _strokePaint);

    // Perforated Alcantara Side Steering Grips + CNC Machined Metallic Thumb-Wheel Rotaries (DIFF / BMIG)!
    if (_alcantaraPaint != null) {
      for (final double sDir in const [-1.0, 1.0]) {
        final RRect gripR = RRect.fromRectAndRadius(
          Rect.fromCenter(center: Offset(sDir * swW * 0.43, swH * 0.04), width: swW * 0.13, height: swH * 0.66),
          const Radius.circular(12),
        );
        canvas.drawRRect(gripR, _alcantaraPaint!);
      }
    }
    for (final double sDir in const [-1.0, 1.0]) {
      final RRect thumbWheel = RRect.fromRectAndRadius(
        Rect.fromCenter(center: Offset(sDir * swW * 0.33, -swH * 0.42), width: swW * 0.095, height: swH * 0.085),
        const Radius.circular(3.5),
      );
      if (UltraTextures.brushedMetalShader != null) {
        _gradPaint.shader = UltraTextures.brushedMetalShader;
        canvas.drawRRect(thumbWheel, _gradPaint);
      } else {
        _fillPaint.color = const Color(0xFF94A3B8);
        canvas.drawRRect(thumbWheel, _fillPaint);
      }
      _strokePaint..color = const Color(0xAA0D1118)..strokeWidth = 1.2;
      for (int kn = -2; kn <= 2; kn++) {
        final double kx = sDir * swW * 0.33 + kn * 4.2;
        canvas.drawLine(Offset(kx, -swH * 0.46), Offset(kx, -swH * 0.38), _strokePaint);
      }
    }

    // 4 CNC Machined Titanium Hex Bolts at Wheel Faceplate Corners + Recessed Dark-Glass LED Bar Housing!
    _fillPaint.color = const Color(0xFFAABBD2);
    for (final Offset bPos in [
      Offset(-swW * 0.21, -swH * 0.34),
      Offset(swW * 0.21, -swH * 0.34),
      Offset(-swW * 0.21, swH * 0.38),
      Offset(swW * 0.21, swH * 0.38),
    ]) {
      canvas.drawCircle(bPos, 2.3, _fillPaint);
    }
    final RRect ledBezel = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset(0, -swH * 0.29), width: swW * 0.49, height: swH * 0.085),
      const Radius.circular(4.5),
    );
    _fillPaint.color = const Color(0xDD06080D);
    canvas.drawRRect(ledBezel, _fillPaint);
    _strokePaint..color = const Color(0x777E92AE)..strokeWidth = 1.1;
    canvas.drawRRect(ledBezel, _strokePaint);

    // 15-LED Shift Light Bar with Zero-Shader Concentric Bloom (saves 15 GPU shaders/frame!)
    final double rpmRatio = ((rpm - 5800) / 8400.0).clamp(0.0, 1.0).toDouble();
    const int ledCount = 15;
    for (int i = 0; i < ledCount; i++) {
      final bool lit = (i / ledCount) < rpmRatio;
      final Color ledColor = i < 5
          ? const Color(0xFF00E676)
          : (i < 10 ? const Color(0xFFFF1744) : const Color(0xFF2979FF));
      final double lx = -swW * 0.22 + (i * (swW * 0.44 / (ledCount - 1)));
      final Offset lc = Offset(lx, -swH * 0.29);
      if (lit) {
        _fillPaint.color = ledColor.withAlpha(62);
        canvas.drawCircle(lc, 7.2, _fillPaint);
        _fillPaint.color = ledColor.withAlpha(128);
        canvas.drawCircle(lc, 4.6, _fillPaint);
      }
      _fillPaint.color = lit ? ledColor : const Color(0xFF1D232E);
      canvas.drawCircle(lc, 2.9, _fillPaint);
    }

    // Left & Right 3-LED FIA Marshal Flag Strips flanking the OLED Display (zero-shader glow!)
    final Color flagLedCol = engine.startLightsTimer > 0
        ? const Color(0xFFFF1744)
        : (ersOn
            ? const Color(0xFF00E5FF)
            : (kNow > 0.018 ? const Color(0xFFFFD600) : const Color(0xFF00E676)));
    for (final double sDir in const [-1.0, 1.0]) {
      for (int m = 0; m < 3; m++) {
        final Offset mc = Offset(sDir * swW * 0.248, -swH * 0.13 + m * (swH * 0.105));
        _fillPaint.color = flagLedCol.withAlpha(56);
        canvas.drawCircle(mc, 5.8, _fillPaint);
        _fillPaint.color = flagLedCol;
        canvas.drawCircle(mc, 2.3, _fillPaint);
      }
    }

    // High-Contrast Anti-Glare OLED Broadcast Display
    final Rect lcdRect = Rect.fromCenter(center: Offset(0, -swH * 0.01), width: swW * 0.45, height: swH * 0.45);
    _fillPaint.color = const Color(0xFF04060A);
    canvas.drawRRect(RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)), _fillPaint);
    final bool shiftAlert = rpm > 12400 && ((engine.totalRaceTime * 16.0).floor() % 2 == 0);
    if (shiftAlert) {
      _fillPaint.color = const Color(0x482979FF);
      canvas.drawRect(Rect.fromLTWH(lcdRect.left + 2, lcdRect.top + 2, lcdRect.width - 4, lcdRect.height * 0.26), _fillPaint);
    }
    _gradPaint.shader = const LinearGradient(
      begin: Alignment.topLeft,
      end: Alignment.bottomRight,
      stops: [0.0, 0.45, 0.55, 1.0],
      colors: [Color(0x22FFFFFF), Color(0x05FFFFFF), Color(0x00FFFFFF), Color(0x00000000)],
    ).createShader(lcdRect);
    canvas.drawRRect(RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)), _gradPaint);
    _strokePaint..color = ersOn ? const Color(0xFF00E5FF) : (shiftAlert ? const Color(0xFF448AFF) : const Color(0xFF536682))..strokeWidth = 1.8;
    canvas.drawRRect(RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)), _strokePaint);

    // Mini Live G-Force Reticle inside Left-Bottom of OLED Display!
    final Offset gCenter = Offset(-swW * 0.145, swH * 0.045);
    final double gRad = swH * 0.068;
    _strokePaint..color = const Color(0x6694A3B8)..strokeWidth = 1.0;
    canvas.drawCircle(gCenter, gRad, _strokePaint);
    final double gx = (-engine.smoothLatG).clamp(-1.0, 1.0).toDouble();
    final double gy = (engine.smoothLongG).clamp(-1.0, 1.0).toDouble();
    _fillPaint.color = engine.brakeHeld ? const Color(0xFFFF1744) : const Color(0xFF00E5FF);
    canvas.drawCircle(Offset(gCenter.dx + gx * gRad * 0.72, gCenter.dy + gy * gRad * 0.72), 2.4, _fillPaint);

    // Live 4-Tire Thermal Telemetry Mini-Icons inside Right-Bottom of OLED Display!
    final double tHeat = engine.smoothTireHeat.clamp(0.0, 1.0).toDouble();
    final Color tireCol = tHeat < 0.62
        ? Color.lerp(const Color(0xFF00E676), const Color(0xFFFFD600), ((tHeat - 0.30) / 0.32).clamp(0.0, 1.0).toDouble())!
        : Color.lerp(const Color(0xFFFFD600), const Color(0xFFFF3D00), ((tHeat - 0.62) / 0.38).clamp(0.0, 1.0).toDouble())!;
    _fillPaint.color = tireCol;
    for (final Offset tOff in [
      Offset(swW * 0.118, swH * 0.010),
      Offset(swW * 0.168, swH * 0.010),
      Offset(swW * 0.118, swH * 0.068),
      Offset(swW * 0.168, swH * 0.068),
    ]) {
      canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: tOff, width: 4.2, height: 7.2), const Radius.circular(1.2)), _fillPaint);
    }

    _drawCenteredText(canvas, '$gear', Offset(0, -swH * 0.025), swH * 0.225, shiftAlert ? const Color(0xFF80D8FF) : Colors.white, FontWeight.w900);
    _drawCenteredText(canvas, '${engine.speedKmh.toInt()}', Offset(-swW * 0.145, -swH * 0.13), swH * 0.102, const Color(0xFF00E676), FontWeight.w900);
    _drawCenteredText(canvas, engine.phase == SessionPhase.qualifying ? 'Q1' : 'P${engine.currentPosition}', Offset(swW * 0.145, -swH * 0.13), swH * 0.09, const Color(0xFFFFD54F), FontWeight.w900);
    _drawCenteredText(
      canvas,
      ersOn ? 'ERS BOOST' : (engine.playerInSlipstream ? 'SLIPSTREAM' : '${(rpm ~/ 100) * 100} RPM'),
      Offset(0, swH * 0.11),
      swH * 0.075,
      ersOn ? const Color(0xFF00E5FF) : (engine.playerInSlipstream ? const Color(0xFF69F0AE) : const Color(0xFF94A3B8)),
      FontWeight.bold,
    );

    // Live Dual OLED Telemetry Bars: ERS Charge (bottom) + Live Brake Pressure / Throttle Bar (just above!)
    final double barW = lcdRect.width - 12;
    _fillPaint.color = const Color(0xFF1E293B);
    canvas.drawRect(Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 11.5, barW, 3.0), _fillPaint);
    if (engine.brakeHeld && engine.brakePressure > 0.01) {
      _fillPaint.color = const Color(0xFFFF1744);
      canvas.drawRect(Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 11.5, barW * engine.brakePressure.clamp(0.0, 1.0).toDouble(), 3.0), _fillPaint);
    } else if (engine.gasHeld) {
      _fillPaint.color = const Color(0xFF00E676);
      canvas.drawRect(Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 11.5, barW, 3.0), _fillPaint);
    }
    _fillPaint.color = const Color(0xFF1E293B);
    canvas.drawRect(Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 6, barW, 3.4), _fillPaint);
    _fillPaint.color = ersOn ? const Color(0xFF00E5FF) : const Color(0xFFFFD600);
    canvas.drawRect(Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 6, barW * (engine.ersCharge / 100.0), 3.4), _fillPaint);

    // Anodized F1 Rotary Encoders with Brushed Metal Knurled Bezels & White Position Pointer Ticks
    const List<Color> knobColors = [Color(0xFFE53935), Color(0xFF43A047), Color(0xFFFFB300)];
    for (int k = 0; k < 3; k++) {
      final double kx = (k - 1) * (swW * 0.115);
      final Offset kc = Offset(kx, swH * 0.34);
      final double kr = swH * 0.088;
      if (UltraTextures.brushedMetalShader != null) {
        _gradPaint.shader = UltraTextures.brushedMetalShader;
        canvas.drawCircle(kc, kr, _gradPaint);
      } else {
        _fillPaint.color = const Color(0xFF94A3B8);
        canvas.drawCircle(kc, kr, _fillPaint);
      }
      _fillPaint.color = knobColors[k];
      canvas.drawCircle(kc, swH * 0.072, _fillPaint);
      _fillPaint.color = const Color(0xFF13171F);
      canvas.drawCircle(kc, swH * 0.032, _fillPaint);
      _strokePaint..color = const Color(0xEEFFFFFF)..strokeWidth = 1.6;
      final double tickAng = -pi * 0.65 + k * 0.55;
      canvas.drawLine(kc, Offset(kc.dx + cos(tickAng) * kr * 0.78, kc.dy + sin(tickAng) * kr * 0.78), _strokePaint);
    }

    // Backlit F1 Steering Wheel Function Buttons with Authentic Micro-Labels
    _drawWheelButton(canvas, Offset(-swW * 0.33, -swH * 0.24), const Color(0xFF29B6F6), 'DRS');
    _drawWheelButton(canvas, Offset(swW * 0.33, -swH * 0.24), const Color(0xFFFFCA28), 'OVT');
    _drawWheelButton(canvas, Offset(-swW * 0.31, -swH * 0.04), const Color(0xFFEF5350), 'RAD');
    _drawWheelButton(canvas, Offset(swW * 0.31, -swH * 0.04), const Color(0xFF66BB6A), 'PIT');
    _drawWheelButton(canvas, Offset(-swW * 0.29, swH * 0.16), const Color(0xFFAB47BC), 'BB');
    _drawWheelButton(canvas, Offset(swW * 0.29, swH * 0.16), const Color(0xFFFF7043), 'DIF');

    _drawRacingGloveUltra(canvas, swW, swH, true);
    _drawRacingGloveUltra(canvas, swW, swH, false);

    canvas.restore();
  }

  void _drawWheelButton(Canvas canvas, Offset center, Color color, String label) {
    _fillPaint.color = color.withAlpha(52);
    canvas.drawCircle(center, 9.6, _fillPaint);
    _fillPaint.color = const Color(0xFF0D1016);
    canvas.drawCircle(center, 6.6, _fillPaint);
    _fillPaint.color = color;
    canvas.drawCircle(center, 4.8, _fillPaint);
    _fillPaint.color = const Color(0xBBFFFFFF);
    canvas.drawCircle(Offset(center.dx - 1.3, center.dy - 1.3), 1.5, _fillPaint);
    final TextPainter tp = _getCachedBoardText(label, 6.0, const Color(0xCCF0F6FF));
    tp.paint(canvas, Offset(center.dx - tp.width * 0.5, center.dy + 7.2));
  }

