    final RRect knucklePad = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset(s * swW * 0.45 + gripOffset, swH * 0.07), width: swW * 0.165, height: swH * 0.115),
      const Radius.circular(6),
