    _strokePaint..color = const Color(0x48FFFFFF)..strokeWidth = 1.7;
    canvas.drawLine(Offset(s * swW * 0.41 + gripOffset, swH * 0.14), Offset(s * swW * 0.49 + gripOffset, swH * 0.30), _strokePaint);
    canvas.drawLine(Offset(s * swW * 0.46 + gripOffset, swH * 0.15), Offset(s * swW * 0.52 + gripOffset, swH * 0.29), _strokePaint);
    _strokePaint..color = livery.secondary.withAlpha(225)..strokeWidth = 3.2;
    canvas.drawLine(Offset(s * swW * 0.37 + gripOffset, swH * 0.36), Offset(s * swW * 0.53 + gripOffset, swH * 0.36), _strokePaint);
  }

  void _drawCenteredText(Canvas canvas, String text, Offset center, double fontSize, Color color, FontWeight weight) {
    final int fsBucket = fontSize.round().clamp(6, 48).toInt();
    final String key = '${text}_${fsBucket}_${color.hashCode}_${weight.index}';
    if (_wheelTextCache.length > 280) {
      _wheelTextCache.clear();
    }
    final TextPainter tp = _wheelTextCache.putIfAbsent(key, () {
      return TextPainter(
        text: TextSpan(text: text, style: TextStyle(color: color, fontSize: fsBucket.toDouble(), fontWeight: weight)),
        textDirection: TextDirection.ltr,
      )..layout();
    });
    tp.paint(canvas, Offset(center.dx - tp.width * 0.5, center.dy - tp.height * 0.5));
  }

  @override
  bool shouldRepaint(covariant F1UltraSmoothPainter oldDelegate) => false;
